    const groundMat = standardMaterial(0x1e293b, { roughness: 0.8 });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.01;
    ground.receiveShadow = true;
    ts!.group.add(ground);

    const grid = new THREE.GridHelper(30, 60, 0x334155, 0x1e293b);
    ts!.group.add(grid);

    // Central pivot
    const pivotGeo = new THREE.CylinderGeometry(0.3, 0.3, 1, 16);
    const pivotMat = standardMaterial(0xfbbf24, { metalness: 0.8, emissive: 0xfbbf24, emissiveIntensity: 0.3 });
    const pivot = new THREE.Mesh(pivotGeo, pivotMat);
    pivot.position.y = 0.5;
    pivot.castShadow = true;
    ts!.group.add(pivot);

    // Rotating arm
    const armGroup = new THREE.Group();
    const armGeo = new THREE.CylinderGeometry(0.1, 0.1, radius, 16);
    const armMat = standardMaterial(0x6366f1, { metalness: 0.5 });
    const arm = new THREE.Mesh(armGeo, armMat);
    arm.rotation.x = Math.PI / 2;
    arm.castShadow = true;
    armGroup.add(arm);
    armGroup.position.y = 0.5;
    ts!.group.add(armGroup);

    // Mass at the end
    const massGroup = new THREE.Group();
    const massGeo = new THREE.SphereGeometry(mass * 0.3, 16, 16);
    const massMat = standardMaterial(0xef4444, { emissive: 0xef4444, emissiveIntensity: 0.3 });
    const massObj = new THREE.Mesh(massGeo, massMat);
    massObj.castShadow = true;
    massGroup.add(massObj);
    massGroup.position.x = radius;
    armGroup.add(massGroup);

    // Circular path
    let pathCircle: THREE.Line | null = null;
    let velocityArrow: THREE.ArrowHelper | null = null;
    let accelerationArrow: THREE.ArrowHelper | null = null;
    let forceArrow: THREE.ArrowHelper | null = null;
    let radiusArrow: THREE.ArrowHelper | null = null;

    const startTime = performance.now();

    function updateScene() {
      if (!ts) return;

      // Clear previous objects
      if (pathCircle) { ts!.group.remove(pathCircle); pathCircle.geometry.dispose(); }
      if (velocityArrow) ts!.group.remove(velocityArrow);
      if (accelerationArrow) ts!.group.remove(accelerationArrow);
      if (forceArrow) ts!.group.remove(forceArrow);
      if (radiusArrow) ts!.group.remove(radiusArrow);

      const elapsed = (performance.now() - startTime) / 1000;
      const angle = elapsed * angularVelocity;

      // Rotate arm
      armGroup.rotation.z = angle;

      // Create circular path
      const points: THREE.Vector3[] = [];
      const steps = 64;
      for (let i = 0; i <= steps; i++) {
        const theta = (i / steps) * Math.PI * 2;
        points.push(new THREE.Vector3(radius * Math.cos(theta), 0.5, radius * Math.sin(theta)));
      }
      const geometry = new THREE.BufferGeometry().setFromPoints(points);
      const material = new THREE.LineBasicMaterial({ color: 0x3b82f6, transparent: true, opacity: 0.5 });
      pathCircle = new THREE.Line(geometry, material);
      ts!.group.add(pathCircle);

      // Current position
      const x = radius * Math.cos(angle);
      const z = radius * Math.sin(angle);

      // Velocity vector (tangential)
      if (showVectors) {
        const velX = -Math.sin(angle);
        const velZ = Math.cos(angle);
        velocityArrow = new LiveLeaderLine(
          new THREE.Vector3(velX, 0, velZ),
          new THREE.Vector3(x, 0.5, z),
          linearVelocity * 0.3,
          0x22c55e
        );
        ts!.group.add(velocityArrow);

        // Acceleration vector (centripetal, towards center)
        const accX = -x / radius;
        const accZ = -z / radius;
        accelerationArrow = new LiveLeaderLine(
          new THREE.Vector3(accX, 0, accZ),
          new THREE.Vector3(x, 0.5, z),
          centripetalAcceleration * 0.3,
          0xef4444
        );
        ts!.group.add(accelerationArrow);

        // Force vector
        if (showTorque) {
          forceArrow = new LiveLeaderLine(
            new THREE.Vector3(accX, 0, accZ),
            new THREE.Vector3(x, 0.5, z),
            centripetalForce * 0.03,
            0xfbbf24
          );
          ts!.group.add(forceArrow);

          // Radius vector
          radiusArrow = new LiveLeaderLine(
            new THREE.Vector3(-x, 0, -z),
            new THREE.Vector3(0, 0.5, 0),
            radius,
            0xffffff
          );
          ts!.group.add(radiusArrow);
        }
      }

      ts!.controls.update();
      ts!.renderer.render(ts!.scene, ts!.camera);
    }


    updateRef.current = (time) => {
    updateScene();
    };
  }, [radius, angularVelocity, mass, showVectors, showTorque]);


  return (
    <Card className="w-full">
      <CardHeader>
        <CardTitle>Class 11 Rotational Motion</CardTitle>
        <CardDescription>
          Interactive 3D visualization of circular motion, centripetal force, and angular kinematics.
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-6">
        <div ref={mountRef} className="w-full h-96 bg-gray-100 rounded-lg" />

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="space-y-4">
            <div>
              <Label>Radius r (m)</Label>
              <Slider min={1} max={10} step={0.5} value={[radius]} onValueChange={(v) => setRadius(v[0])} />
              <p className="text-sm text-gray-500">Current: {radius} m</p>
            </div>
            <div>
              <Label>Angular Velocity ω (rad/s)</Label>
              <Slider min={0.5} max={5} step={0.1} value={[angularVelocity]} onValueChange={(v) => setAngularVelocity(v[0])} />
              <p className="text-sm text-gray-500">Current: {angularVelocity} rad/s</p>
            </div>
            <div>
              <Label>Mass m (kg)</Label>
              <Slider min={0.5} max={5} step={0.5} value={[mass]} onValueChange={(v) => setMass(v[0])} />
              <p className="text-sm text-gray-500">Current: {mass} kg</p>
            </div>
            <div className="flex gap-2">
              <button
                onClick={() => setShowVectors(!showVectors)}
                className={`px-3 py-2 rounded-md text-xs font-medium ${showVectors ? 'bg-primary/20 text-primary' : 'bg-muted/50 text-muted-foreground'}`}
              >
                Vectors: {showVectors ? 'ON' : 'OFF'}
              </button>
              <button
                onClick={() => setShowTorque(!showTorque)}
                className={`px-3 py-2 rounded-md text-xs font-medium ${showTorque ? 'bg-primary/20 text-primary' : 'bg-muted/50 text-muted-foreground'}`}
              >
                Force: {showTorque ? 'ON' : 'OFF'}
              </button>
            </div>
          </div>

          <div className="space-y-4">
            <div className="rounded-md border border-border bg-muted/30 p-3 text-sm space-y-2">
              <p><span className="font-semibold">Calculations (Class 11):</span></p>
              <p className="text-green-600">Linear Velocity: v = rω = {linearVelocity.toFixed(2)} m/s</p>
              <p className="text-red-600">Centripetal Accel: a_c = rω² = {centripetalAcceleration.toFixed(2)} m/s²</p>
              <p className="text-orange-600">Centripetal Force: F_c = ma_c = {centripetalForce.toFixed(2)} N</p>
              <p className="text-blue-600">Period: T = 2π/ω = {period.toFixed(2)} s</p>
              <p className="text-purple-600">Frequency: f = ω/2π = {frequency.toFixed(2)} Hz</p>
              <p className="text-yellow-600">Moment of Inertia: I = mr² = {momentOfInertia.toFixed(2)} kg·m²</p>
            </div>

            <div>
              <h3 className="font-semibold">Rotational Motion Concepts</h3>
              <p className="text-sm mt-2">
                In circular motion, a body moves along the circumference of a circle or circular path.
              </p>
              <div className="text-sm mt-3 space-y-2">
                <p><strong>Angular Displacement:</strong> θ = s/r (in radians)</p>
                <p><strong>Angular Velocity:</strong> ω = Δθ/Δt = v/r</p>
                <p><strong>Angular Acceleration:</strong> α = Δω/Δt</p>
                <p><strong>Relation:</strong> v = rω, a_t = rα</p>
                <p><strong>Centripetal Acceleration:</strong> a_c = v²/r = rω² (always towards center)</p>
                <p><strong>Centripetal Force:</strong> F_c = mv²/r = mω²r</p>
                <p><strong>Period:</strong> T = 2πr/v = 2π/ω</p>
                <p><strong>Frequency:</strong> f = 1/T = ω/2π</p>
              </div>
            </div>

            <div>
              <h3 className="font-semibold">Key Points</h3>
              <ul className="text-sm mt-2 list-disc pl-5 space-y-1">
                <li>Centripetal force is <strong>not</strong> a new type of force - it's the resultant of actual forces (tension, friction, gravity, etc.)</li>
                <li>Centripetal force acts <strong>towards</strong> the center of the circular path</li>
                <li>Without centripetal force, the body would move in a straight line (tangent to the circle)</li>
                <li>The velocity vector is always <strong>tangent</strong> to the circular path</li>
                <li>For uniform circular motion: speed is constant, but velocity is not (direction changes)</li>
                <li><strong>Banked Road:</strong> tanθ = v²/(rg) where θ is the banking angle</li>
                <li><strong>Death Well:</strong> Normal reaction provides centripetal force at different points</li>
              </ul>
            </div>

            <div className="rounded-md border border-border bg-muted/30 p-3">
              <p className="text-xs text-muted-foreground">Legend:</p>
              <div className="flex items-center gap-4 mt-2 text-xs flex-wrap">
                <div className="flex items-center gap-1"><div className="w-3 h-3 bg-yellow-400"></div><span>Pivot</span></div>
                <div className="flex items-center gap-1"><div className="w-3 h-1 bg-blue-500"></div><span>Arm</span></div>
                <div className="flex items-center gap-1"><div className="w-3 h-3 bg-red-500 rounded-full"></div><span>Mass</span></div>
                <div className="flex items-center gap-1"><div className="w-3 h-0.5 bg-blue-500"></div><span>Path</span></div>
                <div className="flex items-center gap-1"><div className="w-3 h-0.5 bg-green-500"></div><span>Velocity Vector</span></div>
                <div className="flex items-center gap-1"><div className="w-3 h-0.5 bg-red-500"></div><span>Centripetal Accel</span></div>
                <div className="flex items-center gap-1"><div className="w-3 h-0.5 bg-yellow-500"></div><span>Centripetal Force</span></div>
              </div>
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
  );
};

export default Class11RotationalMotion;

"use client";

import { useState, useRef, useEffect, useMemo } from "react";
import * as THREE from "three";
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import Slider from "@/components/ui/slider";
import { isWebGLAvailable } from "@/lib/webgl";
import {
  disposeThreeScene,
  standardMaterial,
  clearGroup,
  type ThreeScene,
  createThreeScene,
  bindResize,
} from "@/components/lab/three-scene";

export const Class11WorkEnergy: React.FC = () => {
  const mountRef = useRef<HTMLDivElement>(null);
  const tsRef = useRef<ThreeScene | null>(null);
  const updateRef = useRef<((time: number) => void) | null>(null);
  const [mass, setMass] = useState(2);
  const [height, setHeight] = useState(5);
  const [velocity, setVelocity] = useState(4);
  const [springConstant, setSpringConstant] = useState(100);
  const [compression, setCompression] = useState(0.5);
  const [showWork, setShowWork] = useState(true);

  // Calculated quantities
  const gravitationalPE = useMemo(() => mass * 9.8 * height, [mass, height]);
  const kineticEnergy = useMemo(() => 0.5 * mass * velocity * velocity, [mass, velocity]);
  const springPE = useMemo(() => 0.5 * springConstant * compression * compression, [springConstant, compression]);
  const totalEnergy = useMemo(() => gravitationalPE + kineticEnergy + springPE, [gravitationalPE, kineticEnergy, springPE]);

  // Scene lifecycle - mount/unmount only
  useEffect(() => {
    if (!mountRef.current || !isWebGLAvailable()) return;
    const ts = createThreeScene(mountRef.current, {
          cameraPosition: new THREE.Vector3(12, 12, 15),
          autoRotate: true,
          autoRotateSpeed: 0.25,
          background: 0x0f172a
        });
    tsRef.current = ts;
    const unbind = bindResize(ts);
    let rafId = 0;
    function animate() {
      rafId = requestAnimationFrame(animate);
      const time = performance.now() / 1000;
      updateRef.current?.(time);
      ts!.controls.update();
      ts!.renderer.render(ts!.scene, ts!.camera);
    }
    animate();
    return () => { cancelAnimationFrame(rafId); unbind(); disposeThreeScene(ts); tsRef.current = null; };
  }, []);

  // Rebuild 3D content on state change
  useEffect(() => {
    let labelRenderer: any;
    let leaderLayer: any;
    const ts = tsRef.current;
    if (!ts) return;
    clearGroup(ts!.group);

const labelMaterials: THREE.SpriteMaterial[] = [];

        // Ground
        const groundGeo = new THREE.PlaneGeometry(30, 30);
        const groundMat = standardMaterial(0x1e293b, { roughness: 0.8 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.position.y = -0.01;
        ground.receiveShadow = true;
        ts!.group.add(ground);

        const grid = new THREE.GridHelper(30, 60, 0x334155, 0x1e293b);
        ts!.group.add(grid);

        // Platform at height
        const platformGeo = new THREE.BoxGeometry(8, 0.3, 8);
        const platformMat = standardMaterial(0x6366f1, { metalness: 0.3 });
        const platform = new THREE.Mesh(platformGeo, platformMat);
        platform.position.y = height;
        platform.receiveShadow = true;
        ts!.group.add(platform);

        // Mass (ball)
        const ballGroup = new THREE.Group();
        const ballGeo = new THREE.SphereGeometry(0.5, 32, 32);
        const ballMat = standardMaterial(0xef4444, { emissive: 0xef4444, emissiveIntensity: 0.3 });
        const ball = new THREE.Mesh(ballGeo, ballMat);
        ball.castShadow = true;
        ballGroup.add(ball);
        ballGroup.position.set(0, height + 0.5, 0);
        ts!.group.add(ballGroup);

        // Spring
        const springGroup = new THREE.Group();
        const springGeo = new THREE.CylinderGeometry(0.2, 0.2, compression, 32);
        const springMat = standardMaterial(0x22c55e, { metalness: 0.5 });
        const spring = new THREE.Mesh(springGeo, springMat);
        spring.castShadow = true;
        springGroup.add(spring);
        springGroup.position.set(5, 0.5, 0);
        ts!.group.add(springGroup);

        // Base for spring
        const baseGeo = new THREE.BoxGeometry(3, 0.2, 3);
        const baseMat = standardMaterial(0xfbbf24, { metalness: 0.4 });
        const base = new THREE.Mesh(baseGeo, baseMat);
        base.position.set(5, 0.1, 0);
        ts!.group.add(base);

        // Energy visualization bars
        const barWidth = 0.5;
        const barHeightPE = gravitationalPE * 0.1;
        const barHeightKE = kineticEnergy * 0.1;
        const barHeightSpring = springPE * 0.1;

        // PE bar
        const peBarGeo = new THREE.BoxGeometry(barWidth, barHeightPE, barWidth);
        const peBarMat = standardMaterial(0x3b82f6, { transparent: true, opacity: 0.8 });
        const peBar = new THREE.Mesh(peBarGeo, peBarMat);
        peBar.position.set(-6, barHeightPE / 2, 0);
        ts!.group.add(peBar);

        // KE bar
        const keBarGeo = new THREE.BoxGeometry(barWidth, barHeightKE, barWidth);
        const keBarMat = standardMaterial(0x22c55e, { transparent: true, opacity: 0.8 });
        const keBar = new THREE.Mesh(keBarGeo, keBarMat);
        keBar.position.set(-3, barHeightKE / 2, 0);
        ts!.group.add(keBar);

        // Spring PE bar
        const springBarGeo = new THREE.BoxGeometry(barWidth, barHeightSpring, barWidth);
        const springBarMat = standardMaterial(0xfbbf24, { transparent: true, opacity: 0.8 });
        const springBar = new THREE.Mesh(springBarGeo, springBarMat);
        springBar.position.set(0, barHeightSpring / 2, 0);
        ts!.group.add(springBar);

        // Energy labels as sprites above each bar. Materials/textures are tracked so
        // they can be disposed on unmount (CanvasTexture isn't freed by disposeThreeScene).
        const makeLabel = (text: string, color: string): THREE.Sprite => {
          const canvas = document.createElement("canvas");
          canvas.width = 256;
          canvas.height = 64;
          const ctx = canvas.getContext("2d");
          if (ctx) {
            ctx.font = "bold 36px system-ui, sans-serif";
            ctx.textAlign = "center";
            ctx.textBaseline = "middle";
            ctx.fillStyle = "rgba(0,0,0,0.75)";
            ctx.fillRect(0, 0, canvas.width, canvas.height);
            ctx.fillStyle = color;
            ctx.fillText(text, canvas.width / 2, canvas.height / 2);
          }
          const texture = new THREE.CanvasTexture(canvas);
          texture.minFilter = THREE.LinearFilter;
          const spriteMat = new THREE.SpriteMaterial({ map: texture, transparent: true, depthWrite: false });
          labelMaterials.push(spriteMat);
          const sprite = new THREE.Sprite(spriteMat);
          sprite.scale.set(3.2, 0.8, 1);
          return sprite;
        };

        const peLabel = makeLabel("PE", "#3b82f6");
        peLabel.position.set(-6, barHeightPE + 1, 0);
        ts!.group.add(peLabel);

        const keLabel = makeLabel("KE", "#22c55e");
        keLabel.position.set(-3, barHeightKE + 1, 0);
        ts!.group.add(keLabel);

        const springLabel = makeLabel("SE", "#fbbf24");
        springLabel.position.set(0, barHeightSpring + 1, 0);
        ts!.group.add(springLabel);

        const startTime = performance.now();
        let falling = false;
        let fallStartTime = 0;
        const ballOriginalY = height + 0.5;

        function updateScene() {
          if (!ts) return;

          const elapsed = (performance.now() - startTime) / 1000;
          
          // Animate ball falling and bouncing
          if (elapsed > 2 && !falling) {
            falling = true;
            fallStartTime = elapsed;
          }

          if (falling) {
            const fallTime = elapsed - fallStartTime;
            const fallHeight = 0.5 * 9.8 * fallTime * fallTime;
            if (ballGroup.position.y > 0.5) {
              ballGroup.position.y = ballOriginalY - fallHeight;
            } else {
              // Bounce
              ballGroup.position.y = 0.5 + Math.abs(Math.sin(elapsed * 10)) * 2;
            }
          }

          // Animate spring compression
          spring.scale.y = compression;
          spring.position.y = 0.1 + compression / 2;

          // Rotate ball
          ballGroup.rotation.y += 0.02;

          // Update energy bars
          peBar.scale.y = gravitationalPE * 0.1;
          peBar.position.y = peBar.scale.y / 2;

          keBar.scale.y = kineticEnergy * 0.1;
          keBar.position.y = keBar.scale.y / 2;

          springBar.scale.y = springPE * 0.1;
          springBar.position.y = springBar.scale.y / 2;

          // Keep labels riding on top of their bars
          peLabel.position.y = peBar.position.y + peBar.scale.y / 2 + 0.8;
          keLabel.position.y = keBar.position.y + keBar.scale.y / 2 + 0.8;
          springLabel.position.y = springBar.position.y + springBar.scale.y / 2 + 0.8;

          ts!.controls.update();
          ts!.renderer.render(ts!.scene, ts!.camera);
        }


    updateRef.current = (time: number) => {
    updateScene();
    };
  }, [mass, height, velocity, springConstant, compression, showWork]);


  return (
    <Card className="w-full">
      <CardHeader>
        <CardTitle>Class 11 Work, Energy and Power</CardTitle>
        <CardDescription>
          Interactive 3D visualization of work-energy theorem and conservation of energy.
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-6">
        <div ref={mountRef} className="w-full h-96 bg-black rounded-lg" />

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="space-y-4">
            <div>
              <Label>Mass m (kg)</Label>
              <Slider min={1} max={10} step={0.5} value={[mass]} onValueChange={(v) => setMass(v[0])} />
              <p className="text-sm text-gray-500">Current: {mass} kg</p>
            </div>
            <div>
              <Label>Height h (m)</Label>
              <Slider min={1} max={15} step={0.5} value={[height]} onValueChange={(v) => setHeight(v[0])} />
              <p className="text-sm text-gray-500">Current: {height} m</p>
            </div>
            <div>
              <Label>Velocity v (m/s)</Label>
              <Slider min={0} max={10} step={0.5} value={[velocity]} onValueChange={(v) => setVelocity(v[0])} />
              <p className="text-sm text-gray-500">Current: {velocity} m/s</p>
            </div>
            <div>
              <Label>Spring Constant k (N/m)</Label>
              <Slider min={10} max={500} step={10} value={[springConstant]} onValueChange={(v) => setSpringConstant(v[0])} />
              <p className="text-sm text-gray-500">Current: {springConstant} N/m</p>
            </div>
            <div>
              <Label>Compression x (m)</Label>
              <Slider min={0} max={1} step={0.05} value={[compression]} onValueChange={(v) => setCompression(v[0])} />
              <p className="text-sm text-gray-500">Current: {compression} m</p>
            </div>
            <div className="flex gap-2">
              <button
                onClick={() => setShowWork(!showWork)}
                className={`px-3 py-2 rounded-md text-xs font-medium ${showWork ? 'bg-primary/20 text-primary' : 'bg-muted/50 text-muted-foreground'}`}
              >
                Energy Bars: {showWork ? 'ON' : 'OFF'}
              </button>
            </div>
          </div>

          <div className="space-y-4">
            <div className="rounded-md border border-border bg-muted/30 p-3 text-sm space-y-2">
              <p><span className="font-semibold">Energy Calculations:</span></p>
              <p className="text-blue-600">Potential Energy: PE = mgh = {gravitationalPE.toFixed(2)} J</p>
              <p className="text-green-600">Kinetic Energy: KE = ½mv² = {kineticEnergy.toFixed(2)} J</p>
              <p className="text-yellow-600">Spring Energy: SE = ½kx² = {springPE.toFixed(2)} J</p>
              <p className="text-purple-600 font-semibold">Total Energy: {totalEnergy.toFixed(2)} J</p>
            </div>

            <div>
              <h3 className="font-semibold">Work-Energy Theorem</h3>
              <p className="text-sm mt-2">
                The work done by all forces (conservative and non-conservative) on a body equals the change in its kinetic energy.
              </p>
              <div className="text-sm mt-3 space-y-2">
                <p><strong>Work Done:</strong> W = F·s·cosθ</p>
                <p><strong>Potential Energy:</strong> PE = mgh (gravitational)</p>
                <p><strong>Kinetic Energy:</strong> KE = ½mv²</p>
                <p><strong>Spring Energy:</strong> SE = ½kx²</p>
                <p><strong>Conservation:</strong> Total mechanical energy is conserved when only conservative forces act.</p>
                <p><strong>Power:</strong> P = W/t = F·v</p>
              </div>
            </div>

            <div>
              <h3 className="font-semibold">Key Concepts</h3>
              <ul className="text-sm mt-2 list-disc pl-5 space-y-1">
                <li><strong>Work:</strong> Transfer of energy when force acts through a displacement</li>
                <li><strong>Positive Work:</strong> Force and displacement in same direction</li>
                <li><strong>Negative Work:</strong> Force and displacement in opposite directions</li>
                <li><strong>Conservative Forces:</strong> Work done is independent of path (gravity, spring)</li>
                <li><strong>Non-conservative Forces:</strong> Work done depends on path (friction)</li>
                <li><strong>Energy Conservation:</strong> Energy cannot be created or destroyed, only transformed</li>
              </ul>
            </div>

            <div className="rounded-md border border-border bg-muted/30 p-3">
              <p className="text-xs text-muted-foreground">Legend:</p>
              <div className="flex items-center gap-4 mt-2 text-xs flex-wrap">
