"use client";

/**
 * SYMBOLS AT THEIR EXACT PLACE — Physics · Atomic & Quantum.
 * The Bohr model labels n, rₙ, Eₙ and the photon hν at their exact places,
 * showing how an electron jumps between allowed orbits.
 */

import { useState, useRef, useEffect } from "react";
import * as THREE from "three";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Slider } from "@/components/ui/slider";
import { Button } from "@/components/ui/button";
import { isWebGLAvailable } from "@/lib/webgl";
import { TheoryPanel } from "@/components/lab/theory-panel";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  createThreeScene,
  bindResize,
  disposeThreeScene,
  standardMaterial,
  titleText,
  clearGroup,
  type ThreeScene,
} from "@/components/lab/three-scene";
import { createLabelSystem, LabelDef, SceneArea, GuidePanel } from "@/components/lab/label3d";

function BohrAtom3D() {
  const mount = useRef<HTMLDivElement>(null);
  const updateRef = useRef<((time: number) => void) | null>(null);
  const tsRef = useRef<ThreeScene | null>(null);
  const [webgl] = useState(() => typeof window !== "undefined" && isWebGLAvailable());
  const [n, setN] = useState(2);
  const [Z, setZ] = useState(1);

  const r1 = 1.4 * Z; // first Bohr radius (scene units)
  const rN = r1 * n * n;
  const EN = -(13.6 * Z * Z) / (n * n);
  const r1m = 0.529e-10; // m
  const rNm = r1m * n * n / Z; // metres

  const defs: LabelDef[] = [
    { x: 0, y: 0, z: 0, symbol: "+Ze", name: "Nucleus", desc: "Contains Z protons; much heavier than orbiting electrons.", color: "#ef4444" },
    { x: rN + 1.1, y: 0.4, z: 0, symbol: "rₙ = r₁·n²", name: "Orbit radius", desc: "Allowed radii scale as n²; only these discrete orbits are stable.", color: "#22d3ee" },
    { x: r1 + 0.5, y: 1.4, z: 0, symbol: "n = " + n, name: "Principal quantum number", desc: "Integer shell index; bigger n ⇒ bigger rₙ, higher (less negative) Eₙ.", color: "#38bdf8" },
    { x: -1.5, y: 3.2, z: 0, symbol: "Eₙ = −13.6Z²/n²", name: "Energy level", desc: "Energy " + EN.toFixed(2) + " eV · quantized, not continuous.", color: "#fbbf24" },
    { x: 0, y: 4.4, z: 0, symbol: "hν = E₂ − E₁", name: "Photon", desc: "A photon of exactly the level gap is absorbed or emitted in a jump.", color: "#a78bfa" },
  ];

  // Scene lifecycle - mount/unmount only
  useEffect(() => {
    if (!mount.current || !isWebGLAvailable()) return;
    const ts = createThreeScene(mount.current, { cameraPosition: new THREE.Vector3(0, 6, 13), autoRotate: true, autoRotateSpeed: 0.5, background: 0x0b1220 });
    tsRef.current = ts;
    const unbind = bindResize(ts);
    let rafId = 0;
    function animate() {
      rafId = requestAnimationFrame(animate);
      const time = performance.now() / 1000;
      updateRef.current?.(time);
      ts!.controls.update();
      ts!.renderer.render(ts!.scene, ts!.camera);
    }
    animate();
    return () => { cancelAnimationFrame(rafId); unbind(); disposeThreeScene(ts); tsRef.current = null; };
  }, []);

  // Rebuild 3D content on state change
  useEffect(() => {(async () => {
    const ts = tsRef.current;
    if (!ts) return;
    clearGroup(ts!.group);

let electron: THREE.Mesh | null = null;
let sys: any = null;
const el = mount.current;
        titleText(ts, "Bohr Model of the Atom", new THREE.Vector3(0, 5.4, 0));

        const nucleus = new THREE.Mesh(new THREE.SphereGeometry(0.42, 24, 24), standardMaterial(0xef4444, { emissive: 0xef4444, emissiveIntensity: 0.7 }));
        ts!.group.add(nucleus);

        const orbits = new THREE.Group();
        for (let m = 1; m <= 4; m++) {
          const rad = r1 * m * m;
          const ring = new THREE.Mesh(
            new THREE.TorusGeometry(rad, 0.03, 8, 96),
            m === n ? standardMaterial(0x22d3ee, { emissive: 0x22d3ee, emissiveIntensity: 0.5 }) : standardMaterial(0x334155)
          );
          ring.rotation.x = Math.PI / 2;
          ring.position.y = 0;
          orbits.add(ring);
        }
        orbits.rotation.x = 0.55;
        ts!.group.add(orbits);

        electron = new THREE.Mesh(new THREE.SphereGeometry(0.16, 16, 16), standardMaterial(0x38bdf8, { emissive: 0x38bdf8, emissiveIntensity: 0.9 }));
        electron.position.set(rN, 0, 0);
        ts!.group.add(electron);

        sys = await createLabelSystem();
        ts!.group.add(sys.group);
        defs.forEach((d) => sys.add(d));


    updateRef.current = (time) => {
    const a = time * 1.4;
    if (electron) electron.position.set(Math.cos(a) * rN, Math.sin(a) * rN, 0);
    sys.render(ts!.scene, ts!.camera);
    };
  })();}, [webgl, n, Z]);


  return (
    <Card className="w-full">
      <CardHeader>
        <CardTitle>⚛️ Bohr Atom — symbols at their exact places</CardTitle>
        <CardDescription>+Ze, rₙ = r₁n², n, Eₙ and the photon hν are labelled where they act; the allowed discrete orbits light up for your chosen n.</CardDescription>
      </CardHeader>
      <CardContent className="space-y-5">
        <SceneArea mountRef={mount} hint="electron orbits the chosen shell · only blue ring is the active n" />
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          <div><Label>Shell n ({n})</Label><Slider min={1} max={6} step={1} value={[n]} onValueChange={(v) => setN(v[0])} /></div>
          <div><Label>Atomic number Z ({Z})</Label><Slider min={1} max={8} step={1} value={[Z]} onValueChange={(v) => setZ(v[0])} /></div>
        </div>
        <span className="text-sm text-muted-foreground">rₙ = {(rNm * 1e10).toFixed(2)} × 10⁻¹⁰ m · Eₙ = {EN.toFixed(2)} eV</span>
        <GuidePanel title="Bohr guide — symbol · position · description" defs={defs} />
        <TheoryPanel
          title="Bohr model — theory"
          vocabulary="Principal quantum number n; Bohr radius r₁ = 0.529 Å; Energy Eₙ = −13.6Z²/n² (eV); Photon hν = ΔE."
          look="Only the shell matching n glows blue — the electron can live on ANY allowed ring, but never half-way between two of them."
          predict="Raise n: the orbit ring jumps outward (r ~ n²) and the energy level climbs toward zero (less negative). Raise Z: everything tightens and E drops sharply."
          principle={<span className="block font-mono text-[11px] text-foreground">rₙ = n²r₁/Z · Eₙ = −13.6Z²/n² eV · ΔE = hν on a jump</span>}
          why="Leads the way to a Total series descriptions — spectrum lines (Balmer) are just the hν = E₂−E₁ differences you read on this energy ladder."
        />
      </CardContent>
    </Card>
  );
}

/* ================================================================
   EXPERIMENT 2 · PHOTOELECTRIC EFFECT (hν, φ, e⁻, KEmax, λ₀)
   ================================================================ */

const METAL_PHI = [
  { name: "Caesium", phi: 2.1 },
  { name: "Sodium", phi: 2.28 },
  { name: "Zinc", phi: 4.3 },
  { name: "Copper", phi: 4.65 },
] as const;

function Photoelectric3D() {
  const mount = useRef<HTMLDivElement>(null);
  const updateRef = useRef<((time: number) => void) | null>(null);
  const tsRef = useRef<ThreeScene | null>(null);
  const [webgl] = useState(() => typeof window !== "undefined" && isWebGLAvailable());
  const [lambdaNm, setLambdaNm] = useState(400);
  const [metalIdx, setMetalIdx] = useState(0);

  const metal = METAL_PHI[metalIdx];
  const E = 1240 / lambdaNm;
  const emit = E > metal.phi;
  const KE = emit ? E - metal.phi : 0;
  const lambda0 = 1240 / metal.phi;

  const photonColor = lambdaNm < 450 ? 0x8b5cf6 : lambdaNm < 550 ? 0x22c55e : lambdaNm < 600 ? 0xfbbf24 : 0xf87171;

  const defs: LabelDef[] = [
    { x: -4.7, y: 1.9, z: 0, symbol: "hν", name: "Photon energy", desc: "E = 1240/λ = " + E.toFixed(2) + " eV for λ = " + lambdaNm + " nm.", color: "#fbbf24" },
    { x: -2.2, y: 2.15, z: 0, symbol: "φ", name: "Work function", desc: "Minimum energy to free an electron: " + metal.phi + " eV (" + metal.name + ").", color: "#ef4444" },
    { x: 0.6, y: 1.5, z: 0, symbol: "e⁻", name: "Photoelectron", desc: emit ? "Ejected! KEmax = " + KE.toFixed(2) + " eV carries it to the collector." : "NOT emitted — E ≤ φ, however bright the light.", color: emit ? "#22d3ee" : "#94a3b8" },
    { x: 2.7, y: -2.0, z: 0, symbol: "KEmax = hν − φ", name: "Max kinetic energy", desc: emit ? "= " + KE.toFixed(2) + " eV — extra energy beyond φ becomes motion." : "= 0 — no emission below threshold.", color: "#22c55e" },
    { x: -4.9, y: -2.0, z: 0, symbol: "λ₀ = 1240/φ", name: "Threshold wavelength", desc: "= " + lambda0.toFixed(0) + " nm — only λ shorter than this can eject electrons.", color: "#a78bfa" },
  ];

  // Scene lifecycle - mount/unmount only
  useEffect(() => {
    if (!mount.current || !isWebGLAvailable()) return;
    const ts = createThreeScene(mount.current, { cameraPosition: new THREE.Vector3(1, 3.6, 11), autoRotate: false, background: 0x0b1220 });
    tsRef.current = ts;
    const unbind = bindResize(ts);
    let rafId = 0;
    function animate() {
      rafId = requestAnimationFrame(animate);
      const time = performance.now() / 1000;
      updateRef.current?.(time);
      ts!.controls.update();
      ts!.renderer.render(ts!.scene, ts!.camera);
    }
    animate();
    return () => { cancelAnimationFrame(rafId); unbind(); disposeThreeScene(ts); tsRef.current = null; };
  }, []);

  // Rebuild 3D content on state change
  useEffect(() => {(async () => {
    const ts = tsRef.current;
    if (!ts) return;
    clearGroup(ts!.group);

const electrons: { mesh: THREE.Mesh; y: number; z: number; x: number }[] = [];
const photons: { mesh: THREE.Mesh; u: number }[] = [];
let sys: any = null;
const el = mount.current;
        titleText(ts, "Photoelectric Effect", new THREE.Vector3(1.2, 3.9, 0));

        const plate = new THREE.Mesh(new THREE.BoxGeometry(0.5, 3.4, 1.7), standardMaterial(0x94a3b8, { metalness: 0.8, roughness: 0.3 }));
        plate.position.set(-2.2, 0, 0);
        ts!.group.add(plate);
        const collector = new THREE.Mesh(new THREE.BoxGeometry(0.3, 3.4, 1.7), standardMaterial(0x334155, { metalness: 0.6 }));
        collector.position.set(5.2, 0, 0);
        ts!.group.add(collector);
        /* battery / meter hint between plates */
        ts!.group.add(new THREE.Line(
          new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(-1.95, -1.9, 0), new THREE.Vector3(5.05, -1.9, 0)]),
          new THREE.LineDashedMaterial({ color: 0x475569, dashSize: 0.2, gapSize: 0.15 })
        ));

        for (let i = 0; i < 5; i++) {
          const p = new THREE.Mesh(new THREE.SphereGeometry(0.12, 10, 10), standardMaterial(photonColor, { emissive: photonColor, emissiveIntensity: 1 }));
          p.position.set(-7 + i * 1.1, 0.6 + (i % 3) * 0.5 - 0.5, (i % 2 === 0 ? 0.3 : -0.3));
          photons.push({ mesh: p, u: i / 5 });
          ts!.group.add(p);
        }
        for (let i = 0; i < 6; i++) {
          const e = new THREE.Mesh(new THREE.SphereGeometry(0.09, 10, 10), standardMaterial(0x22d3ee, { emissive: 0x22d3ee, emissiveIntensity: 0.9 }));
          e.visible = false;
          electrons.push({ mesh: e, y: 0, z: 0, x: -1.9 });
          ts!.group.add(e);
        }

        sys = await createLabelSystem();
        ts!.group.add(sys.group);
        defs.forEach((d) => sys.add(d));


    updateRef.current = (time) => {
    photons.forEach((p, i) => {
      p.u = (p.u + 0.006) % 1;
      p.mesh.position.set(-7 + p.u * 4.7, 0.6 + (i % 3) * 0.5 - 0.5, i % 2 === 0 ? 0.3 : -0.3);
      (p.mesh.material as THREE.MeshStandardMaterial).emissive.setHex(photonColor);
      (p.mesh.material as THREE.MeshStandardMaterial).color.setHex(photonColor);
    });
    electrons.forEach((e, i) => {
      if (!emit) { e.mesh.visible = false; return; }
      e.mesh.visible = true;
      const sp = 0.03 + Math.min(KE, 3) * 0.03;
      e.x += sp;
      if (e.x > 5.1) { e.x = -1.9; e.y = 1.3 * Math.sin(i * 2.1 + time); e.z = (i % 3 - 1) * 0.4; }
      if (e.x <= -1.89) { e.y = 1.3 * Math.sin(i * 2.1 + time); e.z = (i % 3 - 1) * 0.4; }
      e.mesh.position.set(e.x, e.y, e.z);
    });
    sys.render(ts!.scene, ts!.camera);
    };
  })();}, [webgl, lambdaNm, metalIdx]);


  return (
    <Card className="w-full">
      <CardHeader>
        <CardTitle>💡 Photoelectric Effect — hν, φ, KEmax at exact places</CardTitle>
        <CardDescription>Photons of colour-matched wavelength hit the metal plate; if hν &gt; φ electrons eject with KEmax = hν − φ — intensity never matters below threshold.</CardDescription>
      </CardHeader>
      <CardContent className="space-y-5">
        <SceneArea mountRef={mount} hint="coloured dots = photons (colour = wavelength) · cyan = photoelectrons" />
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          <div><Label>Wavelength λ ({lambdaNm} nm)</Label><Slider min={200} max={700} step={5} value={[lambdaNm]} onValueChange={(v) => setLambdaNm(v[0])} /></div>
          <div>
            <Label>Metal (φ)</Label>
            <div className="flex flex-wrap gap-1.5 mt-1">
              {METAL_PHI.map((mm, i) => (
                <Button key={mm.name} size="sm" variant={i === metalIdx ? "default" : "outline"} onClick={() => setMetalIdx(i)}>{mm.name}</Button>
              ))}
            </div>
          </div>
        </div>
        <span className={`text-sm font-medium ${emit ? "text-emerald-600" : "text-red-500"}`}>
          {emit
            ? `Emission ✓ — E = ${E.toFixed(2)} eV > φ = ${metal.phi} eV → KEmax = ${KE.toFixed(2)} eV`
            : `No emission ✗ — E = ${E.toFixed(2)} eV ≤ φ = ${metal.phi} eV (raise λ down / pick a lower-φ metal)`}
        </span>
        <GuidePanel title="Photoelectric guide — symbol · position · description" defs={defs} />
        <TheoryPanel
          title="Photoelectric effect — theory"
          vocabulary="Photon E = hν = 1240/λ (eV·nm); Work function φ — energy to free an electron; Stopping potential eVs = KEmax."
          look="Each photon is absorbed by ONE electron — brighter light means more photons (more current), but only SHORTER wavelength makes them leave faster."
          predict="Slide λ below λ₀ and electrons suddenly appear; push λ shorter still and the cyan electrons fly faster (KEmax grows linearly with 1/λ)."
          principle={<span className="block font-mono text-[11px] text-foreground">hν = φ + KEmax · KEmax = 1240/λ − φ · emission requires λ ≤ λ₀ = 1240/φ</span>}
          why="This effect forced physics to accept light quanta — the paper that earned Einstein the Nobel prize and the operating principle of solar cells and night-vision sensors."
        />
      </CardContent>
    </Card>
  );
}

export default function AtomicSymbols() {
  return (
    <Tabs defaultValue="bohr" className="w-full">
      <TabsList className="flex-wrap">
        <TabsTrigger value="bohr">Bohr Atom</TabsTrigger>
        <TabsTrigger value="photo">Photoelectric</TabsTrigger>
      </TabsList>
      <TabsContent value="bohr" className="mt-4"><BohrAtom3D /></TabsContent>
      <TabsContent value="photo" className="mt-4"><Photoelectric3D /></TabsContent>
    </Tabs>
  );
}

"use client";

/**
 * Elasticity & Ideal Gas suite — labelled 3D simulations for the NEB
 * Physics XI (Phy. 101) units:
 *   • Elasticity — Hooke's law, spring constant, Young's modulus
 *   • Ideal Gas  — kinetic-molecular model, ideal gas equation PV = nRT
 */

import { useState, useRef, useEffect } from "react";
import * as THREE from "three";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Slider } from "@/components/ui/slider";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { isWebGLAvailable } from "@/lib/webgl";
import { TheoryPanel } from "@/components/lab/theory-panel";
import { createLeaderLayer } from "./leader-lines";
import { createRevealBar } from "@/components/lab/leader-lines";
import {
  createThreeScene,
  disposeThreeScene,
  bindResize,
  standardMaterial,
  titleText,
  type ThreeScene,
  clearGroup,
} from "@/components/lab/three-scene";
import { CSS2DRenderer, CSS2DObject } from "three/addons/renderers/CSS2DRenderer.js";

function mkLabel(color: string, title: string, sub?: string): HTMLDivElement {
  const el = document.createElement("div");
  el.style.cssText =
    "pointer-events:auto;padding:3px 8px;border-radius:8px;background:rgba(2,6,23,0.82);" +
    `border:1.5px solid ${color};color:#e2e8f0;font:600 11px/1.35 ui-sans-serif,system-ui;white-space:nowrap;`;
  el.innerHTML = `<span style="color:${color};font-weight:800">${title}</span>` +
    (sub ? `<br/><span style="opacity:.8;font-weight:500">${sub}</span>` : "");
  return el;
}

/* =====================================================================
 * TAB 1 — Hooke's law (spring) and Young's modulus (wire)
 * ===================================================================== */

const SPRINGS = [
  { name: "Soft spring", k: 12, color: 0x4ade80 },
  { name: "Medium spring", k: 30, color: 0x38bdf8 },
  { name: "Stiff spring", k: 60, color: 0xf97316 },
] as const;

const WIRES = [
  { name: "Copper", Y: 110, color: 0xfbbf24 },
  { name: "Brass", Y: 91, color: 0xa3e635 },
  { name: "Steel", Y: 200, color: 0x94a3b8 },
] as const;

const ElasticityTab: React.FC = () => {
  const mountRef = useRef<HTMLDivElement>(null);
  const updateRef = useRef<((time: number) => void) | null>(null);
  const tsRef = useRef<ThreeScene | null>(null);
  const [webGL] = useState(() => typeof window !== "undefined" && isWebGLAvailable());
  const [mode, setMode] = useState<"hooke" | "young">("hooke");
  const [springIdx, setSpringIdx] = useState(1);
  const [massN, setMassN] = useState(20); // hanging weight in newtons
  const [wireIdx, setWireIdx] = useState(2);
  const [forceN, setForceN] = useState(300);
  const [lenM, setLenM] = useState(2.0);
  const [diaMm, setDiaMm] = useState(1.0);

  const spring = SPRINGS[springIdx];
  const wire = WIRES[wireIdx];
  const xSpring = massN / spring.k;
  const area = Math.PI * ((diaMm / 1000) / 2) ** 2;
  const stress = forceN / area; // Pa
  const strain = stress / (wire.Y * 1e9);
  const dL = strain * lenM;

  // Scene lifecycle - mount/unmount only
  useEffect(() => {
    if (!mountRef.current || !isWebGLAvailable()) return;
    const ts = createThreeScene(mountRef.current, { cameraPosition: new THREE.Vector3(8, 5, 12), background: 0x0b1220 });
    tsRef.current = ts;
    const unbind = bindResize(ts);
    let rafId = 0;
    function animate() {
      rafId = requestAnimationFrame(animate);
      const time = performance.now() / 1000;
      updateRef.current?.(time);
      ts!.controls.update();
      ts!.renderer.render(ts!.scene, ts!.camera);
    }
    animate();
    return () => { cancelAnimationFrame(rafId); unbind(); disposeThreeScene(ts); tsRef.current = null; };
  }, []);

  // Rebuild 3D content on state change
  useEffect(() => {
    let labelRenderer: any;
let leaderLayer: any;
    let revealBarDispose: (() => void) | null = null;
    const ts = tsRef.current;
    if (!ts) return;
    clearGroup(ts!.group);

    titleText(ts, mode === "hooke" ? `Hooke's Law — k = ${spring.k} N/m` : `Young's Modulus — ${wire.name} wire, Y = ${wire.Y} GPa`, new THREE.Vector3(0, 5.2, 0));

    labelRenderer = new CSS2DRenderer();
    labelRenderer.setSize(mountRef.current!.clientWidth, mountRef.current!.clientHeight);
    labelRenderer.domElement.style.cssText = "position:absolute;top:0;left:0;pointer-events:none;z-index:10";
    mountRef.current!.appendChild(labelRenderer.domElement);
    try { leaderLayer = createLeaderLayer(mountRef.current!); } catch { leaderLayer = null; }
          try { revealBarDispose = createRevealBar(mountRef.current!, leaderLayer); } catch { /* non-fatal */ }

    const connections: any[] = [];
    const addLbl = (color: string, t: string, pos: [number, number, number], sub?: string, target?: [number, number, number]) => {
      const o = new CSS2DObject(mkLabel(color, t, sub));
      o.position.set(pos[0], pos[1], pos[2]);
      ts!.group.add(o);
      if (target) connections.push({ label: o, target: new THREE.Vector3(target[0], target[1], target[2]), color });
    };

    ts!.group.add(new THREE.Mesh(new THREE.BoxGeometry(18, 0.3, 10), standardMaterial(0x1e293b, { roughness: 0.95 })));
    /* ceiling */
    const ceil = new THREE.Mesh(new THREE.BoxGeometry(6, 0.3, 2.4), standardMaterial(0x57534e, { metalness: 0.5 }));
    ceil.position.set(0, 4.6, 0);
    ts!.group.add(ceil);
    addLbl("#f87171", "Rigid support", [0, 5.6, 0], "top fixed end", [0, 4.5, 0]);

    let hangGrp: THREE.Group | null = null;
    if (mode === "hooke") {
      /* coil spring drawn as a helix tube */
      const restLen = 2.0;
      const stretch = Math.min(1.9, Math.max(0.05, xSpring * 0.9));
      const helixPts: THREE.Vector3[] = [];
      const turns = 10;
      const steps = 120;
      for (let i = 0; i <= steps; i++) {
        const s = i / steps;
        helixPts.push(new THREE.Vector3(0.32 * Math.cos(s * turns * Math.PI * 2), 4.5 - s * (restLen + stretch), 0.32 * Math.sin(s * turns * Math.PI * 2)));
      }
      const springMesh = new THREE.Mesh(
        new THREE.TubeGeometry(new THREE.CatmullRomCurve3(helixPts), 200, 0.055, 8),
        standardMaterial(spring.color, { metalness: 0.6, roughness: 0.35 })
      );
      ts!.group.add(springMesh);

      /* hanger + slotted weights */
      const hanger = new THREE.Group();
      hanger.add(new THREE.Mesh(new THREE.CylinderGeometry(0.5, 0.5, 0.1, 24), standardMaterial(0x94a3b8, { metalness: 0.7 })));
      const weight = new THREE.Mesh(new THREE.CylinderGeometry(0.42, 0.42, 0.55, 24), standardMaterial(0x64748b, { metalness: 0.75 }));
      weight.position.y = -0.4;
      hanger.add(weight);
      hanger.position.set(0, 4.5 - (restLen + stretch) - 0.15, 0);
      const hangerRestY = hanger.position.y;
      ts!.group.add(hanger);
      hangGrp = hanger;

      /* ruler beside spring */
      const ruler = new THREE.Mesh(new THREE.BoxGeometry(0.14, 4.2, 0.08), standardMaterial(0xfafafa, { roughness: 0.6 }));
      ruler.position.set(-1.5, 2.4, 0);
      ts!.group.add(ruler);
      for (let i = 0; i <= 8; i++) {
        const tick = new THREE.Mesh(new THREE.BoxGeometry(0.24, 0.02, 0.09), standardMaterial(0x111827));
        tick.position.set(-1.5, 0.35 + i * 0.5, 0);
        ts!.group.add(tick);
      }
      addLbl("#38bdf8", `Spring — k = ${spring.k} N/m`, [2.6, 4.0, 0], "F = k·x (linear region)", [0.3, 3.6, 0]);
      addLbl("#facc15", `Load F = ${massN} N`, [1.9, hangerRestY + 0.4, 0], `x = F/k = ${xSpring.toFixed(2)} m stretch`, [0, hangerRestY, 0]);
      addLbl("#4ade80", "Millimetre scale", [-2.4, 2.4, 0], "measure x from the pointer", [-1.5, 2.4, 0]);
      addLbl("#a78bfa", "Elastic limit — don't cross it", [3.6, 1.2, 0], "beyond it the spring deforms permanently", [0.6, 2.0, 0]);
    } else {
      /* Young's modulus wire */
      const wireLen = 3.6;
      const wireMesh = new THREE.Mesh(
        new THREE.CylinderGeometry(Math.max(0.02, diaMm * 0.09), Math.max(0.02, diaMm * 0.09), wireLen + Math.min(0.5, dL * 400), 12),
        standardMaterial(wire.color, { metalness: 0.7, roughness: 0.3 })
      );
      wireMesh.position.set(0, 4.5 - (wireLen + Math.min(0.5, dL * 400)) / 2, 0);
      ts!.group.add(wireMesh);

      const clamp = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.3, 0.35, 16), standardMaterial(0x57534e, { metalness: 0.6 }));
      clamp.position.set(0, 4.5 - (wireLen + Math.min(0.5, dL * 400)) - 0.2, 0);
      ts!.group.add(clamp);

      const pan = new THREE.Mesh(new THREE.CylinderGeometry(0.55, 0.45, 0.12, 24), standardMaterial(0x94a3b8, { metalness: 0.7 }));
      pan.position.set(0, clamp.position.y - 0.45, 0);
      ts!.group.add(pan);
      hangGrp = new THREE.Group();
      hangGrp.add(clamp, pan);
      ts!.group.add(hangGrp);
      hangGrp.position.set(0, 0, 0);

      addLbl("#fbbf24", `${wire.name} wire`, [1.9, 3.9, 0], `L = ${lenM.toFixed(2)} m, d = ${diaMm.toFixed(1)} mm`, [0.05, 3.4, 0]);
      addLbl("#facc15", `Load F = ${forceN} N`, [1.7, clamp.position.y - 1.1, 0], `stress = ${stress.toExponential(2)} Pa`, [0, clamp.position.y - 0.45, 0]);
      addLbl("#38bdf8", `ΔL = ${(dL * 1000).toFixed(2)} mm`, [-2.5, 1.3, 0], `strain = ${(strain * 100).toFixed(4)} %`, [0, 1.5, 0]);
    }

    updateRef.current = (time) => {
    if (mode === "hooke" && hangGrp) {
      hangGrp.position.y = Math.sin(time * 2.4) * 0.07; // gentle bounce about equilibrium
    }
    if (leaderLayer) leaderLayer.draw(ts!.camera, connections);
    if (labelRenderer) labelRenderer.render(ts!.scene, ts!.camera);
    };
  }, [webGL, mode, springIdx, massN, wireIdx, forceN, lenM, diaMm]);

return (
    <div className="space-y-3">
      <div className="grid gap-4 lg:grid-cols-[1.5fr_1fr]">
        <div className="relative min-h-[clamp(320px,60vh,640px)] overflow-hidden rounded-lg border border-border bg-slate-950" ref={mountRef}>
          {!webGL && <div className="absolute inset-0 grid place-items-center text-sm text-muted-foreground">WebGL unavailable.</div>}
        </div>
        <div className="space-y-4">
          <Tabs value={mode} onValueChange={(v) => setMode(v as "hooke" | "young")}>
            <TabsList className="w-full">
              <TabsTrigger value="hooke" className="flex-1">Hooke's law</TabsTrigger>
              <TabsTrigger value="young" className="flex-1">Young's modulus</TabsTrigger>
            </TabsList>
          </Tabs>
          {mode === "hooke" ? (
            <>
              <div className="space-y-2">
                <div className="flex justify-between"><Label>Spring</Label><span className="text-sm font-semibold text-primary">{spring.name}</span></div>
                <Slider value={[springIdx]} min={0} max={2} step={1} onValueChange={(v) => setSpringIdx(v[0])} />
              </div>
              <div className="space-y-2">
                <div className="flex justify-between"><Label>Load F</Label><span className="text-sm font-semibold text-primary">{massN} N</span></div>
                <Slider value={[massN]} min={2} max={100} step={2} onValueChange={(v) => setMassN(v[0])} />
              </div>
              <div className="grid grid-cols-2 gap-2 text-center">
                <div className="rounded-md border border-sky-500/30 bg-sky-500/5 p-2"><p className="text-[10px] uppercase text-muted-foreground">Extension x = F/k</p><p className="text-sm font-bold text-sky-500">{(xSpring * 100).toFixed(1)} cm</p></div>
                <div className="rounded-md border border-emerald-500/30 bg-emerald-500/5 p-2"><p className="text-[10px] uppercase text-muted-foreground">Energy ½kx²</p><p className="text-sm font-bold text-emerald-500">{(0.5 * spring.k * xSpring ** 2).toFixed(2)} J</p></div>
              </div>
            </>
          ) : (
            <>
              <div className="space-y-2">
                <div className="flex justify-between"><Label>Wire material</Label><span className="text-sm font-semibold text-primary">{wire.name}</span></div>
                <Slider value={[wireIdx]} min={0} max={2} step={1} onValueChange={(v) => setWireIdx(v[0])} />
              </div>
              <div className="space-y-2">
                <div className="flex justify-between"><Label>Load F</Label><span className="text-sm font-semibold text-primary">{forceN} N</span></div>
                <Slider value={[forceN]} min={50} max={1000} step={10} onValueChange={(v) => setForceN(v[0])} />
              </div>
              <div className="space-y-2">
                <div className="flex justify-between"><Label>Length L</Label><span className="text-sm font-semibold text-primary">{lenM.toFixed(2)} m</span></div>
