const DIELECTRICS = [
  { name: "Air (vacuum)", k: 1.0, color: 0x94a3b8 },
  { name: "Paper", k: 3.5, color: 0xfcd34d },
  { name: "Glass", k: 7.0, color: 0x67e8f9 },
