  const cEff = frac * mat.k * cAir + (1 - frac) * cAir;
  const charge = cEff * volts;
  const energy = 0.5 * cEff * volts ** 2;
  const field = volts / d;

  // Scene lifecycle - mount/unmount only
  useEffect(() => {
    if (!mountRef.current || !isWebGLAvailable()) return;
