          if (target) connections.push({ label: o, target: new THREE.Vector3(target[0], target[1], target[2]), color });
        };

        ts!.group.add(new THREE.Mesh(new THREE.BoxGeometry(16, 0.3, 11), standardMaterial(0x1e293b, { roughness: 0.95 })));

