  const [showLabels, setShowLabels] = useState(true);
  const [showField, setShowField] = useState(true);
  const [runId, setRunId] = useState(0);
  // Speed lives in a ref so changing it never tears down the WebGL scene.
  const speedRef = useRef(1);
  speedRef.current = speed;

  const voltage = charge / capacitance; // V (Q in μC, C in μF)
  const energyUJ = (charge * charge) / (2 * capacitance); // μJ

  const DEFAULTS = { charge: 5, capacitance: 2 };
  const presets: ScenePreset[] = [
    {
      name: "Default (2 μF)",
      hint: "5 μC on a 2 μF capacitor — 2.5 V across the plates.",
      apply: () => { setCharge(5); setCapacitance(2); setRunId((r) => r + 1); },
    },
    {
      name: "Large capacitor",
      hint: "10 μF — same charge spreads out, voltage drops.",
      apply: () => { setCharge(8); setCapacitance(10); setRunId((r) => r + 1); },
    },
    {
      name: "High voltage (0.5 μF)",
      hint: "Small capacitance at 10 μC — V = Q/C = 20 V.",
      apply: () => { setCharge(10); setCapacitance(0.5); setRunId((r) => r + 1); },
    },
    {
      name: "Energy storage",
      hint: "Max charge, moderate C — compare stored energy U = Q²/2C.",
      apply: () => { setCharge(10); setCapacitance(2); setRunId((r) => r + 1); },
    },
  ];

  const resetAll = () => {
    setCharge(DEFAULTS.charge);
    setCapacitance(DEFAULTS.capacitance);
    setSpeed(1);
    setShowLabels(true);
    setShowField(true);
    setAnimating(true);
    setRunId((r) => r + 1);
  };

  useEffect(() => {
    const container = containerRef.current;
    if (!container || !isWebGL) return;

    let scene: THREE.Scene, camera: THREE.PerspectiveCamera, renderer: THREE.WebGLRenderer;
    let controls: any, frameId: number;
    const meshes: THREE.Object3D[] = [];
    const labelSprites: THREE.Sprite[] = [];
    const fieldObjs: THREE.Object3D[] = [];
    let animPhase = 0;

    const init = async () => {
      const { OrbitControls } = await import("three/addons/controls/OrbitControls.js");

      scene = new THREE.Scene();
      scene.background = new THREE.Color(0x0f172a);
      camera = new THREE.PerspectiveCamera(50, container.clientWidth / container.clientHeight, 0.1, 100);
      camera.position.set(0, 0, 10);

      renderer = new THREE.WebGLRenderer({ antialias: true });
      renderer.setSize(container.clientWidth, container.clientHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      container.appendChild(renderer.domElement);

      controls = new OrbitControls(camera, renderer.domElement);
      controls.enableDamping = true;
      controls.autoRotate = false;
      controls.minDistance = 3;
      controls.maxDistance = 20;
      vizTargetRef.current = {
        controls,
        el: container,
        canvasEl: renderer.domElement,
        setLabels: (on: boolean) => labelSprites.forEach((s) => (s.visible = on)),
      };

      scene.add(new THREE.AmbientLight(0xffffff, 0.7));
      const dir = new THREE.DirectionalLight(0xffffff, 1.0);
      dir.position.set(5, 10, 5);
      scene.add(dir);

      const push = <T extends THREE.Object3D>(o: T): T => { scene.add(o); meshes.push(o); return o; };
      const addLabel = (s: THREE.Sprite): THREE.Sprite => { s.visible = showLabels; push(s); labelSprites.push(s); return s; };
      const addField = <T extends THREE.Object3D>(o: T): T => { o.visible = showField; push(o); fieldObjs.push(o); return o; };

      // Positive plate (right)
      const posPlate = push(new THREE.Mesh(
        new THREE.BoxGeometry(0.2, 3, 2),
        new THREE.MeshBasicMaterial({ color: 0xef4444 }),
      )) as THREE.Mesh;
      posPlate.position.set(1.5, 0, 0);
      addLabel(mkSprite("+Q", "#ef4444", new THREE.Vector3(2.2, 0, 0), 0.8));

      // Negative plate (left)
      const negPlate = push(new THREE.Mesh(
        new THREE.BoxGeometry(0.2, 3, 2),
        new THREE.MeshBasicMaterial({ color: 0x3b82f6 }),
      )) as THREE.Mesh;
      negPlate.position.set(-1.5, 0, 0);
      addLabel(mkSprite("−Q", "#3b82f6", new THREE.Vector3(-2.2, 0, 0), 0.8));

      // Electric field lines (from + to −)
      const fieldLines: THREE.Line[] = [];
      for (let y = -1.2; y <= 1.2; y += 0.4) {
        const pts: THREE.Vector3[] = [new THREE.Vector3(1.3, y, 0), new THREE.Vector3(-1.3, y, 0)];
        const line = addField(new THREE.Line(
          new THREE.BufferGeometry().setFromPoints(pts),
          new THREE.LineBasicMaterial({ color: 0xfbbf24, transparent: true, opacity: 0.7 }),
        )) as THREE.Line;
        fieldLines.push(line);
      }
      // Arrow heads on field lines
      for (let y = -1.2; y <= 1.2; y += 0.8) {
        const arrowHead = addField(new THREE.Mesh(
          new THREE.ConeGeometry(0.08, 0.2, 8),
          new THREE.MeshBasicMaterial({ color: 0xfbbf24 }),
        )) as THREE.Mesh;
        arrowHead.position.set(0, y, 0);
        arrowHead.rotation.z = -Math.PI / 2;
        fieldLines.push(arrowHead as any);
      }
      addLabel(mkSprite("E field (E = V/d)", "#fbbf24", new THREE.Vector3(0, 2.2, 0), 0.75));

      // Long arrow label for charge
      const chargeLabelPos = new THREE.Vector3(0, -2.5, 0);
      const chargeTarget = new THREE.Vector3(0, 0, 0);
      const chargeDir = chargeTarget.clone().sub(chargeLabelPos).normalize();
      push(new LiveLeaderLine(chargeDir, chargeLabelPos, chargeLabelPos.distanceTo(chargeTarget) * 0.9, 0x22d3ee, 0.15, 0.1));
      addLabel(mkSprite(`Q = ${charge} μC`, "#22d3ee", chargeLabelPos.clone().sub(chargeDir.multiplyScalar(0.5)), 0.8));

      // Voltage label
      const vLabelPos = new THREE.Vector3(3.5, 0, 0);
      const vTarget = new THREE.Vector3(1.5, 0, 0);
      const vDir = vTarget.clone().sub(vLabelPos).normalize();
      push(new LiveLeaderLine(vDir, vLabelPos, vLabelPos.distanceTo(vTarget) * 0.9, 0xa78bfa, 0.15, 0.1));
      addLabel(mkSprite(`V = Q/C = ${voltage.toFixed(1)} V`, "#a78bfa", vLabelPos.clone().sub(vDir.multiplyScalar(0.5)), 0.7));

      // Capacitance formula label
      const CLabelPos = new THREE.Vector3(-3.5, 0, 0);
      const CTarget = new THREE.Vector3(-1.5, 0, 0);
      const CDir = CTarget.clone().sub(CLabelPos).normalize();
      push(new LiveLeaderLine(CDir, CLabelPos, CLabelPos.distanceTo(CTarget) * 0.9, 0x34d399, 0.15, 0.1));
      addLabel(mkSprite(`C = ${capacitance} μF`, "#34d399", CLabelPos.clone().sub(CDir.multiplyScalar(0.5)), 0.75));

      // Electron flow animation
      const electrons: THREE.Mesh[] = [];
      for (let i = 0; i < 8; i++) {
        const e = push(new THREE.Mesh(
          new THREE.SphereGeometry(0.08, 8, 8),
          new THREE.MeshBasicMaterial({ color: 0x3b82f6 }),
        )) as THREE.Mesh;
        e.userData.phase = (i / 8) * Math.PI * 2;
        electrons.push(e);
      }

      const update = () => {
        while (meshes.length > 50) {
          const m = meshes.pop()!;
          scene.remove(m);
          if (m instanceof THREE.Mesh) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Line) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Sprite) { (m.material as THREE.SpriteMaterial).map?.dispose?.(); m.material.dispose(); }
          else if (m instanceof THREE.ArrowHelper) m.dispose();
        }
      };
      update();

      const animate = () => {
        frameId = requestAnimationFrame(animate);
        controls.update();
        if (animating) {
          animPhase += 0.03 * speedRef.current;
          electrons.forEach((e) => {
            const phase = e.userData.phase + animPhase;
            e.position.set(Math.cos(phase) * 2.5, Math.sin(phase) * 1.5, 0);
          });
        }
        renderer.render(scene, camera);
      };
      animate();

      const handleResize = () => {
        if (!container) return;
        camera.aspect = container.clientWidth / container.clientHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(container.clientWidth, container.clientHeight);
      };
      window.addEventListener("resize", handleResize);
      // Re-fit the canvas whenever the container itself resizes (screen fit)
      const resizeObserver = new ResizeObserver(() => handleResize());
      resizeObserver.observe(container);

      return () => {
        cancelAnimationFrame(frameId);
        window.removeEventListener("resize", handleResize);
        resizeObserver?.disconnect();
        if (renderer.domElement.parentNode) renderer.domElement.parentNode.removeChild(renderer.domElement);
        meshes.forEach((m) => {
          scene.remove(m);
          if (m instanceof THREE.Mesh) { m.geometry?.dispose(); const mat = m.material; if (Array.isArray(mat)) mat.forEach((x) => x.dispose()); else (Array.isArray(mat) ? mat : [mat]).forEach((x) => x.dispose()); }
          else if (m instanceof THREE.Line) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Sprite) { const sm = m.material; sm.map?.dispose?.(); sm.dispose(); }
          else if (m instanceof THREE.ArrowHelper) m.dispose();
        });
        renderer.dispose();
        controls.dispose?.();
      };
    };

    const cleanup = init();
    return () => { cleanup.then((d) => d?.()); };
  }, [charge, capacitance, isWebGL, animating, runId, showLabels, showField]);

  if (!isWebGL) {
    return <WebGLFallback title="Capacitor" description="Parallel plate capacitor with electric field lines." />;
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex flex-wrap items-center gap-2">
          <span>Capacitor — Parallel Plates & Field Lines</span>
          <span className="text-xs text-muted-foreground font-normal">Drag to rotate · Scroll to zoom</span>
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <CollapsibleControls label="Capacitor Parameters">
          <div className="flex flex-wrap gap-4 mt-2">
            <div className="w-28">
              <Label className="text-xs text-muted-foreground">Charge Q (μC):</Label>
              <Input type="range" min={1} max={10} step={0.5} value={charge} onChange={(e) => setCharge(Number(e.target.value))} className="mt-1 w-full" />
              <p className="text-xs font-mono text-primary mt-1">{charge} μC</p>
            </div>
            <div className="w-28">
              <Label className="text-xs text-muted-foreground">Capacitance C (μF):</Label>
              <Input type="range" min={0.5} max={10} step={0.5} value={capacitance} onChange={(e) => setCapacitance(Number(e.target.value))} className="mt-1 w-full" />
              <p className="text-xs font-mono text-primary mt-1">{capacitance} μF</p>
            </div>
          </div>
        </CollapsibleControls>

        <div className="flex flex-wrap items-center justify-between gap-3">
          <PlaybackBar
            playing={animating}
            onPlayToggle={() => setAnimating(!animating)}
            speed={speed}
            onSpeedChange={setSpeed}
            onReset={resetAll}
          />
          <div className="flex flex-wrap items-center gap-2">
            <button
              onClick={() => setShowLabels((v) => !v)}
              className={`px-2.5 py-1 rounded-md text-xs font-medium border transition-colors ${showLabels ? "border-primary/50 bg-primary/10 text-primary" : "border-border bg-muted/40 text-muted-foreground"}`}
            >
              Labels
            </button>
            <button
              onClick={() => setShowField((v) => !v)}
              className={`px-2.5 py-1 rounded-md text-xs font-medium border transition-colors ${showField ? "border-yellow-500/50 bg-yellow-500/10 text-yellow-400" : "border-border bg-muted/40 text-muted-foreground"}`}
            >
              Field lines
            </button>
          </div>
        </div>

        <ScenePresets presets={presets} />

        <div ref={containerRef} className="relative h-[clamp(320px,60vh,640px)] w-full overflow-hidden rounded-lg border border-border bg-slate-900">
          <VizToolbar targetRef={vizTargetRef} />
        </div>

        <ReadoutGrid
          items={[
            { label: "Capacitance C", value: capacitance, unit: "μF" },
            { label: "Voltage V = Q/C", value: voltage.toFixed(2), unit: "V", highlight: true },
            { label: "Stored energy U", value: energyUJ.toFixed(1), unit: "μJ" },
            { label: "Charge Q", value: charge, unit: "μC" },
          ]}
        />

        <div className="rounded-lg border border-yellow-500/30 bg-yellow-500/5 p-4">
          <p className="text-xs font-semibold uppercase tracking-wide text-yellow-400">Key Concepts</p>
          <div className="mt-2 space-y-1.5 text-xs text-muted-foreground">
            <p><strong className="text-foreground">Capacitance:</strong> C = Q/V — ability to store charge per unit voltage.</p>
            <p><strong className="text-foreground">Parallel plate:</strong> C = ε₀A/d — depends on area and separation.</p>
            <p><strong className="text-foreground">Electric field:</strong> E = V/d = σ/ε₀ — uniform between plates.</p>
            <p><strong className="text-foreground">Energy stored:</strong> U = ½CV² = ½QV = Q²/(2C)</p>
            <p><strong className="text-foreground">Dielectric:</strong> Inserting dielectric increases capacitance by factor κ.</p>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { useRef, useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { CollapsibleControls } from "@/components/lab/collapsible-controls";
import { isWebGLAvailable } from "@/lib/webgl";
import { WebGLFallback } from "@/components/lab/webgl-fallback";
import { VizToolbar, type VizTarget } from "@/components/viz/viz-toolbar";
import {
  ScenePresets,
  PlaybackBar,
  ReadoutGrid,
  type ScenePreset,
} from "@/components/lab/scene-interactivity";
import * as THREE from "three";
import { LiveLeaderLine } from "@/components/lab/leader-lines-3d";

function mkSprite(text: string, color: string, pos: THREE.Vector3, scale = 1.0): THREE.Sprite {
  const canvas = document.createElement("canvas");
  canvas.width = 512;
  canvas.height = 96;
  const ctx = canvas.getContext("2d")!;
  ctx.fillStyle = "rgba(15, 23, 42, 0.9)";
  ctx.fillRect(4, 4, 504, 88);
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.strokeRect(4, 4, 504, 88);
  ctx.font = "bold 32px monospace";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillStyle = color;
  ctx.fillText(text, 256, 48);
  const tex = new THREE.CanvasTexture(canvas);
  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: false }));
  s.position.copy(pos);
  s.scale.set(3.0 * scale, 0.56 * scale, 1);
  return s;
}

export function EMIInductionVisual() {
  const containerRef = useRef<HTMLDivElement>(null);
  const vizTargetRef = useRef<VizTarget>({});
  const [speed, setSpeed] = useState(2);
  const [isWebGL] = useState(() => isWebGLAvailable());
  const [animating, setAnimating] = useState(true);
  // PlaybackBar animation-rate multiplier (separate from the magnet-speed slider).
  const [animSpeed, setAnimSpeed] = useState(1);
  const animSpeedRef = useRef(1);
  animSpeedRef.current = animSpeed;
  const [showLabels, setShowLabels] = useState(true);
  const [showField, setShowField] = useState(true);
  const [runId, setRunId] = useState(0);
  // Live physics readouts published (throttled) from the animation loop.
  const [live, setLive] = useState({ x: 6, flux: 0, emf: 0, approaching: true });

  // Faraday model: N = 20 turns, coil radius 1.5 m, dipole magnet (μ₀·2m/4π ≈ 2×10⁻⁴ T·m³).
  const TURNS = 20;
  const COIL_AREA = Math.PI * 1.5 * 1.5;
  const fluxAt = (x: number) => {
    const d = Math.max(Math.abs(x), 0.6);
    return (TURNS * COIL_AREA * 2e-4) / (d * d * d); // Wb
  };

  const DEFAULTS = { speed: 2 };
  const presets: ScenePreset[] = [
    {
      name: "Slow push (0.5)",
      hint: "Gentle magnet motion — small, easily-traced emf.",
      apply: () => { setSpeed(0.5); setAnimating(true); setRunId((r) => r + 1); },
    },
    {
      name: "Standard (2)",
      hint: "Typical lab shuttle speed.",
      apply: () => { setSpeed(2); setAnimating(true); setRunId((r) => r + 1); },
    },
    {
      name: "Fast shuttle (5)",
      hint: "Rapid motion — dΦ/dt is large, so the induced emf spikes.",
      apply: () => { setSpeed(5); setAnimating(true); setRunId((r) => r + 1); },
    },
    {
      name: "Frozen (paused)",
      hint: "No motion → no flux change → zero induced emf.",
      apply: () => { setAnimating(false); setRunId((r) => r + 1); },
    },
  ];

  const resetAll = () => {
    setSpeed(DEFAULTS.speed);
    setAnimating(true);
    setAnimSpeed(1);
    setShowLabels(true);
    setShowField(true);
    setLive({ x: 6, flux: 0, emf: 0, approaching: true });
    setRunId((r) => r + 1);
  };


  useEffect(() => {
    const container = containerRef.current;
    if (!container || !isWebGL) return;

    let scene: THREE.Scene, camera: THREE.PerspectiveCamera, renderer: THREE.WebGLRenderer;
    let controls: any, frameId: number;
    const meshes: THREE.Object3D[] = [];
    const labelSprites: THREE.Sprite[] = [];
    let magnetX = 6;
    let direction = -1;

    const init = async () => {
      const { OrbitControls } = await import("three/addons/controls/OrbitControls.js");

      scene = new THREE.Scene();
      scene.background = new THREE.Color(0x0f172a);
      camera = new THREE.PerspectiveCamera(50, container.clientWidth / container.clientHeight, 0.1, 100);
      camera.position.set(0, 3, 10);

      renderer = new THREE.WebGLRenderer({ antialias: true });
      renderer.setSize(container.clientWidth, container.clientHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      container.appendChild(renderer.domElement);

      controls = new OrbitControls(camera, renderer.domElement);
      controls.enableDamping = true;
      controls.autoRotate = false;
      controls.minDistance = 3;
      controls.maxDistance = 20;
      vizTargetRef.current = {
        controls,
        el: container,
        canvasEl: renderer.domElement,
        setLabels: (on: boolean) => labelSprites.forEach((s) => (s.visible = on)),
      };

      scene.add(new THREE.AmbientLight(0xffffff, 0.7));
      const dir = new THREE.DirectionalLight(0xffffff, 1.0);
      dir.position.set(5, 10, 5);
      scene.add(dir);

      const push = <T extends THREE.Object3D>(o: T): T => { scene.add(o); meshes.push(o); return o; };
      const addLabel = (s: THREE.Sprite): THREE.Sprite => { push(s); labelSprites.push(s); return s; };

      // Coil (solenoid)
      const coilRadius = 1.5;
      const coilLength = 4;
      const turns = 20;
      for (let i = 0; i < turns; i++) {
        const t = i / (turns - 1);
        const x = -2 + t * coilLength;
        const coilRing = push(new THREE.Mesh(
          new THREE.TorusGeometry(coilRadius, 0.05, 8, 32),
          new THREE.MeshBasicMaterial({ color: 0xfbbf24 }),
        )) as THREE.Mesh;
        coilRing.position.set(x, 0, 0);
        coilRing.rotation.y = Math.PI / 2;
      }
      addLabel(mkSprite("Coil (solenoid)", "#fbbf24", new THREE.Vector3(0, 2.5, 0), 0.7));

      // Magnetic field lines through coil
      const fieldLinePts: THREE.Vector3[] = [];
      for (let x = -4; x <= 4; x += 0.2) {
        fieldLinePts.push(new THREE.Vector3(x, 0, 0));
      }
      const bField = push(new THREE.Line(
        new THREE.BufferGeometry().setFromPoints(fieldLinePts),
        new THREE.LineDashedMaterial({ color: 0x64748b, dashSize: 0.2, gapSize: 0.15 }),
      ) as any);
      (meshes[meshes.length - 1] as any).computeLineDistances();
      bField.visible = showField;

      // N and S labels on coil
      addLabel(mkSprite("N", "#ef4444", new THREE.Vector3(2.3, 0, 0), 0.8));
      addLabel(mkSprite("S", "#3b82f6", new THREE.Vector3(-2.3, 0, 0), 0.8));

      // Bar magnet
      const magnetGroup = new THREE.Group();
      const northPole = push(new THREE.Mesh(
        new THREE.BoxGeometry(1, 0.6, 0.6),
        new THREE.MeshBasicMaterial({ color: 0xef4444 }),
      ));
      northPole.position.set(0.5, 0, 0);
      magnetGroup.add(northPole);
      const southPole = push(new THREE.Mesh(
        new THREE.BoxGeometry(1, 0.6, 0.6),
        new THREE.MeshBasicMaterial({ color: 0x3b82f6 }),
      ));
      southPole.position.set(-0.5, 0, 0);
      magnetGroup.add(southPole);
      magnetGroup.position.set(magnetX, 0, 0);
      meshes.push(magnetGroup);

      // Magnet labels with long arrows
      const nLabelPos = new THREE.Vector3(magnetX, 1.5, 0);
      const nTarget = new THREE.Vector3(magnetX + 0.5, 0, 0);
      const nDir = nTarget.clone().sub(nLabelPos).normalize();
      push(new LiveLeaderLine(nDir, nLabelPos, nLabelPos.distanceTo(nTarget) * 0.9, 0xef4444, 0.2, 0.12));
      addLabel(mkSprite("N pole (North)", "#ef4444", nLabelPos.clone().sub(nDir.multiplyScalar(0.5)), 0.75));

      const sLabelPos = new THREE.Vector3(magnetX, -1.5, 0);
      const sTarget = new THREE.Vector3(magnetX - 0.5, 0, 0);
      const sDir = sTarget.clone().sub(sLabelPos).normalize();
      push(new LiveLeaderLine(sDir, sLabelPos, sLabelPos.distanceTo(sTarget) * 0.9, 0x3b82f6, 0.2, 0.12));
      addLabel(mkSprite("S pole (South)", "#3b82f6", sLabelPos.clone().sub(sDir.multiplyScalar(0.5)), 0.75));

      // Induced current arrow
      const indLabelPos = new THREE.Vector3(0, -3, 0);
      const indTarget = new THREE.Vector3(0, 0, 0);
      const indDir = indTarget.clone().sub(indLabelPos).normalize();
      push(new LiveLeaderLine(indDir, indLabelPos, indLabelPos.distanceTo(indTarget) * 0.9, 0x22d3ee, 0.15, 0.1));
      addLabel(mkSprite("Induced EMF & current", "#22d3ee", indLabelPos.clone().sub(indDir.multiplyScalar(0.5)), 0.75));

      // Galvanometer
      const galv = push(new THREE.Mesh(
        new THREE.CylinderGeometry(0.5, 0.5, 0.2, 24),
        new THREE.MeshBasicMaterial({ color: 0x475569 }),
      )) as THREE.Mesh;
      galv.position.set(0, -2.5, 1);
      galv.rotation.x = Math.PI / 2;
      addLabel(mkSprite("G", "#475569", new THREE.Vector3(0, -2.5, 1.5), 0.7));

      labelSprites.forEach((s) => (s.visible = showLabels));

      const update = () => {
        while (meshes.length > 60) {
          const m = meshes.pop()!;
          scene.remove(m);
          if (m instanceof THREE.Mesh) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Line) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Sprite) { (m.material as THREE.SpriteMaterial).map?.dispose?.(); m.material.dispose(); }
          else if (m instanceof THREE.ArrowHelper) m.dispose();
        }
      };
      update();

      let prevFlux = fluxAt(magnetX);
      let frameCount = 0;

      const animate = () => {
        frameId = requestAnimationFrame(animate);
        controls.update();
        if (animating) {
          const step = speed * animSpeedRef.current;
          magnetX += step * 0.03 * direction;
          if (magnetX < -5 || magnetX > 5) direction *= -1;
          magnetGroup.position.set(magnetX, 0, 0);

          // Faraday's law: ε = |dΦ/dt| with Φ from the dipole model.
          const dt = 0.016 * step;
          const flux = fluxAt(magnetX);
          const emf = Math.abs((flux - prevFlux) / dt);
          prevFlux = flux;
          if (++frameCount % 10 === 0) {
            setLive({ x: magnetX, flux, emf, approaching: magnetX * direction < 0 });
          }
        }
        renderer.render(scene, camera);
      };
      animate();

      const handleResize = () => {
        if (!container) return;
        camera.aspect = container.clientWidth / container.clientHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(container.clientWidth, container.clientHeight);
      };
      window.addEventListener("resize", handleResize);
      // Re-fit the canvas whenever the container itself resizes (screen fit)
      const resizeObserver = new ResizeObserver(() => handleResize());
      resizeObserver.observe(container);

      return () => {
        cancelAnimationFrame(frameId);
        window.removeEventListener("resize", handleResize);
        resizeObserver?.disconnect();
        if (renderer.domElement.parentNode) renderer.domElement.parentNode.removeChild(renderer.domElement);
        meshes.forEach((m) => {
          scene.remove(m);
          if (m instanceof THREE.Mesh) { m.geometry?.dispose(); const mat = m.material; if (Array.isArray(mat)) mat.forEach((x) => x.dispose()); else (Array.isArray(mat) ? mat : [mat]).forEach((x) => x.dispose()); }
          else if (m instanceof THREE.Line) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Sprite) { const sm = m.material; sm.map?.dispose?.(); sm.dispose(); }
          else if (m instanceof THREE.ArrowHelper) m.dispose();
        });
        renderer.dispose();
        controls.dispose?.();
      };
    };

    const cleanup = init();
    return () => { cleanup.then((d) => d?.()); };
  }, [speed, animating, isWebGL, runId, showLabels, showField]);

  if (!isWebGL) {
    return <WebGLFallback title="EM Induction" description="Coil + magnet animation showing electromagnetic induction." />;
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex flex-wrap items-center gap-2">
          <span>Electromagnetic Induction — Coil & Magnet</span>
          <span className="text-xs text-muted-foreground font-normal">Drag to rotate · Scroll to zoom</span>
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <CollapsibleControls label="Induction Parameters">
          <div className="flex flex-wrap gap-4 mt-2">
            <div className="w-24">
              <Label className="text-xs text-muted-foreground">Speed:</Label>
              <Input type="range" min={0.5} max={5} step={0.5} value={speed} onChange={(e) => setSpeed(Number(e.target.value))} className="mt-1 w-full" />
              <p className="text-xs font-mono text-primary mt-1">{speed.toFixed(1)}</p>
            </div>
          </div>
        </CollapsibleControls>

        <div className="flex flex-wrap items-center justify-between gap-3">
          <PlaybackBar
            playing={animating}
            onPlayToggle={() => setAnimating(!animating)}
            speed={animSpeed}
            onSpeedChange={setAnimSpeed}
            onReset={resetAll}
          />
          <div className="flex flex-wrap items-center gap-2">
            <button
              onClick={() => setShowLabels((v) => !v)}
              className={`px-2.5 py-1 rounded-md text-xs font-medium border transition-colors ${showLabels ? "border-primary/50 bg-primary/10 text-primary" : "border-border bg-muted/40 text-muted-foreground"}`}
            >
              Labels
            </button>
            <button
              onClick={() => setShowField((v) => !v)}
              className={`px-2.5 py-1 rounded-md text-xs font-medium border transition-colors ${showField ? "border-purple-500/50 bg-purple-500/10 text-purple-400" : "border-border bg-muted/40 text-muted-foreground"}`}
            >
              Field line
            </button>
          </div>
        </div>

        <ScenePresets presets={presets} />

        <div ref={containerRef} className="relative h-[clamp(320px,60vh,640px)] w-full overflow-hidden rounded-lg border border-border bg-slate-900">
          <VizToolbar targetRef={vizTargetRef} />
        </div>

        <ReadoutGrid
          items={[
            { label: "Magnet position x", value: live.x.toFixed(2), unit: "m" },
            { label: "Flux Φ (N·B·A)", value: (live.flux * 1000).toFixed(3), unit: "mWb" },
            { label: "Induced emf ε", value: (live.emf * 1000).toFixed(2), unit: "mV", highlight: live.emf > 0.001 },
            { label: "Flux change", value: live.approaching ? "Increasing → oppose" : "Decreasing → support" },
          ]}
        />

        <div className="rounded-lg border border-purple-500/30 bg-purple-500/5 p-4">
          <p className="text-xs font-semibold uppercase tracking-wide text-purple-400">Key Concepts</p>
          <div className="mt-2 space-y-1.5 text-xs text-muted-foreground">
            <p><strong className="text-foreground">Faraday's Law:</strong> ε = −N(dΦ/dt) — induced EMF proportional to rate of change of flux.</p>
            <p><strong className="text-foreground">Lenz's Law:</strong> Induced current opposes the change in flux that produced it (conservation of energy).</p>
            <p><strong className="text-foreground">Magnetic flux:</strong> Φ = B·A·cosθ — flux through a surface.</p>
            <p><strong className="text-foreground">Moving magnet toward coil:</strong> Flux increases → induced current creates opposing field.</p>
            <p><strong className="text-foreground">Moving magnet away:</strong> Flux decreases → induced current tries to maintain flux.</p>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { useRef, useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { CollapsibleControls } from "@/components/lab/collapsible-controls";
import { isWebGLAvailable } from "@/lib/webgl";
import { WebGLFallback } from "@/components/lab/webgl-fallback";
import { VizToolbar, type VizTarget } from "@/components/viz/viz-toolbar";
import { ScenePresets, ReadoutGrid, type ScenePreset } from "@/components/lab/scene-interactivity";
import * as THREE from "three";

/* ============================================================
   Formation of Differential Equations — NEB Calculus (Maths 12)
   Shows how arbitrary constants are eliminated to form DEs,
   with family of curves visualization.
   ============================================================ */

function mkSprite(text: string, color: string, pos: THREE.Vector3, scale = 1.0): THREE.Sprite {
  const canvas = document.createElement("canvas");
  canvas.width = 512;
  canvas.height = 96;
  const ctx = canvas.getContext("2d")!;
  ctx.fillStyle = "rgba(15, 23, 42, 0.9)";
  ctx.fillRect(4, 4, 504, 88);
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.strokeRect(4, 4, 504, 88);
  ctx.font = "bold 28px monospace";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillStyle = color;
  ctx.fillText(text, 256, 48);
  const tex = new THREE.CanvasTexture(canvas);
  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: false }));
  s.position.copy(pos);
  s.scale.set(3.0 * scale, 0.56 * scale, 1);
  return s;
}

type DeFamily = "exp-pm" | "trig" | "exp-23" | "lines";

const FORM_INFO: Record<DeFamily, { general: string; d1: string; d2: string; de: string; note: string; eval: (x: number, k1: number, k2: number) => number; d1eval: (x: number, k1: number, k2: number) => number }> = {
  "exp-pm": {
    general: "y = c₁eˣ + c₂e⁻ˣ",
    d1: "y′ = c₁eˣ − c₂e⁻ˣ",
    d2: "y″ = c₁eˣ + c₂e⁻ˣ = y",
    de: "y″ − y = 0",
    note: "Differentiate twice; y″ reproduces y, so both constants vanish at once.",
    eval: (x, k1, k2) => k1 * Math.exp(x) + k2 * Math.exp(-x),
    d1eval: (x, k1, k2) => k1 * Math.exp(x) - k2 * Math.exp(-x),
  },
  trig: {
    general: "y = c₁cos x + c₂sin x",
    d1: "y′ = −c₁sin x + c₂cos x",
    d2: "y″ = −c₁cos x − c₂sin x = −y",
    de: "y″ + y = 0",
    note: "Simple harmonic motion DE — characteristic roots r = ±i.",
    eval: (x, k1, k2) => k1 * Math.cos(x) + k2 * Math.sin(x),
    d1eval: (x, k1, k2) => -k1 * Math.sin(x) + k2 * Math.cos(x),
  },
  "exp-23": {
    general: "y = c₁e²ˣ + c₂e³ˣ",
    d1: "y′ = 2c₁e²ˣ + 3c₂e³ˣ",
    d2: "y″ = 4c₁e²ˣ + 9c₂e³ˣ",
    de: "y″ − 5y′ + 6y = 0",
    note: "Characteristic equation r² − 5r + 6 = 0 factors as (r − 2)(r − 3) = 0.",
    eval: (x, k1, k2) => k1 * Math.exp(2 * x) + k2 * Math.exp(3 * x),
    d1eval: (x, k1, k2) => 2 * k1 * Math.exp(2 * x) + 3 * k2 * Math.exp(3 * x),
  },
  lines: {
    general: "y = c₁x + c₂ (family of straight lines)",
    d1: "y′ = c₁",
    d2: "y″ = 0",
    de: "y″ = 0",
    note: "Two arbitrary constants → a second-order DE whose solutions are all lines.",
    eval: (x, k1, k2) => k1 * x + k2,
    d1eval: (_x, k1) => k1,
  },
};

export function FormationDEVisual() {
  const containerRef = useRef<HTMLDivElement>(null);
  const vizTargetRef = useRef<VizTarget>({});
  const [family, setFamily] = useState<DeFamily>("exp-pm");
  const [c1, setC1] = useState(1);
  const [c2, setC2] = useState(0);
  const [isWebGL] = useState(() => isWebGLAvailable());
  const [showLabels, setShowLabels] = useState(true);
  const [runId, setRunId] = useState(0);

  const info = FORM_INFO[family];
  const fmtD = (v: number) => (isFinite(v) ? v.toFixed(2) : "∞");

  const presets: ScenePreset[] = [
    { name: "y″ − y = 0", hint: "From y = c₁eˣ + c₂e⁻ˣ", apply: () => { setFamily("exp-pm"); setC1(1); setC2(0); setRunId((r) => r + 1); } },
    { name: "y″ + y = 0", hint: "From y = c₁cos x + c₂sin x", apply: () => { setFamily("trig"); setC1(1); setC2(0); setRunId((r) => r + 1); } },
    { name: "y″ − 5y′ + 6y = 0", hint: "From y = c₁e²ˣ + c₂e³ˣ", apply: () => { setFamily("exp-23"); setC1(1); setC2(0.5); setRunId((r) => r + 1); } },
    { name: "y″ = 0", hint: "From the family of lines y = c₁x + c₂", apply: () => { setFamily("lines"); setC1(1); setC2(1); setRunId((r) => r + 1); } },
  ];

  const resetAll = () => {
    setFamily("exp-pm");
    setC1(1);
    setC2(0);
    setShowLabels(true);
    setRunId((r) => r + 1);
  };


  useEffect(() => {
    const container = containerRef.current;
    if (!container || !isWebGL) return;

    let scene: THREE.Scene, camera: THREE.PerspectiveCamera, renderer: THREE.WebGLRenderer;
    let controls: any, frameId: number;
    const meshes: THREE.Object3D[] = [];
    const labelSprites: THREE.Sprite[] = [];

    const init = async () => {
      const { OrbitControls } = await import("three/addons/controls/OrbitControls.js");

      scene = new THREE.Scene();
      scene.background = new THREE.Color(0x0f172a);
      camera = new THREE.PerspectiveCamera(50, container.clientWidth / container.clientHeight, 0.1, 100);
      camera.position.set(0, 0, 14);

      renderer = new THREE.WebGLRenderer({ antialias: true });
      renderer.setSize(container.clientWidth, container.clientHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      container.appendChild(renderer.domElement);

      controls = new OrbitControls(camera, renderer.domElement);
      controls.enableDamping = true;
      vizTargetRef.current = { controls, el: container, canvasEl: renderer.domElement, setLabels: (on: boolean) => labelSprites.forEach((s) => (s.visible = on)) };
      controls.autoRotate = false;

      scene.add(new THREE.AmbientLight(0xffffff, 0.8));

      const push = <T extends THREE.Object3D>(o: T): T => { scene.add(o); meshes.push(o); return o; };

      push(new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(-10, 0, 0), new THREE.Vector3(10, 0, 0)]), new THREE.LineBasicMaterial({ color: 0xef4444 })));
      push(new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, -10, 0), new THREE.Vector3(0, 10, 0)]), new THREE.LineBasicMaterial({ color: 0x22c55e })));
      for (let i = -10; i <= 10; i++) {
        if (i === 0) continue;
        push(new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(i, -10, 0), new THREE.Vector3(i, 10, 0)]), new THREE.LineBasicMaterial({ color: 0x1e293b })));
        push(new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(-10, i, 0), new THREE.Vector3(10, i, 0)]), new THREE.LineBasicMaterial({ color: 0x1e293b })));
      }

      const update = () => {
        while (meshes.length > 30) {
          const m = meshes.pop()!;
          scene.remove(m);
          if (m instanceof THREE.Mesh) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Line) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Sprite) { (m.material as THREE.SpriteMaterial).map?.dispose?.(); m.material.dispose(); }
        }

        // Family of curves for the selected general solution (2 arbitrary constants)
        const curveFn = info.eval;
        const colors = [0xef4444, 0x3b82f6, 0x22c55e, 0xfbbf24, 0xa78bfa, 0xf97316];
        for (let i = 0; i < 6; i++) {
          const cc1 = c1 + (i - 2) * 0.5;
          const cc2 = c2 + (i % 3 - 1) * 0.5;
          const pts: THREE.Vector3[] = [];
          for (let j = 0; j <= 200; j++) {
            const x = -8 + (j / 200) * 16;
            const y = curveFn(x, cc1, cc2);
            if (isFinite(y) && Math.abs(y) < 12) {
              pts.push(new THREE.Vector3(x, y, 0.02));
            }
          }
          push(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), new THREE.LineBasicMaterial({ color: colors[i], linewidth: 1 })));
        }

        // Highlight the specific curve for current c1, c2
        const mainPts: THREE.Vector3[] = [];
        for (let j = 0; j <= 200; j++) {
          const x = -8 + (j / 200) * 16;
          const y = curveFn(x, c1, c2);
          if (isFinite(y) && Math.abs(y) < 12) {
            mainPts.push(new THREE.Vector3(x, y, 0.05));
          }
        }
        push(new THREE.Line(new THREE.BufferGeometry().setFromPoints(mainPts), new THREE.LineBasicMaterial({ color: 0x22d3ee, linewidth: 3 })));

        labelSprites.push(push(mkSprite(`${info.general}   →   ${info.de}`, "#fbbf24", new THREE.Vector3(0, 8.5, 0), 0.85)));
        labelSprites.push(push(mkSprite(`2 arbitrary constants → 2nd order DE`, "#a78bfa", new THREE.Vector3(0, 7.5, 0), 0.75)));
        labelSprites.push(push(mkSprite(`c₁=${c1.toFixed(1)}, c₂=${c2.toFixed(1)}`, "#7dd3fc", new THREE.Vector3(-7, -8.5, 0), 0.7)));
      };

      update();
      labelSprites.forEach((s) => (s.visible = showLabels));

      const animate = () => {
        frameId = requestAnimationFrame(animate);
        controls.update();
        renderer.render(scene, camera);
      };
      animate();

      const handleResize = () => {
        if (!container) return;
        camera.aspect = container.clientWidth / container.clientHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(container.clientWidth, container.clientHeight);
      };
      window.addEventListener("resize", handleResize);
      // Re-fit the canvas whenever the container itself resizes (screen fit)
      const resizeObserver = new ResizeObserver(() => handleResize());
      resizeObserver.observe(container);

      return () => {
        cancelAnimationFrame(frameId);
        window.removeEventListener("resize", handleResize);
        resizeObserver?.disconnect();
        if (renderer.domElement.parentNode) renderer.domElement.parentNode.removeChild(renderer.domElement);
        meshes.forEach((m) => {
          scene.remove(m);
          if (m instanceof THREE.Mesh) { m.geometry?.dispose(); const mat = m.material; if (Array.isArray(mat)) mat.forEach((x) => x.dispose()); else (Array.isArray(mat) ? mat : [mat]).forEach((x) => x.dispose()); }
          else if (m instanceof THREE.Line) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Sprite) { const sm = m.material; sm.map?.dispose?.(); sm.dispose(); }
        });
        renderer.dispose();
        controls.dispose?.();
      };
    };

    const cleanup = init();
    return () => { cleanup.then((d) => d?.()); };
  }, [family, c1, c2, isWebGL, runId, showLabels]);

  if (!isWebGL) {
    return <WebGLFallback title="Formation of DE" description="Family of curves — requires WebGL." />;
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex flex-wrap items-center gap-2">
          <span>Formation of Differential Equations</span>
          <span className="text-xs text-muted-foreground font-normal">Eliminating arbitrary constants</span>
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <ScenePresets presets={presets} />
          <div className="flex flex-wrap items-center gap-2">
            <button onClick={() => setShowLabels((v) => !v)} className={`px-2.5 py-1 rounded-md text-xs font-medium border transition-colors ${showLabels ? "border-violet-500/50 bg-violet-500/10 text-violet-300" : "border-border bg-muted/40 text-muted-foreground"}`}>Labels</button>
            <button onClick={resetAll} className="px-2.5 py-1 rounded-md text-xs font-medium border border-border bg-muted/40 text-muted-foreground hover:bg-muted/70 transition-colors" title="Reset to defaults">Reset</button>
          </div>
        </div>

        <CollapsibleControls label="General Solution (curve family)">
          <div className="flex flex-wrap gap-2 mt-2">
            {(["exp-pm", "trig", "exp-23", "lines"] as DeFamily[]).map((fam) => (
              <button
                key={fam}
                onClick={() => setFamily(fam)}
                className={`px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${
                  family === fam ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground hover:bg-muted/80"
                }`}
              >
                {FORM_INFO[fam].de}
              </button>
            ))}
          </div>
        </CollapsibleControls>

        <CollapsibleControls label="Constants (family of curves)">
          <div className="flex gap-3 mt-2">
            <div className="w-16"><Label className="text-xs text-muted-foreground">c₁:</Label><Input type="number" step="0.5" value={c1} onChange={(e) => setC1(Number(e.target.value))} className="mt-1" /></div>
            <div className="w-16"><Label className="text-xs text-muted-foreground">c₂:</Label><Input type="number" step="0.5" value={c2} onChange={(e) => setC2(Number(e.target.value))} className="mt-1" /></div>
          </div>
        </CollapsibleControls>

        <div ref={containerRef} className="relative h-[clamp(320px,60vh,640px)] w-full overflow-hidden rounded-lg border border-border bg-slate-900">
          <VizToolbar targetRef={vizTargetRef} />
        </div>

        <ReadoutGrid
          items={[
            { label: "Family of curves", value: info.general },
            { label: "First derivative", value: info.d1 },
            { label: "Second derivative", value: info.d2 },
            { label: "Formed DE", value: info.de, highlight: true },
            { label: `Particular curve (c₁=${c1.toFixed(1)}, c₂=${c2.toFixed(1)})`, value: `y(0) = ${fmtD(info.eval(0, c1, c2))}, y′(0) = ${fmtD(info.d1eval(0, c1, c2))}` },
            { label: "Elimination", value: info.note },
          ]}
        />

        <div className="rounded-lg border border-violet-500/30 bg-violet-500/5 p-4">
          <p className="text-xs font-semibold uppercase tracking-wide text-violet-400">Key Idea · {info.general}</p>
          <div className="mt-2 space-y-1.5 text-xs text-muted-foreground">
            <p><strong className="text-foreground">Rule:</strong> To eliminate n arbitrary constants, differentiate n times to get n+1 equations, then eliminate constants.</p>
            <p><strong className="text-foreground">Example:</strong> {info.general} → {info.d1} → {info.d2} → <strong className="text-foreground">{info.de}</strong></p>
            <p><strong className="text-foreground">Order of DE</strong> = number of arbitrary constants eliminated</p>
            <p><strong className="text-foreground">Each curve</strong> in the family corresponds to specific values of c₁, c₂.</p>
            <p><strong className="text-foreground">Note:</strong> {info.note}</p>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { useRef, useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { CollapsibleControls } from "@/components/lab/collapsible-controls";
import { isWebGLAvailable } from "@/lib/webgl";
import { WebGLFallback } from "@/components/lab/webgl-fallback";
import { VizToolbar, type VizTarget } from "@/components/viz/viz-toolbar";
import { ScenePresets, ReadoutGrid, type ScenePreset } from "@/components/lab/scene-interactivity";
import * as THREE from "three";

/* ============================================================
   Functions — NEB Algebra (Maths 11)
   Interactive function explorer: domain, range, inverse,
   composite, and various function types.
   ============================================================ */

function mkSprite(text: string, color: string, pos: THREE.Vector3, scale = 1.0): THREE.Sprite {
  const canvas = document.createElement("canvas");
  canvas.width = 512;
  canvas.height = 96;
  const ctx = canvas.getContext("2d")!;
  ctx.fillStyle = "rgba(15, 23, 42, 0.9)";
  ctx.fillRect(4, 4, 504, 88);
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.strokeRect(4, 4, 504, 88);
  ctx.font = "bold 32px monospace";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillStyle = color;
  ctx.fillText(text, 256, 48);
  const tex = new THREE.CanvasTexture(canvas);
  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: false }));
  s.position.copy(pos);
  s.scale.set(3.0 * scale, 0.56 * scale, 1);
  return s;
}

type FuncType = "linear" | "quadratic" | "cubic" | "reciprocal" | "exponential" | "logarithmic" | "trig" | "inverse";

const FUNC_INFO: Record<FuncType, { general: string; feature: string }> = {
  linear: { general: "y = ax + b — straight line", feature: "Constant gradient a; y-intercept b; no extrema." },
  quadratic: { general: "y = ax² + bx + c — parabola", feature: "Vertex at x = −b/2a; roots x = (−b ± √(b²−4ac))/2a." },
  cubic: { general: "y = ax³ + bx — cubic", feature: "Odd symmetry about the origin; inflection at (0, 0)." },
  reciprocal: { general: "y = a/(x − b) — hyperbola", feature: "Vertical asymptote x = b; horizontal asymptote y = 0." },
  exponential: { general: "y = a·e^(bx) — exponential", feature: "One-signed; passes through (0, a); y = 0 is a horizontal asymptote." },
  logarithmic: { general: "y = a·ln|x − b| — logarithmic", feature: "Inverse of the exponential; vertical asymptote x = b; zeros at x = b ± 1." },
  trig: { general: "y = a·sin(bx) — sine wave", feature: "Amplitude |a|, period 2π/|b|, odd function." },
  inverse: { general: "y = a√|x| — root type", feature: "Steep near the origin, then flattens; mirror of a parabola about y = x." },
};

export function FunctionVisual() {
  const containerRef = useRef<HTMLDivElement>(null);
  const vizTargetRef = useRef<VizTarget>({});
  const [funcType, setFuncType] = useState<FuncType>("quadratic");
  const [params, setParams] = useState({ a: 1, b: -2, c: -3, k: 1, h: 0 });
  const [showDomainRange, setShowDomainRange] = useState(true);
  const [isWebGL] = useState(() => isWebGLAvailable());
  const [showLabels, setShowLabels] = useState(true);
  const [runId, setRunId] = useState(0);

  const info = FUNC_INFO[funcType];

  const funcExpr = (x: number): number => {
    switch (funcType) {
      case "linear": return params.a * x + params.b;
      case "quadratic": return params.a * x * x + params.b * x + params.c;
      case "cubic": return params.a * x * x * x + params.b * x;
      case "reciprocal": return params.a / (x - params.b);
      case "exponential": return params.a * Math.exp(params.b * x);
      case "logarithmic": return params.a * Math.log(Math.abs(x - params.b) + 0.1);
      case "trig": return params.a * Math.sin(params.b * x);
      case "inverse": return params.a * Math.sqrt(Math.abs(x));
    }
  };
  const fmtVal = (v: number) => (isFinite(v) ? v.toFixed(2) : "undefined");

  let domainLabel = "all reals (ℝ)";
  let rangeLabel = "all reals (ℝ)";
  if (funcType === "logarithmic") { domainLabel = `x ≠ ${params.b}`; rangeLabel = "all reals (ℝ)"; }
  else if (funcType === "reciprocal") { domainLabel = `x ≠ ${params.b}`; rangeLabel = "y ≠ 0"; }
  else if (funcType === "inverse") { domainLabel = "all reals (plot of a√|x|)"; rangeLabel = params.a >= 0 ? "y ≥ 0" : "y ≤ 0"; }
  else if (funcType === "exponential") { rangeLabel = params.a > 0 ? "y > 0" : params.a < 0 ? "y < 0" : "y = 0"; }
  else if (funcType === "trig") { rangeLabel = `−${Math.abs(params.a).toFixed(1)} ≤ y ≤ ${Math.abs(params.a).toFixed(1)}`; }
  else if (funcType === "quadratic" && params.a !== 0) {
    const vy = params.c - (params.b * params.b) / (4 * params.a);
    rangeLabel = params.a > 0 ? `y ≥ ${vy.toFixed(2)}` : `y ≤ ${vy.toFixed(2)}`;
  } else if (funcType === "linear" && params.a === 0) { rangeLabel = `y = ${params.b}`; }

  const presets: ScenePreset[] = [
    { name: "Parabola x² − 2x − 3", hint: "Roots at x = 3 and x = −1", apply: () => { setFuncType("quadratic"); setParams({ a: 1, b: -2, c: -3, k: 1, h: 0 }); setRunId((r) => r + 1); } },
    { name: "Sine wave 2 sin 2x", hint: "Amplitude 2, period π", apply: () => { setFuncType("trig"); setParams({ a: 2, b: 2, c: -3, k: 1, h: 0 }); setRunId((r) => r + 1); } },
    { name: "Exponential eˣ", hint: "Grows through (0, 1)", apply: () => { setFuncType("exponential"); setParams({ a: 1, b: 1, c: -3, k: 1, h: 0 }); setRunId((r) => r + 1); } },
    { name: "Hyperbola 1/x", hint: "Asymptotes x = 0 and y = 0", apply: () => { setFuncType("reciprocal"); setParams({ a: 1, b: 0, c: -3, k: 1, h: 0 }); setRunId((r) => r + 1); } },
  ];

  const resetAll = () => {
    setFuncType("quadratic");
    setParams({ a: 1, b: -2, c: -3, k: 1, h: 0 });
    setShowDomainRange(true);
    setShowLabels(true);
    setRunId((r) => r + 1);
  };


  useEffect(() => {
    const container = containerRef.current;
    if (!container || !isWebGL) return;

    const getFunc = funcExpr;

    let scene: THREE.Scene, camera: THREE.PerspectiveCamera, renderer: THREE.WebGLRenderer;
    let controls: any, frameId: number;
    const meshes: THREE.Object3D[] = [];
    const labelSprites: THREE.Sprite[] = [];

    const init = async () => {
      const { OrbitControls } = await import("three/addons/controls/OrbitControls.js");

      scene = new THREE.Scene();
      scene.background = new THREE.Color(0x0f172a);
      camera = new THREE.PerspectiveCamera(50, container.clientWidth / container.clientHeight, 0.1, 100);
      camera.position.set(0, 0, 14);

      renderer = new THREE.WebGLRenderer({ antialias: true });
      renderer.setSize(container.clientWidth, container.clientHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      container.appendChild(renderer.domElement);

      controls = new OrbitControls(camera, renderer.domElement);
      controls.enableDamping = true;
      vizTargetRef.current = { controls, el: container, canvasEl: renderer.domElement, setLabels: (on: boolean) => labelSprites.forEach((s) => (s.visible = on)) };
      controls.autoRotate = false;

      scene.add(new THREE.AmbientLight(0xffffff, 0.8));

      const push = <T extends THREE.Object3D>(o: T): T => { scene.add(o); meshes.push(o); return o; };

      const mkAxis = (from: THREE.Vector2, to: THREE.Vector2, color: number, label: string) => {
        push(new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(from.x, from.y, 0), new THREE.Vector3(to.x, to.y, 0)]), new THREE.LineBasicMaterial({ color })));
        push(mkSprite(label, `#${color.toString(16).padStart(6, "0")}`, new THREE.Vector3(to.x, to.y, 0.05), 0.6));
      };
      mkAxis(new THREE.Vector2(-10, 0), new THREE.Vector2(10, 0), 0xef4444, "x");
      mkAxis(new THREE.Vector2(0, -10), new THREE.Vector2(0, 10), 0x22c55e, "y");
      for (let i = -10; i <= 10; i++) {
        if (i === 0) continue;
        push(new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(i, -10, 0), new THREE.Vector3(i, 10, 0)]), new THREE.LineBasicMaterial({ color: 0x1e293b })));
        push(new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(-10, i, 0), new THREE.Vector3(10, i, 0)]), new THREE.LineBasicMaterial({ color: 0x1e293b })));
      }

      const update = () => {
        while (meshes.length > 30) {
          const m = meshes.pop()!;
          scene.remove(m);
          if (m instanceof THREE.Mesh) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Line) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Sprite) { (m.material as THREE.SpriteMaterial).map?.dispose?.(); m.material.dispose(); }
        }

        const curvePts: THREE.Vector3[] = [];
        let dyMin = Infinity, dyMax = -Infinity;
        for (let i = 0; i <= 400; i++) {
          const x = -10 + (i / 400) * 20;
          try {
            const y = getFunc(x);
            if (isFinite(y) && Math.abs(y) < 50) {
              curvePts.push(new THREE.Vector3(x, y, 0.02));
              dyMin = Math.min(dyMin, y);
              dyMax = Math.max(dyMax, y);
            } else {
              curvePts.push(curvePts[curvePts.length - 1]);
            }
          } catch {
            curvePts.push(curvePts[curvePts.length - 1]);
          }
        }
        push(new THREE.Line(new THREE.BufferGeometry().setFromPoints(curvePts), new THREE.LineBasicMaterial({ color: 0x22d3ee, linewidth: 2 })));

        if (showDomainRange) {
          const fName = funcType.charAt(0).toUpperCase() + funcType.slice(1);
          const labelY = Math.min(8, Math.max(-8, dyMax + 1.5));
          labelSprites.push(push(mkSprite(`f(x) = ${fName}  Domain: ${domainLabel}`, "#7dd3fc", new THREE.Vector3(-7, labelY, 0), 0.8)));
          labelSprites.push(push(mkSprite(`Range: ${rangeLabel}`, "#fb923c", new THREE.Vector3(-7, labelY - 1.0, 0), 0.8)));
        }
      };

      update();
      labelSprites.forEach((s) => (s.visible = showLabels));

      const animate = () => {
        frameId = requestAnimationFrame(animate);
        controls.update();
        renderer.render(scene, camera);
      };
      animate();

      const handleResize = () => {
        if (!container) return;
        camera.aspect = container.clientWidth / container.clientHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(container.clientWidth, container.clientHeight);
      };
      window.addEventListener("resize", handleResize);
      // Re-fit the canvas whenever the container itself resizes (screen fit)
      const resizeObserver = new ResizeObserver(() => handleResize());
      resizeObserver.observe(container);

      return () => {
        cancelAnimationFrame(frameId);
        window.removeEventListener("resize", handleResize);
        resizeObserver?.disconnect();
        if (renderer.domElement.parentNode) renderer.domElement.parentNode.removeChild(renderer.domElement);
        meshes.forEach((m) => {
          scene.remove(m);
          if (m instanceof THREE.Mesh) { m.geometry?.dispose(); const mat = m.material; if (Array.isArray(mat)) mat.forEach((x) => x.dispose()); else (Array.isArray(mat) ? mat : [mat]).forEach((x) => x.dispose()); }
          else if (m instanceof THREE.Line) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Sprite) { const sm = m.material; sm.map?.dispose?.(); sm.dispose(); }
        });
        renderer.dispose();
        controls.dispose?.();
      };
    };

    const cleanup = init();
    return () => { cleanup.then((d) => d?.()); };
  }, [funcType, params, showDomainRange, isWebGL, runId, showLabels]);

  if (!isWebGL) {
    return <WebGLFallback title="Functions" description="Function graph explorer — requires WebGL." />;
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex flex-wrap items-center gap-2">
          <span>Functions — Domain, Range &amp; Types</span>
          <span className="text-xs text-muted-foreground font-normal">Explore different function families</span>
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <ScenePresets presets={presets} />
          <div className="flex flex-wrap items-center gap-2">
            <button onClick={() => setShowLabels((v) => !v)} className={`px-2.5 py-1 rounded-md text-xs font-medium border transition-colors ${showLabels ? "border-blue-500/50 bg-blue-500/10 text-blue-300" : "border-border bg-muted/40 text-muted-foreground"}`}>Labels</button>
            <button onClick={resetAll} className="px-2.5 py-1 rounded-md text-xs font-medium border border-border bg-muted/40 text-muted-foreground hover:bg-muted/70 transition-colors" title="Reset to defaults">Reset</button>
          </div>
        </div>

        <CollapsibleControls label="Function Type">
          <Tabs value={funcType} onValueChange={(v) => setFuncType(v as FuncType)} className="mt-1">
            <TabsList className="grid w-full grid-cols-4">
              <TabsTrigger value="linear" className="text-xs">Linear</TabsTrigger>
              <TabsTrigger value="quadratic" className="text-xs">Quadratic</TabsTrigger>
              <TabsTrigger value="cubic" className="text-xs">Cubic</TabsTrigger>
              <TabsTrigger value="reciprocal" className="text-xs">Reciprocal</TabsTrigger>
              <TabsTrigger value="exponential" className="text-xs">Exponential</TabsTrigger>
              <TabsTrigger value="logarithmic" className="text-xs">Logarithmic</TabsTrigger>
              <TabsTrigger value="trig" className="text-xs">Trigonometric</TabsTrigger>
              <TabsTrigger value="inverse" className="text-xs">Inverse/Root</TabsTrigger>
            </TabsList>
          </Tabs>
        </CollapsibleControls>

        <CollapsibleControls label="Parameters">
          <div className="flex flex-wrap gap-3 mt-2">
            <div className="w-16"><Label className="text-xs text-muted-foreground">a:</Label><Input type="number" step="0.5" value={params.a} onChange={(e) => setParams({ ...params, a: Number(e.target.value) })} className="mt-1" /></div>
            <div className="w-16"><Label className="text-xs text-muted-foreground">b:</Label><Input type="number" step="0.5" value={params.b} onChange={(e) => setParams({ ...params, b: Number(e.target.value) })} className="mt-1" /></div>
            <div className="w-16"><Label className="text-xs text-muted-foreground">c:</Label><Input type="number" step="0.5" value={params.c} onChange={(e) => setParams({ ...params, c: Number(e.target.value) })} className="mt-1" /></div>
            <div className="w-16"><Label className="text-xs text-muted-foreground">h:</Label><Input type="number" step="0.5" value={params.h} onChange={(e) => setParams({ ...params, h: Number(e.target.value) })} className="mt-1" /></div>
          </div>
        </CollapsibleControls>

        <div ref={containerRef} className="relative h-[clamp(320px,60vh,640px)] w-full overflow-hidden rounded-lg border border-border bg-slate-900">
          <VizToolbar targetRef={vizTargetRef} />
        </div>

        <ReadoutGrid
          items={[
            { label: "Family", value: info.general },
            { label: "Domain", value: domainLabel },
            { label: "Range", value: rangeLabel, highlight: true },
            { label: "f(0)", value: fmtVal(funcExpr(0)) },
            { label: "f(1)", value: fmtVal(funcExpr(1)) },
            { label: "Feature", value: info.feature },
          ]}
        />

        <div className="rounded-lg border border-blue-500/30 bg-blue-500/5 p-4">
          <p className="text-xs font-semibold uppercase tracking-wide text-blue-400">Key Concepts</p>
          <div className="mt-2 space-y-1.5 text-xs text-muted-foreground">
            <p><strong className="text-foreground">Function:</strong> A relation where each input x has exactly one output y = f(x).</p>
            <p><strong className="text-foreground">Domain:</strong> All possible input values (x-values) for which f is defined.</p>
            <p><strong className="text-foreground">Range:</strong> All possible output values (y-values) that f can produce.</p>
            <p><strong className="text-foreground">One-to-one:</strong> Each y-value corresponds to exactly one x-value (passes horizontal line test).</p>
            <p><strong className="text-foreground">Inverse function f⁻¹:</strong> Swaps domain and range; reflects across y = x.</p>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { useRef, useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { CollapsibleControls } from "@/components/lab/collapsible-controls";
import { isWebGLAvailable } from "@/lib/webgl";
import { WebGLFallback } from "@/components/lab/webgl-fallback";
import { VizToolbar, type VizTarget } from "@/components/viz/viz-toolbar";
import {
  ScenePresets,
  PlaybackBar,
  ReadoutGrid,
  type ScenePreset,
} from "@/components/lab/scene-interactivity";
import * as THREE from "three";
import { LiveLeaderLine } from "@/components/lab/leader-lines-3d";

function mkSprite(text: string, color: string, pos: THREE.Vector3, scale = 1.0): THREE.Sprite {
  const canvas = document.createElement("canvas");
  canvas.width = 512;
  canvas.height = 96;
  const ctx = canvas.getContext("2d")!;
  ctx.fillStyle = "rgba(15, 23, 42, 0.9)";
  ctx.fillRect(4, 4, 504, 88);
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.strokeRect(4, 4, 504, 88);
  ctx.font = "bold 32px monospace";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillStyle = color;
  ctx.fillText(text, 256, 48);
  const tex = new THREE.CanvasTexture(canvas);
  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: false }));
  s.position.copy(pos);
  s.scale.set(3.0 * scale, 0.56 * scale, 1);
  return s;
}

export function LenzLawVisual() {
  const containerRef = useRef<HTMLDivElement>(null);
  const vizTargetRef = useRef<VizTarget>({});
  const [direction, setDirection] = useState<"approaching" | "receding">("approaching");
  const [isWebGL] = useState(() => isWebGLAvailable());
  const [animating, setAnimating] = useState(true);
  const [speed, setSpeed] = useState(1);
  // Refs so playback changes never tear down the WebGL scene.
  const speedRef = useRef(1);
  speedRef.current = speed;
  const animatingRef = useRef(true);
  animatingRef.current = animating;
  const [showLabels, setShowLabels] = useState(true);
  const [showField, setShowField] = useState(true);
  const [runId, setRunId] = useState(0);
  // Live physics readouts published (throttled) from the animation loop.
  const [live, setLive] = useState({ x: 6, emf: 0, approaching: true });

  // Faraday/Lenz model: N = 15 turns, coil radius 1.8 m, dipole magnet (μ₀·2m/4π ≈ 2×10⁻⁴ T·m³), R = 10 Ω.
  const TURNS = 15;
  const COIL_AREA = Math.PI * 1.8 * 1.8;
  const RESISTANCE = 10;
  const fluxAt = (x: number) => {
    const d = Math.max(Math.abs(x), 0.6);
    return (TURNS * COIL_AREA * 2e-4) / (d * d * d); // Wb
  };

  const DEFAULTS = { direction: "approaching" as const };
  const presets: ScenePreset[] = [
    {
      name: "Approaching",
      hint: "Magnet moves toward the coil — flux increases, induced pole repels.",
      apply: () => { setDirection("approaching"); setAnimating(true); setSpeed(1); setRunId((r) => r + 1); },
    },
    {
      name: "Receding",
      hint: "Magnet moves away — flux decreases, induced pole attracts.",
      apply: () => { setDirection("receding"); setAnimating(true); setSpeed(1); setRunId((r) => r + 1); },
    },
    {
      name: "Slow-mo approach",
      hint: "Slow motion makes the induced-current response easy to trace.",
      apply: () => { setDirection("approaching"); setAnimating(true); setSpeed(0.25); setRunId((r) => r + 1); },
    },
    {
      name: "Fast recede",
      hint: "Fast withdrawal — large dΦ/dt, strong induced current.",
      apply: () => { setDirection("receding"); setAnimating(true); setSpeed(2); setRunId((r) => r + 1); },
    },
  ];

  const resetAll = () => {
    setDirection(DEFAULTS.direction);
    setAnimating(true);
    setSpeed(1);
    setShowLabels(true);
    setShowField(true);
    setLive({ x: 6, emf: 0, approaching: true });
    setRunId((r) => r + 1);
  };


  useEffect(() => {
    const container = containerRef.current;
    if (!container || !isWebGL) return;

    let scene: THREE.Scene, camera: THREE.PerspectiveCamera, renderer: THREE.WebGLRenderer;
    let controls: any, frameId: number;
    const meshes: THREE.Object3D[] = [];
    const labelSprites: THREE.Sprite[] = [];
    let magnetX = direction === "approaching" ? 6 : -6;
    let movingDir = direction === "approaching" ? -1 : 1;

    const init = async () => {
      const { OrbitControls } = await import("three/addons/controls/OrbitControls.js");

      scene = new THREE.Scene();
      scene.background = new THREE.Color(0x0f172a);
      camera = new THREE.PerspectiveCamera(50, container.clientWidth / container.clientHeight, 0.1, 100);
      camera.position.set(0, 2, 10);

      renderer = new THREE.WebGLRenderer({ antialias: true });
      renderer.setSize(container.clientWidth, container.clientHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      container.appendChild(renderer.domElement);

      controls = new OrbitControls(camera, renderer.domElement);
      controls.enableDamping = true;
      controls.autoRotate = false;
      controls.minDistance = 3;
      controls.maxDistance = 20;
      vizTargetRef.current = {
        controls,
        el: container,
        canvasEl: renderer.domElement,
        setLabels: (on: boolean) => labelSprites.forEach((s) => (s.visible = on)),
      };

      scene.add(new THREE.AmbientLight(0xffffff, 0.7));
      const dir = new THREE.DirectionalLight(0xffffff, 1.0);
      dir.position.set(5, 10, 5);
      scene.add(dir);

      const push = <T extends THREE.Object3D>(o: T): T => { scene.add(o); meshes.push(o); return o; };
      const addLabel = (s: THREE.Sprite): THREE.Sprite => { push(s); labelSprites.push(s); return s; };

      // Coil
      const coilRadius = 1.8;
      const coilLength = 3;
      const turns = 15;
      for (let i = 0; i < turns; i++) {
        const t = i / (turns - 1);
        const x = -coilLength / 2 + t * coilLength;
        const ring = push(new THREE.Mesh(
          new THREE.TorusGeometry(coilRadius, 0.06, 8, 32),
          new THREE.MeshBasicMaterial({ color: 0xfbbf24 }),
        )) as THREE.Mesh;
        ring.position.set(x, 0, 0);
        ring.rotation.y = Math.PI / 2;
      }
      addLabel(mkSprite("Coil", "#fbbf24", new THREE.Vector3(0, 3, 0), 0.7));

      // Magnetic field lines from magnet
      const fieldLinePts: THREE.Vector3[] = [];
      for (let x = -4; x <= 4; x += 0.3) {
        fieldLinePts.push(new THREE.Vector3(x, 0, 0));
      }
      const bField = push(new THREE.Line(
        new THREE.BufferGeometry().setFromPoints(fieldLinePts),
        new THREE.LineDashedMaterial({ color: 0x64748b, dashSize: 0.2, gapSize: 0.15 }),
      ) as any);
      (meshes[meshes.length - 1] as any).computeLineDistances();
      bField.visible = showField;

      // Bar magnet
      const magnetGroup = new THREE.Group();
      const north = push(new THREE.Mesh(
        new THREE.BoxGeometry(0.8, 0.6, 0.6),
        new THREE.MeshBasicMaterial({ color: 0xef4444 }),
      ));
      north.position.set(direction === "approaching" ? 0.4 : -0.4, 0, 0);
      magnetGroup.add(north);
      const south = push(new THREE.Mesh(
        new THREE.BoxGeometry(0.8, 0.6, 0.6),
        new THREE.MeshBasicMaterial({ color: 0x3b82f6 }),
      ));
      south.position.set(direction === "approaching" ? -0.4 : 0.4, 0, 0);
      magnetGroup.add(south);
      magnetGroup.position.set(magnetX, 0, 0);
      meshes.push(magnetGroup);

      // Pole labels
      const nLabelPos = new THREE.Vector3(magnetX + (direction === "approaching" ? 1.2 : -1.2), 1.2, 0);
      addLabel(mkSprite("N", "#ef4444", nLabelPos, 0.8));
      const sLabelPos = new THREE.Vector3(magnetX + (direction === "approaching" ? -1.2 : 1.2), -1.2, 0);
      addLabel(mkSprite("S", "#3b82f6", sLabelPos, 0.8));

      // Flux change label with long arrow
      const fluxLabelPos = new THREE.Vector3(0, -3, 0);
      const fluxTarget = new THREE.Vector3(0, 0, 0);
      const fluxDir = fluxTarget.clone().sub(fluxLabelPos).normalize();
      push(new LiveLeaderLine(fluxDir, fluxLabelPos, fluxLabelPos.distanceTo(fluxTarget) * 0.9, 0xa78bfa, 0.15, 0.1));
      addLabel(mkSprite(
        direction === "approaching" ? "Φ increasing → induced B opposes" : "Φ decreasing → induced B supports",
        "#a78bfa", fluxLabelPos.clone().sub(fluxDir.multiplyScalar(0.5)), 0.75
      ));

      // Induced current direction
      const indLabelPos = new THREE.Vector3(3.5, 1.5, 0);
      const indTarget = new THREE.Vector3(0, 0, 0);
      const indDir = indTarget.clone().sub(indLabelPos).normalize();
      push(new LiveLeaderLine(indDir, indLabelPos, indLabelPos.distanceTo(indTarget) * 0.9, 0x22d3ee, 0.15, 0.1));
      addLabel(mkSprite(
        direction === "approaching" ? "Induced: N pole faces magnet (repel)" : "Induced: S pole faces magnet (attract)",
        "#22d3ee", indLabelPos.clone().sub(indDir.multiplyScalar(0.5)), 0.7
      ));

      // Lenz's law formula
      const lenzLabelPos = new THREE.Vector3(-3.5, 2.5, 0);
      const lenzTarget = new THREE.Vector3(0, 0, 0);
      const lenzDir = lenzTarget.clone().sub(lenzLabelPos).normalize();
      push(new LiveLeaderLine(lenzDir, lenzLabelPos, lenzLabelPos.distanceTo(lenzTarget) * 0.9, 0xef4444, 0.15, 0.1));
      addLabel(mkSprite("ε = −N(dΦ/dt) (Lenz's Law)", "#ef4444", lenzLabelPos.clone().sub(lenzDir.multiplyScalar(0.5)), 0.8));

      labelSprites.forEach((s) => (s.visible = showLabels));

      const update = () => {
        while (meshes.length > 40) {
          const m = meshes.pop()!;
          scene.remove(m);
          if (m instanceof THREE.Mesh) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Line) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Sprite) { (m.material as THREE.SpriteMaterial).map?.dispose?.(); m.material.dispose(); }
          else if (m instanceof THREE.ArrowHelper) m.dispose();
        }
      };
      update();

      let prevFlux = fluxAt(magnetX);
      let frameCount = 0;

      const animate = () => {
        frameId = requestAnimationFrame(animate);
        controls.update();
        if (animatingRef.current) {
          const spd = speedRef.current;
          magnetX += movingDir * 0.02 * spd;
          if (magnetX > 6 || magnetX < -6) movingDir *= -1;
          magnetGroup.position.set(magnetX, 0, 0);

          // ε = |dΦ/dt|; induced current I = ε/R (Lenz: opposes the flux change).
          const dt = 0.016 * spd;
          const flux = fluxAt(magnetX);
          const emf = Math.abs((flux - prevFlux) / dt);
          prevFlux = flux;
          if (++frameCount % 10 === 0) {
            setLive({ x: magnetX, emf, approaching: magnetX * movingDir < 0 });
          }
        }
        renderer.render(scene, camera);
      };
      animate();

      const handleResize = () => {
        if (!container) return;
        camera.aspect = container.clientWidth / container.clientHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(container.clientWidth, container.clientHeight);
      };
      window.addEventListener("resize", handleResize);
      // Re-fit the canvas whenever the container itself resizes (screen fit)
      const resizeObserver = new ResizeObserver(() => handleResize());
      resizeObserver.observe(container);

      return () => {
        cancelAnimationFrame(frameId);
        window.removeEventListener("resize", handleResize);
        resizeObserver?.disconnect();
        if (renderer.domElement.parentNode) renderer.domElement.parentNode.removeChild(renderer.domElement);
        meshes.forEach((m) => {
          scene.remove(m);
          if (m instanceof THREE.Mesh) { m.geometry?.dispose(); const mat = m.material; if (Array.isArray(mat)) mat.forEach((x) => x.dispose()); else (Array.isArray(mat) ? mat : [mat]).forEach((x) => x.dispose()); }
          else if (m instanceof THREE.Line) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Sprite) { const sm = m.material; sm.map?.dispose?.(); sm.dispose(); }
          else if (m instanceof THREE.ArrowHelper) m.dispose();
        });
        renderer.dispose();
        controls.dispose?.();
      };
    };

    const cleanup = init();
    return () => { cleanup.then((d) => d?.()); };
  }, [direction, isWebGL, runId, showLabels, showField]);

  if (!isWebGL) {
    return <WebGLFallback title="Lenz's Law" description="Induced current direction opposing flux change." />;
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex flex-wrap items-center gap-2">
          <span>Lenz's Law — Induced Current Direction</span>
          <span className="text-xs text-muted-foreground font-normal">Drag to rotate · Scroll to zoom</span>
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <CollapsibleControls label="Magnet Motion">
          <div className="flex flex-wrap gap-2 mt-1">
            <button
              onClick={() => setDirection("approaching")}
              className={`px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${
                direction === "approaching" ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground hover:bg-muted/80"
              }`}
            >
              Magnet Approaching
            </button>
            <button
              onClick={() => setDirection("receding")}
              className={`px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${
                direction === "receding" ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground hover:bg-muted/80"
              }`}
            >
              Magnet Receding
            </button>
          </div>
        </CollapsibleControls>

        <div className="flex flex-wrap items-center justify-between gap-3">
          <PlaybackBar
            playing={animating}
            onPlayToggle={() => setAnimating(!animating)}
            speed={speed}
            onSpeedChange={setSpeed}
            onReset={resetAll}
          />
          <div className="flex flex-wrap items-center gap-2">
            <button
              onClick={() => setShowLabels((v) => !v)}
              className={`px-2.5 py-1 rounded-md text-xs font-medium border transition-colors ${showLabels ? "border-primary/50 bg-primary/10 text-primary" : "border-border bg-muted/40 text-muted-foreground"}`}
            >
              Labels
            </button>
            <button
              onClick={() => setShowField((v) => !v)}
              className={`px-2.5 py-1 rounded-md text-xs font-medium border transition-colors ${showField ? "border-purple-500/50 bg-purple-500/10 text-purple-400" : "border-border bg-muted/40 text-muted-foreground"}`}
            >
              Field line
            </button>
          </div>
        </div>

        <ScenePresets presets={presets} />

        <div ref={containerRef} className="relative h-[clamp(320px,60vh,640px)] w-full overflow-hidden rounded-lg border border-border bg-slate-900">
          <VizToolbar targetRef={vizTargetRef} />
        </div>

        <ReadoutGrid
          items={[
            { label: "Magnet position x", value: live.x.toFixed(2), unit: "m" },
            { label: "Induced emf ε", value: (live.emf * 1000).toFixed(2), unit: "mV", highlight: live.emf > 0.001 },
            { label: "Induced current I = ε/R", value: ((live.emf / RESISTANCE) * 1000).toFixed(3), unit: "mA" },
            { label: "Induced pole (Lenz)", value: live.approaching ? "N — repels magnet" : "S — attracts magnet" },
          ]}
        />

        <div className="rounded-lg border border-purple-500/30 bg-purple-500/5 p-4">
          <p className="text-xs font-semibold uppercase tracking-wide text-purple-400">Key Concepts</p>
          <div className="mt-2 space-y-1.5 text-xs text-muted-foreground">
            <p><strong className="text-foreground">Lenz's Law:</strong> The direction of induced EMF is such that it opposes the change in magnetic flux that produced it.</p>
            <p><strong className="text-foreground">Approaching magnet:</strong> Flux increases → induced current creates opposing field (repulsion).</p>
            <p><strong className="text-foreground">Receding magnet:</strong> Flux decreases → induced current reinforces field (attraction).</p>
            <p><strong className="text-foreground">Energy conservation:</strong> Lenz's law is a consequence of conservation of energy.</p>
            <p><strong className="text-foreground">Faraday's Law:</strong> ε = −N(dΦ/dt) — magnitude of induced EMF.</p>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { useRef, useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { CollapsibleControls } from "@/components/lab/collapsible-controls";
import { isWebGLAvailable } from "@/lib/webgl";
import { WebGLFallback } from "@/components/lab/webgl-fallback";
import { VizToolbar, type VizTarget } from "@/components/viz/viz-toolbar";
import { ScenePresets, ReadoutGrid, PlaybackBar, type ScenePreset } from "@/components/lab/scene-interactivity";
import * as THREE from "three";

function mkSprite(text: string, color: string, pos: THREE.Vector3, scale = 1.0): THREE.Sprite {
  const canvas = document.createElement("canvas");
  canvas.width = 512;
  canvas.height = 96;
  const ctx = canvas.getContext("2d")!;
  ctx.fillStyle = "rgba(15, 23, 42, 0.9)";
  ctx.fillRect(4, 4, 504, 88);
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.strokeRect(4, 4, 504, 88);
  ctx.font = "bold 32px monospace";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillStyle = color;
  ctx.fillText(text, 256, 48);
  const tex = new THREE.CanvasTexture(canvas);
  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: false }));
  s.position.copy(pos);
  s.scale.set(3.0 * scale, 0.56 * scale, 1);
  return s;
}

export function LimitsConcept3D() {
  const containerRef = useRef<HTMLDivElement>(null);
  const vizTargetRef = useRef<VizTarget>({});
  const [targetX, setTargetX] = useState(3);
  const [isWebGL] = useState(() => isWebGLAvailable());
  const [showLabels, setShowLabels] = useState(true);
  const [runId, setRunId] = useState(0);
  const [playing, setPlaying] = useState(true);
  const [speed, setSpeed] = useState(1);
  const playingRef = useRef(true);
  const speedRef = useRef(1);
  useEffect(() => { speedRef.current = speed; playingRef.current = playing; }, [speed, playing]);

  const presets: ScenePreset[] = [
    { name: "a = 0", hint: "Limit of 2·sin x at the origin — L = 0", apply: () => { setTargetX(0); setRunId((r) => r + 1); } },
    { name: "a = π/2", hint: "Peak of the curve — L = 2", apply: () => { setTargetX(Math.PI / 2); setRunId((r) => r + 1); } },
    { name: "a = π", hint: "Back to zero crossing — L = 0", apply: () => { setTargetX(Math.PI); setRunId((r) => r + 1); } },
    { name: "a = 3", hint: "Default target", apply: () => { setTargetX(3); setRunId((r) => r + 1); } },
  ];

  const resetAll = () => {
    setTargetX(3);
    setShowLabels(true);
    setPlaying(true);
    setSpeed(1);
    setRunId((r) => r + 1);
  };

  const fx = (t: number) => 2 * Math.sin(t);
  const L = fx(targetX);
  const lhl = fx(targetX - 1e-4);
  const rhl = fx(targetX + 1e-4);
  const epsErr = Math.abs(fx(targetX + 1e-3) - L);

  useEffect(() => {
    const container = containerRef.current;
    if (!container || !isWebGL) return;

    let scene: THREE.Scene, camera: THREE.PerspectiveCamera, renderer: THREE.WebGLRenderer;
    let controls: any;
    let frameId: number;
    let animTime = 0;
    const meshes: THREE.Object3D[] = [];
    const labelSprites: THREE.Sprite[] = [];
    let trailLine: THREE.Line;

    const init = async () => {
      const { OrbitControls } = await import("three/addons/controls/OrbitControls.js");

      scene = new THREE.Scene();
      scene.background = new THREE.Color(0x0f172a);
      camera = new THREE.PerspectiveCamera(50, container.clientWidth / container.clientHeight, 0.1, 100);
      camera.position.set(0, 0, 14);

      renderer = new THREE.WebGLRenderer({ antialias: true });
      renderer.setSize(container.clientWidth, container.clientHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      container.appendChild(renderer.domElement);

      controls = new OrbitControls(camera, renderer.domElement);
      controls.enableDamping = true;
      controls.minDistance = 5;
      controls.maxDistance = 25;
      vizTargetRef.current = { controls, el: container, canvasEl: renderer.domElement, setLabels: (on: boolean) => labelSprites.forEach((s) => (s.visible = on)) };

      scene.add(new THREE.AmbientLight(0xffffff, 0.7));

      const push = <T extends THREE.Object3D>(o: T): T => { scene.add(o); meshes.push(o); return o; };

      const grid = new THREE.GridHelper(20, 20, 0x334155, 0x1e293b);
      grid.rotation.x = Math.PI / 2;
      push(grid);

      const curvePoints: THREE.Vector3[] = [];
      for (let x = -8; x <= 8; x += 0.1) {
        curvePoints.push(new THREE.Vector3(x, Math.sin(x) * 2, 0));
      }
      push(new THREE.Line(new THREE.BufferGeometry().setFromPoints(curvePoints), new THREE.LineBasicMaterial({ color: 0x60a5fa })));

      const targetLineGeom = new THREE.BufferGeometry().setFromPoints([
        new THREE.Vector3(targetX, -5, 0),
        new THREE.Vector3(targetX, 5, 0),
      ]);
      const targetLineMat = new THREE.LineDashedMaterial({ color: 0xf59e0b, dashSize: 0.3, gapSize: 0.2 });
      const targetLine = new THREE.Line(targetLineGeom, targetLineMat);
      targetLine.computeLineDistances();
      push(targetLine);

      push(mkSprite("lim(x→a) f(x) = L", "#60a5fa", new THREE.Vector3(0, 4.5, 0)));
      push(mkSprite(`L = 2·sin(${targetX.toFixed(2)}) = ${L.toFixed(2)}`, "#34d399", new THREE.Vector3(targetX + 1.5, Math.sin(targetX) * 2, 0)));

      const dotGeom = new THREE.SphereGeometry(0.2, 32, 32);
      const dotMat = new THREE.MeshStandardMaterial({ color: 0xf59e0b, emissive: 0xf59e0b, emissiveIntensity: 0.5 });
      const approachDot = push(new THREE.Mesh(dotGeom, dotMat));

      const trailPoints: THREE.Vector3[] = [];
      const trailGeom = new THREE.BufferGeometry().setFromPoints(trailPoints);
      const trailMat = new THREE.LineBasicMaterial({ color: 0xf59e0b, transparent: true, opacity: 0.6 });
      trailLine = push(new THREE.Line(trailGeom, trailMat));

      meshes.forEach((m) => { if (m instanceof THREE.Sprite) labelSprites.push(m); });
      labelSprites.forEach((s) => (s.visible = showLabels));

      const animate = () => {
        frameId = requestAnimationFrame(animate);
        if (playingRef.current) animTime += 0.02 * speedRef.current;
        const xProgress = 1 - Math.exp(-animTime * 0.3);
        approachDot.position.x = -6 + 12 * xProgress;
        approachDot.position.y = Math.sin(approachDot.position.x) * 2;
        if (trailPoints.length === 0 || approachDot.position.distanceTo(trailPoints[trailPoints.length - 1]) > 0.1) {
          trailPoints.push(approachDot.position.clone());
          if (trailPoints.length > 100) trailPoints.shift();
          trailGeom.setFromPoints(trailPoints);
        }
        controls.update();
        renderer.render(scene, camera);
      };
      animate();
    };

    const cleanup = async () => {
      await init();
      return () => {
        cancelAnimationFrame(frameId);
        const parent = renderer.domElement.parentNode;
        if (parent) parent.removeChild(renderer.domElement);
        meshes.forEach((m) => {
          scene.remove(m);
          if (m instanceof THREE.Mesh) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Line) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Sprite) { (m.material as THREE.SpriteMaterial).map?.dispose?.(); m.material.dispose(); }
        });
        renderer.dispose();
        controls.dispose?.();
      };
    };

    const cleanupPromise = cleanup();
    return () => { cleanupPromise.then((d) => d?.()); };
  }, [targetX, isWebGL, runId, showLabels]);

  if (!isWebGL) {
    return <WebGLFallback title="Concept of Limit" description="Animated point approaching a curve — requires WebGL." />;
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex flex-wrap items-center gap-2">
          <span>Concept of Limit — 3D</span>
          <span className="text-xs text-muted-foreground font-normal">Watch the orange dot approach the curve</span>
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <ScenePresets presets={presets} />
          <div className="flex flex-wrap items-center gap-2">
            <button onClick={() => setShowLabels((v) => !v)} className={`px-2.5 py-1 rounded-md text-xs font-medium border transition-colors ${showLabels ? "border-amber-500/50 bg-amber-500/10 text-amber-300" : "border-border bg-muted/40 text-muted-foreground"}`}>Labels</button>
            <button onClick={resetAll} className="px-2.5 py-1 rounded-md text-xs font-medium border border-border bg-muted/40 text-muted-foreground hover:bg-muted/70 transition-colors" title="Reset to defaults">Reset</button>
          </div>
        </div>

        <CollapsibleControls label="Target x-value">
          <div className="w-20 mt-1">
            <Label className="text-xs text-muted-foreground">a:</Label>
            <Input type="number" step="0.5" value={targetX} onChange={(e) => setTargetX(Number(e.target.value))} className="mt-1" />
          </div>
        </CollapsibleControls>

        <div ref={containerRef} className="relative h-[clamp(320px,60vh,640px)] w-full overflow-hidden rounded-lg border border-border bg-slate-900">
          <VizToolbar targetRef={vizTargetRef} />
        </div>

        <PlaybackBar playing={playing} onPlayToggle={() => setPlaying((p) => !p)} speed={speed} onSpeedChange={setSpeed} onReset={resetAll} />

        <ReadoutGrid
          items={[
            { label: "Curve", value: "f(x) = 2·sin x" },
            { label: `L = lim(x→${targetX.toFixed(2)}) f(x)`, value: L.toFixed(4), highlight: true },
            { label: "LHL (x→a⁻)", value: lhl.toFixed(4) },
            { label: "RHL (x→a⁺)", value: rhl.toFixed(4) },
            { label: "f(a) — limit equals value", value: L.toFixed(4) },
            { label: "|f(a+0.001) − L|", value: epsErr.toExponential(2) },
          ]}
        />

        <div className="rounded-lg border border-amber-500/30 bg-amber-500/5 p-4">
          <p className="text-xs font-semibold uppercase tracking-wide text-amber-400">The Limit Concept</p>
          <div className="mt-2 space-y-1.5 text-xs text-muted-foreground">
            <p><strong className="text-foreground">lim(x→a) f(x) = L</strong> means f(x) gets arbitrarily close to L as x approaches a.</p>
            <p><strong className="text-foreground">The dot</strong> traces the curve, showing how the function behaves near a.</p>
            <p><strong className="text-foreground">Trail</strong> shows the path taken — observe how it smooths out near the target.</p>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { useRef, useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { CollapsibleControls } from "@/components/lab/collapsible-controls";
import { isWebGLAvailable } from "@/lib/webgl";
import { WebGLFallback } from "@/components/lab/webgl-fallback";
import { VizToolbar, type VizTarget } from "@/components/viz/viz-toolbar";
import { ScenePresets, ReadoutGrid, PlaybackBar, type ScenePreset } from "@/components/lab/scene-interactivity";
import * as THREE from "three";

/* ============================================================
   Limits & Continuity — NEB Calculus (Maths 11 & 12)
   Animated visualization of lim(x→a) f(x), discontinuities,
   left-hand and right-hand limits.
   ============================================================ */

function mkSprite(text: string, color: string, pos: THREE.Vector3, scale = 1.0): THREE.Sprite {
  const canvas = document.createElement("canvas");
  canvas.width = 512;
  canvas.height = 96;
  const ctx = canvas.getContext("2d")!;
  ctx.fillStyle = "rgba(15, 23, 42, 0.9)";
  ctx.fillRect(4, 4, 504, 88);
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.strokeRect(4, 4, 504, 88);
  ctx.font = "bold 32px monospace";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillStyle = color;
  ctx.fillText(text, 256, 48);
  const tex = new THREE.CanvasTexture(canvas);
  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: false }));
  s.position.copy(pos);
  s.scale.set(3.0 * scale, 0.56 * scale, 1);
  return s;
}

type DiscontinuityType = "removable" | "jump" | "infinite" | "continuous";

/** Analytic one-sided limits of the plotted curves at x = a. */
function limitSides(type: DiscontinuityType, a: number): { lhl: number; rhl: number } {
  switch (type) {
    case "continuous":
    case "removable":
      return { lhl: 1, rhl: 1 }; // 2·sin(x−a)+1 → 1 as x→a
    case "jump":
      return { lhl: 1.5 * Math.sin(a) + 1, rhl: 1.5 * Math.sin(a) - 1 };
    case "infinite":
      return { lhl: -Infinity, rhl: Infinity }; // 2/(x−a)
  }
}

function fmtV(v: number): string {
  if (v === Infinity) return "+∞";
  if (v === -Infinity) return "−∞";
  return v.toFixed(2);
}

const DISC_INFO: Record<DiscontinuityType, { concept: string; formula: string; condition: string; resolution: string; fact: string; tip: string }> = {
  continuous: {
    concept: "Continuous at x = a",
    formula: "f(x) = 2·sin(x−a) + 1",
    condition: "LHL = RHL = f(a)",
    resolution: "The dot slides onto the curve with no break — the limit equals the value.",
    fact: "Every polynomial, sin x, cos x and eˣ is continuous at all real numbers.",
    tip: "Draw it without lifting your pen — that is continuity at Grade-12 level.",
  },
  removable: {
    concept: "Removable discontinuity (hole)",
    formula: "f(x) = 2·sin(x−a) + 1, x ≠ a; f(a) = 2.5",
    condition: "LHL = RHL exists, but f(a) ≠ limit",
    resolution: "Hole at (a, 1), point parked at 2.5 — redefine f(a) = 1 to repair it.",
    fact: "sin x / x at x = 0 is the classic removable discontinuity: limit 1, value undefined.",
    tip: "The limit ignores f(a) entirely — it only watches the approach.",
  },
  jump: {
    concept: "Jump discontinuity",
    formula: "f(x) = 1.5·sin x + 1 (x < a); 1.5·sin x − 1 (x > a)",
    condition: "LHL ≠ RHL",
    resolution: "Two branch heights differ by 2 — the two-sided limit does not exist.",
    fact: "The greatest-integer function ⌊x⌋ jumps by 1 at every integer.",
    tip: "Both one-sided limits exist at a jump; DNE refers only to the two-sided limit.",
  },
  infinite: {
    concept: "Infinite discontinuity (asymptote)",
    formula: "f(x) = 2 / (x−a)",
    condition: "f → −∞ from the left, +∞ from the right",
    resolution: "Vertical asymptote at x = a — no finite limit exists.",
    fact: "1/x at x = 0: the left branch dives to −∞ while the right climbs to +∞.",
    tip: "Writing lim = ∞ records HOW it diverges; strictly, the limit still does not exist.",
  },
};

export function LimitsContinuityVisual() {
  const containerRef = useRef<HTMLDivElement>(null);
  const vizTargetRef = useRef<VizTarget>({});
  const [disType, setDisType] = useState<DiscontinuityType>("continuous");
  const [a, setA] = useState(2);
  const [isWebGL] = useState(() => isWebGLAvailable());
  const [showLabels, setShowLabels] = useState(true);
  const [runId, setRunId] = useState(0);
  const [playing, setPlaying] = useState(true);
  const [speed, setSpeed] = useState(1);
  const playingRef = useRef(true);
  const speedRef = useRef(1);
  useEffect(() => { speedRef.current = speed; playingRef.current = playing; }, [speed, playing]);

  const info = DISC_INFO[disType];
  const sides = limitSides(disType, a);
  const limitExists = disType === "continuous" || disType === "removable";

  const presets: ScenePreset[] = [
    { name: "Continuous", hint: "LHL = RHL = f(a)", apply: () => { setDisType("continuous"); setRunId((r) => r + 1); } },
    { name: "Removable hole", hint: "Limit exists, f(a) ≠ limit", apply: () => { setDisType("removable"); setRunId((r) => r + 1); } },
    { name: "Jump", hint: "LHL ≠ RHL → DNE", apply: () => { setDisType("jump"); setRunId((r) => r + 1); } },
    { name: "Infinite", hint: "Vertical asymptote at x = a", apply: () => { setDisType("infinite"); setRunId((r) => r + 1); } },
  ];

  const resetAll = () => {
    setDisType("continuous");
    setA(2);
    setShowLabels(true);
    setPlaying(true);
    setSpeed(1);
    setRunId((r) => r + 1);
  };


  useEffect(() => {
    const container = containerRef.current;
    if (!container || !isWebGL) return;

    let scene: THREE.Scene, camera: THREE.PerspectiveCamera, renderer: THREE.WebGLRenderer;
    let controls: any;
    let frameId: number;
    let animId: number;
    let animTime = 0;
    const meshes: THREE.Object3D[] = [];
    const labelSprites: THREE.Sprite[] = [];
    let dotPos = 0;

    const init = async () => {
      const { OrbitControls } = await import("three/addons/controls/OrbitControls.js");

      scene = new THREE.Scene();
      scene.background = new THREE.Color(0x0f172a);
      camera = new THREE.PerspectiveCamera(50, container.clientWidth / container.clientHeight, 0.1, 100);
      camera.position.set(0, 0, 14);

      renderer = new THREE.WebGLRenderer({ antialias: true });
      renderer.setSize(container.clientWidth, container.clientHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      container.appendChild(renderer.domElement);

      controls = new OrbitControls(camera, renderer.domElement);
      controls.enableDamping = true;
      controls.autoRotate = false;
      controls.minDistance = 5;
      controls.maxDistance = 25;
      vizTargetRef.current = { controls, el: container, canvasEl: renderer.domElement, setLabels: (on: boolean) => labelSprites.forEach((s) => (s.visible = on)) };

      scene.add(new THREE.AmbientLight(0xffffff, 0.7));

      const push = <T extends THREE.Object3D>(o: T): T => { scene.add(o); meshes.push(o); return o; };

      // Axes
      const mkAxis = (from: THREE.Vector2, to: THREE.Vector2, color: number, label: string) => {
        push(new THREE.Line(
          new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(from.x, from.y, 0), new THREE.Vector3(to.x, to.y, 0)]),
          new THREE.LineBasicMaterial({ color }),
        ));
        push(mkSprite(label, `#${color.toString(16).padStart(6, "0")}`, new THREE.Vector3(to.x, to.y, 0.05), 0.6));
      };
      mkAxis(new THREE.Vector2(-10, 0), new THREE.Vector2(10, 0), 0xef4444, "x");
      mkAxis(new THREE.Vector2(0, -10), new THREE.Vector2(0, 10), 0x22c55e, "y");

      for (let i = -10; i <= 10; i++) {
        if (i === 0) continue;
        push(new THREE.Line(
          new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(i, -10, 0), new THREE.Vector3(i, 10, 0)]),
          new THREE.LineBasicMaterial({ color: 0x1e293b }),
        ));
        push(new THREE.Line(
          new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(-10, i, 0), new THREE.Vector3(10, i, 0)]),
          new THREE.LineBasicMaterial({ color: 0x1e293b }),
        ));
      }

      // Vertical line at x = a
      push(new THREE.Line(
        new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(a, -10, 0), new THREE.Vector3(a, 10, 0)]),
        new THREE.LineDashedMaterial({ color: 0xfbbf24, dashSize: 0.2, gapSize: 0.15 }),
      ) as any);
      (meshes[meshes.length - 1] as any).computeLineDistances();

      const fValues: { left: number; right: number; actual?: number; open?: boolean }[] = [];
      const steps = 200;
      for (let i = 0; i <= steps; i++) {
        const x = -10 + (i / steps) * 20;
        let y: number;
        switch (disType) {
          case "continuous": y = Math.sin(x - a) * 2 + 1; break;
          case "removable":
            y = Math.sin(x - a) * 2 + 1; // curve passes through (a, 1) as a hole — marker drawn separately
            break;
          case "jump":
            y = x < a ? Math.sin(x) * 1.5 + 1 : Math.sin(x) * 1.5 - 1;
            break;
          case "infinite":
            y = 2 / (x - a);
            break;
          default: y = 0;
        }
        fValues.push({
          left: x < a ? y : NaN,
          right: x >= a ? y : NaN,
          actual: y,
          open: disType === "removable" && Math.abs(x - a) < 0.01,
        });
      }

      // Curve line
      const curvePoints: THREE.Vector3[] = [];
      fValues.forEach((v, i) => {
        const x = -10 + (i / steps) * 20;
        if (disType === "infinite" && Math.abs(v.actual!) > 10) return;
        curvePoints.push(new THREE.Vector3(x, v.actual ?? 0, 0.02));
      });
      push(new THREE.Line(new THREE.BufferGeometry().setFromPoints(curvePoints), new THREE.LineBasicMaterial({ color: 0x22d3ee, linewidth: 2 })));

      // Limit-point height at x = a (hole position for the removable case).
      // For removable: f = 2·sin(x−a) + 1 with x ≠ a, so the limit is 1 — not 2.5.
      const limitY = Number.isFinite(sides.lhl) ? sides.lhl : 0;

      // Approaching dot
      const dot = push(new THREE.Mesh(new THREE.SphereGeometry(0.15, 12, 12), new THREE.MeshBasicMaterial({ color: 0xf97316 }))) as THREE.Mesh;
      dot.position.set(-10, 0, 0.05);

      let dir = 1;
      const speed = 0.04;

      const animate = () => {
        frameId = requestAnimationFrame(animate);
        controls.update();
        animTime += 0.016;
        renderer.render(scene, camera);
      };
      animate();

      // Animation loop for approaching dot
      const animLoop = () => {
        animId = requestAnimationFrame(animLoop);
        if (playingRef.current) {
          dotPos += speed * dir * speedRef.current;
          if (dotPos >= a) { dir = -1; dotPos = a; }
          if (dotPos <= -10) { dir = 1; dotPos = -10; }
        }

        let yVal = 0;
        switch (disType) {
          case "continuous": yVal = Math.sin(dotPos - a) * 2 + 1; break;
          case "removable": yVal = Math.sin(dotPos - a) * 2 + 1; break;
          case "jump": yVal = dotPos < a ? Math.sin(dotPos) * 1.5 + 1 : Math.sin(dotPos) * 1.5 - 1; break;
          case "infinite": yVal = dotPos !== a ? 2 / (dotPos - a) : 0; break;
        }

        dot.position.x = dotPos;
        dot.position.y = Math.max(-9, Math.min(9, yVal));
      };
      animLoop();

      // L-hat and R-hat markers — one-sided limits computed analytically
      push(mkSprite(`lim(x→${a}⁻) = ${fmtV(sides.lhl)}`, "#22d3ee", new THREE.Vector3(a - 3, 7, 0), 0.9));
      push(mkSprite(`lim(x→${a}⁺) = ${fmtV(sides.rhl)}`, "#a78bfa", new THREE.Vector3(a + 3, 7, 0), 0.9));

      // f(a) marker (open circle for removable)
      if (disType === "removable") {
        const openCircle = push(new THREE.Mesh(
          new THREE.RingGeometry(0.15, 0.22, 16),
          new THREE.MeshBasicMaterial({ color: 0xef4444, side: THREE.DoubleSide }),
        ) as THREE.Mesh);
        openCircle.position.set(a, limitY, 0.05);
        const fillCircle = push(new THREE.Mesh(
          new THREE.CircleGeometry(0.15, 16),
          new THREE.MeshBasicMaterial({ color: 0xef4444 }),
        ) as THREE.Mesh);
        fillCircle.position.set(a, 2.5, 0.05);
      } else if (disType === "jump") {
        const yLeft = sides.lhl;
        const yRight = sides.rhl;
        const lc = push(new THREE.Mesh(new THREE.SphereGeometry(0.12, 8, 8), new THREE.MeshBasicMaterial({ color: 0x22d3ee }))) as THREE.Mesh;
        lc.position.set(a, yLeft, 0.05);
        const rc = push(new THREE.Mesh(new THREE.SphereGeometry(0.12, 8, 8), new THREE.MeshBasicMaterial({ color: 0xa78bfa }))) as THREE.Mesh;
        rc.position.set(a, yRight, 0.05);
      }

      meshes.forEach((m) => { if (m instanceof THREE.Sprite) labelSprites.push(m); });
      labelSprites.forEach((s) => (s.visible = showLabels));

      return () => {
        cancelAnimationFrame(frameId);
        cancelAnimationFrame(animId);
        if (renderer.domElement.parentNode) renderer.domElement.parentNode.removeChild(renderer.domElement);
        meshes.forEach((m) => {
          scene.remove(m);
          if (m instanceof THREE.Mesh) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Line) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Sprite) { (m.material as THREE.SpriteMaterial).map?.dispose?.(); m.material.dispose(); }
        });
        renderer.dispose();
        controls.dispose?.();
      };
    };

    const cleanup = init();
    return () => { cleanup.then((d) => d?.()); };
  }, [disType, a, isWebGL, runId, showLabels]);

  if (!isWebGL) {
    return <WebGLFallback title="Limits & Continuity" description="Animated limit visualization — requires WebGL." />;
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex flex-wrap items-center gap-2">
          <span>Limits & Continuity</span>
          <span className="text-xs text-muted-foreground font-normal">Watch the orange dot approach x = {a}</span>
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <ScenePresets presets={presets} />
          <div className="flex flex-wrap items-center gap-2">
            <button onClick={() => setShowLabels((v) => !v)} className={`px-2.5 py-1 rounded-md text-xs font-medium border transition-colors ${showLabels ? "border-orange-500/50 bg-orange-500/10 text-orange-300" : "border-border bg-muted/40 text-muted-foreground"}`}>Labels</button>
            <button onClick={resetAll} className="px-2.5 py-1 rounded-md text-xs font-medium border border-border bg-muted/40 text-muted-foreground hover:bg-muted/70 transition-colors" title="Reset to defaults">Reset</button>
          </div>
        </div>

        <CollapsibleControls label="Discontinuity Type">
          <div className="flex flex-wrap gap-2 mt-2">
            {(["continuous", "removable", "jump", "infinite"] as DiscontinuityType[]).map((t) => (
              <button
                key={t}
                onClick={() => setDisType(t)}
                className={`px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${
                  disType === t
                    ? "bg-primary text-primary-foreground"
                    : "bg-muted text-muted-foreground hover:bg-muted/80"
                }`}
              >
                {t === "continuous" ? "Continuous" : t === "removable" ? "Removable" : t === "jump" ? "Jump" : "Infinite"}
              </button>
            ))}
          </div>
        </CollapsibleControls>

        <CollapsibleControls label="Approach Point (a)">
          <div className="w-20 mt-1">
            <Label className="text-xs text-muted-foreground">a:</Label>
            <Input type="number" step="0.5" value={a} onChange={(e) => setA(Number(e.target.value))} className="mt-1" />
          </div>
        </CollapsibleControls>

        <div ref={containerRef} className="relative h-[clamp(320px,60vh,640px)] w-full overflow-hidden rounded-lg border border-border bg-slate-900">
          <VizToolbar targetRef={vizTargetRef} />
        </div>

        <PlaybackBar playing={playing} onPlayToggle={() => setPlaying((p) => !p)} speed={speed} onSpeedChange={setSpeed} onReset={resetAll} />

        <ReadoutGrid
          items={[
            { label: "Behavior", value: info.concept, highlight: true },
            { label: "f(x)", value: info.formula },
            { label: `LHL at x = ${a}`, value: fmtV(sides.lhl) },
            { label: `RHL at x = ${a}`, value: fmtV(sides.rhl) },
            { label: `lim(x→${a}) f(x)`, value: limitExists ? fmtV(sides.lhl) : "Does not exist" },
            { label: `f(${a})`, value: disType === "continuous" ? fmtV(sides.lhl) : disType === "removable" ? "2.50 ≠ limit" : disType === "jump" ? `${fmtV(sides.rhl)} (right branch)` : "undefined (asymptote)" },
          ]}
        />

        <div className="rounded-lg border border-orange-500/30 bg-orange-500/5 p-4">
          <p className="text-xs font-semibold uppercase tracking-wide text-orange-400">Key Ideas</p>
          <div className="mt-2 space-y-1.5 text-xs text-muted-foreground">
            <p><strong className="text-foreground">lim(x→a) f(x) = L</strong> means f(x) gets arbitrarily close to L as x approaches a from both sides.</p>
            <p><strong className="text-foreground">Left-hand limit:</strong> lim(x→a⁻) f(x) — approaching from values less than a.</p>
            <p><strong className="text-foreground">Right-hand limit:</strong> lim(x→a⁺) f(x) — approaching from values greater than a.</p>
            <p><strong className="text-foreground">Continuous at a:</strong> lim(x→a) f(x) = f(a) — all three exist and are equal.</p>
            <p><strong className="text-foreground">Removable discontinuity:</strong> limit exists but f(a) is undefined or different.</p>
            <p><strong className="text-foreground">Jump discontinuity:</strong> LHL ≠ RHL — limit does not exist.</p>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { useRef, useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { CollapsibleControls } from "@/components/lab/collapsible-controls";
import { isWebGLAvailable } from "@/lib/webgl";
import { WebGLFallback } from "@/components/lab/webgl-fallback";
import { VizToolbar, type VizTarget } from "@/components/viz/viz-toolbar";
import { ScenePresets, ReadoutGrid, type ScenePreset } from "@/components/lab/scene-interactivity";
import * as THREE from "three";

/* ============================================================
   LPP Graphical Method — NEB Math 12
   Interactive graphical method showing sliding objective line
   to find optimal corner point.
   ============================================================ */

function mkSprite(text: string, color: string, pos: THREE.Vector3, scale = 1.0): THREE.Sprite {
  const canvas = document.createElement("canvas");
  canvas.width = 512;
  canvas.height = 96;
  const ctx = canvas.getContext("2d")!;
  ctx.fillStyle = "rgba(15, 23, 42, 0.9)";
  ctx.fillRect(4, 4, 504, 88);
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.strokeRect(4, 4, 504, 88);
  ctx.font = "bold 28px monospace";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillStyle = color;
  ctx.fillText(text, 256, 48);
  const tex = new THREE.CanvasTexture(canvas);
  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: false }));
  s.position.copy(pos);
  s.scale.set(3.0 * scale, 0.56 * scale, 1);
  return s;
}

export function LPPGraphicalVisual() {
  const containerRef = useRef<HTMLDivElement>(null);
  const vizTargetRef = useRef<VizTarget>({});
  const [a1, setA1] = useState(2);
  const [b1, setB1] = useState(1);
  const [c1, setC1] = useState(10);
  const [a2, setA2] = useState(1);
  const [b2, setB2] = useState(2);
  const [c2, setC2] = useState(10);
  const [p, setP] = useState(3);
  const [q, setQ] = useState(2);
  const [isoLevel, setIsoLevel] = useState(0);
  const [isWebGL] = useState(() => isWebGLAvailable());
  const [showLabels, setShowLabels] = useState(true);
  const [runId, setRunId] = useState(0);

  const det = a1 * b2 - a2 * b1;
  const ix = det !== 0 ? (c1 * b2 - c2 * b1) / det : NaN;
  const iy = det !== 0 ? (a1 * c2 - a2 * c1) / det : NaN;
  // Axis corners of the feasible region (x ≤ c1/a1 AND x ≤ c2/a2 on y = 0, etc.)
  const xAxisCorner = Math.min(a1 > 0 ? c1 / a1 : Infinity, a2 > 0 ? c2 / a2 : Infinity);
  const yAxisCorner = Math.min(b1 > 0 ? c1 / b1 : Infinity, b2 > 0 ? c2 / b2 : Infinity);
  const hasRegion =
    Number.isFinite(ix) && Number.isFinite(iy) &&
    ix > 0 && iy > 0 &&
    Number.isFinite(xAxisCorner) && Number.isFinite(yAxisCorner) &&
    ix <= xAxisCorner + 1e-9 && iy <= yAxisCorner + 1e-9;
  const cornerList = hasRegion
    ? [{ x: 0, y: 0 }, { x: xAxisCorner, y: 0 }, { x: ix, y: iy }, { x: 0, y: yAxisCorner }]
    : [];
  const zAt = (x: number, y: number) => p * x + q * y;
  const bestCorner = cornerList.length ? cornerList.reduce((m, c) => (zAt(c.x, c.y) > zAt(m.x, m.y) ? c : m)) : null;

  const presets: ScenePreset[] = [
    {
      name: "Classic pair (Z = 3x + 2y)",
      hint: "2x + y ≤ 10, x + 2y ≤ 10 — optimum at the intersection (10/3, 10/3).",
      apply: () => { setA1(2); setB1(1); setC1(10); setA2(1); setB2(2); setC2(10); setP(3); setQ(2); setIsoLevel(0); setRunId((r) => r + 1); },
    },
    {
      name: "Equal weights (p = q = 2)",
      hint: "Z = 2x + 2y — a 45° objective line; ties can occur along an edge.",
      apply: () => { setA1(2); setB1(1); setC1(10); setA2(1); setB2(2); setC2(10); setP(2); setQ(2); setIsoLevel(0); setRunId((r) => r + 1); },
    },
    {
      name: "y-heavy profit (Z = x + 5y)",
      hint: "Steep weight on y — the optimum moves onto the y-axis corner.",
      apply: () => { setA1(2); setB1(1); setC1(10); setA2(1); setB2(2); setC2(10); setP(1); setQ(5); setIsoLevel(0); setRunId((r) => r + 1); },
    },
    {
      name: "Optimal iso-line in place",
      hint: "Slides the orange line px + qy = k to the maximum attainable level k = 17.",
      apply: () => { setA1(2); setB1(1); setC1(10); setA2(1); setB2(2); setC2(10); setP(3); setQ(2); setIsoLevel(17); setRunId((r) => r + 1); },
    },
  ];

  const resetAll = () => {
    setA1(2); setB1(1); setC1(10);
    setA2(1); setB2(2); setC2(10);
    setP(3); setQ(2);
    setIsoLevel(0);
    setShowLabels(true);
    setRunId((r) => r + 1);
  };

  useEffect(() => {
    const container = containerRef.current;
    if (!container || !isWebGL) return;

    let scene: THREE.Scene, camera: THREE.PerspectiveCamera, renderer: THREE.WebGLRenderer;
    let controls: any, frameId: number;
    const meshes: THREE.Object3D[] = [];
    const labelSprites: THREE.Sprite[] = [];

    const init = async () => {
      const { OrbitControls } = await import("three/addons/controls/OrbitControls.js");

      scene = new THREE.Scene();
      scene.background = new THREE.Color(0x0f172a);
      camera = new THREE.PerspectiveCamera(50, container.clientWidth / container.clientHeight, 0.1, 100);
      camera.position.set(0, 0, 14);

      renderer = new THREE.WebGLRenderer({ antialias: true });
      renderer.setSize(container.clientWidth, container.clientHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      container.appendChild(renderer.domElement);

      controls = new OrbitControls(camera, renderer.domElement);
      controls.enableDamping = true;
      vizTargetRef.current = { controls, el: container, canvasEl: renderer.domElement, setLabels: (on: boolean) => labelSprites.forEach((s) => (s.visible = on)) };
      controls.autoRotate = false;

      scene.add(new THREE.AmbientLight(0xffffff, 0.8));

      const push = <T extends THREE.Object3D>(o: T): T => { scene.add(o); meshes.push(o); return o; };
      const addLabel = (s: THREE.Sprite): THREE.Sprite => { push(s); labelSprites.push(s); return s; };

      push(new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(-1, 0, 0), new THREE.Vector3(10, 0, 0)]), new THREE.LineBasicMaterial({ color: 0xef4444 })));
      push(new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, -1, 0), new THREE.Vector3(0, 10, 0)]), new THREE.LineBasicMaterial({ color: 0x22c55e })));

      for (let i = -10; i <= 10; i++) {
        if (i === 0) continue;
        push(new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(i, -10, 0), new THREE.Vector3(i, 10, 0)]), new THREE.LineBasicMaterial({ color: 0x1e293b })));
        push(new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(-10, i, 0), new THREE.Vector3(10, i, 0)]), new THREE.LineBasicMaterial({ color: 0x1e293b })));
      }

      // Grid/axes are static — only meshes added after this line get rebuilt.
      const staticCount = meshes.length;

      const update = () => {
        while (meshes.length > staticCount) {
          const m = meshes.pop()!;
          scene.remove(m);
          if (m instanceof THREE.Mesh) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Line) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Sprite) { (m.material as THREE.SpriteMaterial).map?.dispose?.(); m.material.dispose(); }
        }
        labelSprites.length = 0;

        const drawLine = (a: number, b: number, c: number, color: number) => {
          if (a === 0 && b === 0) return;
          const xInt = a !== 0 ? c / a : Infinity;
          const yInt = b !== 0 ? c / b : Infinity;
          push(new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(Math.max(-1, xInt * 1.2), 0, 0), new THREE.Vector3(0, Math.max(-1, yInt * 1.2), 0)]), new THREE.LineBasicMaterial({ color })));
        };
        drawLine(a1, b1, c1, 0xef4444);
        drawLine(a2, b2, c2, 0x3b82f6);

        // Feasible region: convex quad O → (xA, 0) → (ix, iy) → (0, yA)
        if (hasRegion) {
          const shape = new THREE.Shape();
          shape.moveTo(0, 0);
          shape.lineTo(xAxisCorner, 0);
          shape.lineTo(ix, iy);
          shape.lineTo(0, yAxisCorner);
          shape.closePath();
          push(new THREE.Mesh(new THREE.ShapeGeometry(shape), new THREE.MeshBasicMaterial({ color: 0x22d3ee, transparent: true, opacity: 0.12, side: THREE.DoubleSide })));

          const polyPts: THREE.Vector3[] = [];
          const verts = [new THREE.Vector3(0, 0), new THREE.Vector3(xAxisCorner, 0), new THREE.Vector3(ix, iy), new THREE.Vector3(0, yAxisCorner)];
          for (let i = 0; i <= 80; i++) {
            const idx = Math.floor(i / 20) % 4;
            const nextIdx = (idx + 1) % 4;
            const t = (i % 20) / 20;
            polyPts.push(new THREE.Vector3(verts[idx].x + t * (verts[nextIdx].x - verts[idx].x), verts[idx].y + t * (verts[nextIdx].y - verts[idx].y), 0.02));
          }
          push(new THREE.Line(new THREE.BufferGeometry().setFromPoints(polyPts), new THREE.LineBasicMaterial({ color: 0x22d3ee, linewidth: 3 })));
        }

        // Corner points
        cornerList.forEach(({ x, y }) => {
          const dot = push(new THREE.Mesh(new THREE.SphereGeometry(0.15, 12, 12), new THREE.MeshBasicMaterial({ color: 0xfbbf24 })));
          dot.position.set(x, y, 0.05);
          const zVal = p * x + q * y;
          addLabel(mkSprite(`(${x.toFixed(1)},${y.toFixed(1)}) Z=${zVal.toFixed(1)}`, "#fbbf24", new THREE.Vector3(x + 0.3, y + 0.4, 0), 0.6));
        });

        // Sliding objective line: px + qy = isoLevel
        if (isoLevel > 0 && p !== 0 && q !== 0) {
          const ox1 = 0, oy1 = isoLevel / q;
          const ox2 = isoLevel / p, oy2 = 0;
          push(new THREE.Line(
            new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(ox1, oy1, 0), new THREE.Vector3(ox2, oy2, 0)]),
            new THREE.LineBasicMaterial({ color: 0xf97316, linewidth: 2 }),
          ));
        }

        addLabel(mkSprite(`Max Z = ${p}x + ${q}y  |  Slide orange line to farthest corner`, "#a78bfa", new THREE.Vector3(0, 8, 0), 0.8));
      };

      update();
      labelSprites.forEach((s) => (s.visible = showLabels));

      const animate = () => {
        frameId = requestAnimationFrame(animate);
        controls.update();
        renderer.render(scene, camera);
      };
      animate();

      const handleResize = () => {
        if (!container) return;
        camera.aspect = container.clientWidth / container.clientHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(container.clientWidth, container.clientHeight);
      };
      window.addEventListener("resize", handleResize);
      // Re-fit the canvas whenever the container itself resizes (screen fit)
      const resizeObserver = new ResizeObserver(() => handleResize());
      resizeObserver.observe(container);

      return () => {
        cancelAnimationFrame(frameId);
        window.removeEventListener("resize", handleResize);
        resizeObserver?.disconnect();
        if (renderer.domElement.parentNode) renderer.domElement.parentNode.removeChild(renderer.domElement);
        meshes.forEach((m) => {
          scene.remove(m);
          if (m instanceof THREE.Mesh) { m.geometry?.dispose(); const mat = m.material; if (Array.isArray(mat)) mat.forEach((x) => x.dispose()); else (Array.isArray(mat) ? mat : [mat]).forEach((x) => x.dispose()); }
          else if (m instanceof THREE.Line) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Sprite) { const sm = m.material; sm.map?.dispose?.(); sm.dispose(); }
        });
        renderer.dispose();
        controls.dispose?.();
      };
    };

    const cleanup = init();
    return () => { cleanup.then((d) => d?.()); };
  }, [a1, b1, c1, a2, b2, c2, p, q, isoLevel, ix, iy, xAxisCorner, yAxisCorner, hasRegion, cornerList, isWebGL, runId, showLabels]);

  if (!isWebGL) {
    return <WebGLFallback title="LPP Graphical Method" description="Feasible region optimizer — requires WebGL." />;
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex flex-wrap items-center gap-2">
          <span>LPP — Graphical Method</span>
          <span className="text-xs text-muted-foreground font-normal">Slide objective line to find optimum</span>
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <ScenePresets presets={presets} />
          <div className="flex flex-wrap items-center gap-2">
            <button onClick={() => setShowLabels((v) => !v)} className={`px-2.5 py-1 rounded-md text-xs font-medium border transition-colors ${showLabels ? "border-amber-500/50 bg-amber-500/10 text-amber-300" : "border-border bg-muted/40 text-muted-foreground"}`}>Labels</button>
            <button onClick={resetAll} className="px-2.5 py-1 rounded-md text-xs font-medium border border-border bg-muted/40 text-muted-foreground hover:bg-muted/70 transition-colors" title="Reset to defaults">Reset</button>
          </div>
        </div>

        <CollapsibleControls label="Constraints">
          <div className="flex flex-wrap gap-2 mt-2">
            <div className="w-10"><Label className="text-xs text-muted-foreground">a₁:</Label><Input type="number" step="0.5" value={a1} onChange={(e) => setA1(Number(e.target.value))} className="mt-1" /></div>
            <div className="w-10"><Label className="text-xs text-muted-foreground">b₁:</Label><Input type="number" step="0.5" value={b1} onChange={(e) => setB1(Number(e.target.value))} className="mt-1" /></div>
            <div className="w-10"><Label className="text-xs text-muted-foreground">c₁:</Label><Input type="number" step="0.5" value={c1} onChange={(e) => setC1(Number(e.target.value))} className="mt-1" /></div>
            <div className="w-10"><Label className="text-xs text-muted-foreground">a₂:</Label><Input type="number" step="0.5" value={a2} onChange={(e) => setA2(Number(e.target.value))} className="mt-1" /></div>
            <div className="w-10"><Label className="text-xs text-muted-foreground">b₂:</Label><Input type="number" step="0.5" value={b2} onChange={(e) => setB2(Number(e.target.value))} className="mt-1" /></div>
            <div className="w-10"><Label className="text-xs text-muted-foreground">c₂:</Label><Input type="number" step="0.5" value={c2} onChange={(e) => setC2(Number(e.target.value))} className="mt-1" /></div>
          </div>
        </CollapsibleControls>

        <CollapsibleControls label="Objective Z = px + qy">
          <div className="flex gap-2 mt-2">
            <div className="w-10"><Label className="text-xs text-muted-foreground">p:</Label><Input type="number" step="0.5" value={p} onChange={(e) => setP(Number(e.target.value))} className="mt-1" /></div>
            <div className="w-10"><Label className="text-xs text-muted-foreground">q:</Label><Input type="number" step="0.5" value={q} onChange={(e) => setQ(Number(e.target.value))} className="mt-1" /></div>
          </div>
        </CollapsibleControls>

        <CollapsibleControls label="Objective Line Level">
          <input type="range" min={0} max={50} step={1} value={isoLevel} onChange={(e) => setIsoLevel(Number(e.target.value))} className="w-full mt-1" />
          <p className="text-xs font-mono text-primary mt-1">px + qy = {isoLevel}</p>
        </CollapsibleControls>

        <div ref={containerRef} className="relative h-[clamp(320px,60vh,640px)] w-full overflow-hidden rounded-lg border border-border bg-slate-900">
          <VizToolbar targetRef={vizTargetRef} />
        </div>

        <ReadoutGrid
          items={[
            { label: "Objective function", value: `Z = ${p}x + ${q}y` },
            { label: "Objective line at", value: isoLevel > 0 ? `Z = ${isoLevel}` : "hidden (0)" },
            { label: "Z at x-axis corner", value: Number.isFinite(xAxisCorner) ? zAt(xAxisCorner, 0).toFixed(1) : "unbounded" },
            { label: "Z at intersection", value: hasRegion ? zAt(ix, iy).toFixed(1) : "—" },
            { label: "Z at y-axis corner", value: Number.isFinite(yAxisCorner) ? zAt(0, yAxisCorner).toFixed(1) : "unbounded" },
            { label: "Max Z", value: bestCorner ? `${zAt(bestCorner.x, bestCorner.y).toFixed(1)} at (${bestCorner.x.toFixed(1)}, ${bestCorner.y.toFixed(1)})` : "—", highlight: true },
          ]}
        />

        <div className="rounded-lg border border-amber-500/30 bg-amber-500/5 p-4">
          <p className="text-xs font-semibold uppercase tracking-wide text-amber-400">Corner Point Method</p>
          <div className="mt-2 space-y-1.5 text-xs text-muted-foreground">
            <p><strong className="text-foreground">Step 1:</strong> Plot constraints and identify the feasible region.</p>
            <p><strong className="text-foreground">Step 2:</strong> Find all corner (vertex) points of the feasible region.</p>
            <p><strong className="text-foreground">Step 3:</strong> Evaluate Z = px + qy at each corner point.</p>
            <p><strong className="text-foreground">Step 4:</strong> The maximum/minimum value is the optimal solution.</p>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { useRef, useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { CollapsibleControls } from "@/components/lab/collapsible-controls";
import { isWebGLAvailable } from "@/lib/webgl";
import { WebGLFallback } from "@/components/lab/webgl-fallback";
import { VizToolbar, type VizTarget } from "@/components/viz/viz-toolbar";
import { ScenePresets, ReadoutGrid, type ScenePreset } from "@/components/lab/scene-interactivity";
import * as THREE from "three";

/* ============================================================
   Mean, Variance & SD of Random Variable — NEB Probability (Maths 12)
   Interactive distribution showing how mean and spread behave.
   ============================================================ */

function mkSprite(text: string, color: string, pos: THREE.Vector3, scale = 1.0): THREE.Sprite {
  const canvas = document.createElement("canvas");
  canvas.width = 512;
  canvas.height = 96;
  const ctx = canvas.getContext("2d")!;
  ctx.fillStyle = "rgba(15, 23, 42, 0.9)";
  ctx.fillRect(4, 4, 504, 88);
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.strokeRect(4, 4, 504, 88);
  ctx.font = "bold 28px monospace";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillStyle = color;
  ctx.fillText(text, 256, 48);
  const tex = new THREE.CanvasTexture(canvas);
  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: false }));
  s.position.copy(pos);
  s.scale.set(3.0 * scale, 0.56 * scale, 1);
  return s;
}

export function MeanVarianceVisual() {
  const containerRef = useRef<HTMLDivElement>(null);
  const vizTargetRef = useRef<VizTarget>({});
  const [n, setN] = useState(10);
  const [p, setP] = useState(0.4);
  const [isWebGL] = useState(() => isWebGLAvailable());
  const [showLabels, setShowLabels] = useState(true);
  const [runId, setRunId] = useState(0);

  const presets: ScenePreset[] = [
    { name: "Balanced · n = 10, p = 0.5", hint: "σ² = 2.5, symmetric spread", apply: () => { setN(10); setP(0.5); setRunId((r) => r + 1); } },
    { name: "Default · n = 10, p = 0.4", hint: "μ = 4, σ ≈ 1.55", apply: () => { setN(10); setP(0.4); setRunId((r) => r + 1); } },
    { name: "Wide spread · n = 20, p = 0.5", hint: "σ² = 5 — more trials widen the SD band", apply: () => { setN(20); setP(0.5); setRunId((r) => r + 1); } },
  ];

  const resetAll = () => {
    setN(10);
    setP(0.4);
    setShowLabels(true);
    setRunId((r) => r + 1);
  };

  const factorial = (x: number): number => x <= 1 ? 1 : x * factorial(x - 1);
  const pmf = (k: number) => factorial(n) / (factorial(k) * factorial(n - k)) * Math.pow(p, k) * Math.pow(1 - p, n - k);
  const mean = n * p;
  const variance = n * p * (1 - p);
  const sd = Math.sqrt(variance);
  const ex2 = variance + mean * mean; // E[X²] = Var(X) + (E[X])²

  useEffect(() => {
    const container = containerRef.current;
    if (!container || !isWebGL) return;

    let scene: THREE.Scene, camera: THREE.PerspectiveCamera, renderer: THREE.WebGLRenderer;
    let controls: any, frameId: number;
    const meshes: THREE.Object3D[] = [];
    const labelSprites: THREE.Sprite[] = [];

    const init = async () => {
      const { OrbitControls } = await import("three/addons/controls/OrbitControls.js");

      scene = new THREE.Scene();
      scene.background = new THREE.Color(0x0f172a);
      camera = new THREE.PerspectiveCamera(50, container.clientWidth / container.clientHeight, 0.1, 100);
      camera.position.set(0, 6, 12);
      camera.lookAt(0, 1, 0);

      renderer = new THREE.WebGLRenderer({ antialias: true });
      renderer.setSize(container.clientWidth, container.clientHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      container.appendChild(renderer.domElement);

      controls = new OrbitControls(camera, renderer.domElement);
      controls.enableDamping = true;
      vizTargetRef.current = { controls, el: container, canvasEl: renderer.domElement, setLabels: (on: boolean) => labelSprites.forEach((s) => (s.visible = on)) };
      controls.autoRotate = false;
      controls.maxPolarAngle = Math.PI / 2.2;

      scene.add(new THREE.AmbientLight(0xffffff, 0.8));

      const push = <T extends THREE.Object3D>(o: T): T => { scene.add(o); meshes.push(o); if (o instanceof THREE.Sprite) labelSprites.push(o); return o; };

      push(new THREE.GridHelper(20, 20, 0x334155, 0x1e293b));

      const update = () => {
        while (meshes.length > 50) {
          const m = meshes.pop()!;
          scene.remove(m);
          if (m instanceof THREE.Mesh) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Sprite) { (m.material as THREE.SpriteMaterial).map?.dispose?.(); m.material.dispose(); }
        }

        const maxProb = Math.max(...Array.from({ length: n + 1 }, (_, k) => pmf(k)));
        const colors = [0xef4444, 0xf97316, 0xfbbf24, 0x22c55e, 0x3b82f6, 0x8b5cf6];

        for (let k = 0; k <= n; k++) {
          const prob = pmf(k);
          const barH = (prob / maxProb) * 3;
          const bar = push(new THREE.Mesh(
            new THREE.BoxGeometry(0.6, barH, 0.6),
            new THREE.MeshBasicMaterial({ color: colors[k % colors.length] }),
          ));
          bar.position.set((k - n / 2) * 1.0, barH / 2, 0);
        }

        // Mean line
        const meanX = (mean - n / 2) * 1.0;
        push(new THREE.Line(
          new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(meanX, 0, 0), new THREE.Vector3(meanX, 4, 0)]),
          new THREE.LineBasicMaterial({ color: 0xef4444, linewidth: 3 }),
        ));
        push(mkSprite(`μ = ${mean.toFixed(1)}`, "#f87171", new THREE.Vector3(meanX, 4.3, 0), 0.7));

        // SD band
        const sdLeft = (mean - sd - n / 2) * 1.0;
        const sdRight = (mean + sd - n / 2) * 1.0;
        push(new THREE.Line(
          new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(sdLeft, 0, 0), new THREE.Vector3(sdRight, 0, 0)]),
          new THREE.LineBasicMaterial({ color: 0xfbbf24, linewidth: 2 }),
        ));
        push(mkSprite(`μ ± σ = [${(mean - sd).toFixed(1)}, ${(mean + sd).toFixed(1)}]`, "#fbbf24", new THREE.Vector3(meanX, -1.5, 0), 0.75));

        // Stats panel
        push(mkSprite(`E[X] = np = ${mean.toFixed(2)}   Var(X) = np(1-p) = ${variance.toFixed(2)}   σ = ${sd.toFixed(2)}`, "#a78bfa", new THREE.Vector3(0, -3, 0), 0.8));
      };

      update();
      labelSprites.forEach((s) => (s.visible = showLabels));

      const animate = () => {
        frameId = requestAnimationFrame(animate);
        controls.update();
        renderer.render(scene, camera);
      };
      animate();

      const handleResize = () => {
        if (!container) return;
        camera.aspect = container.clientWidth / container.clientHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(container.clientWidth, container.clientHeight);
      };
      window.addEventListener("resize", handleResize);
      // Re-fit the canvas whenever the container itself resizes (screen fit)
      const resizeObserver = new ResizeObserver(() => handleResize());
      resizeObserver.observe(container);

      return () => {
        cancelAnimationFrame(frameId);
        window.removeEventListener("resize", handleResize);
        resizeObserver?.disconnect();
        if (renderer.domElement.parentNode) renderer.domElement.parentNode.removeChild(renderer.domElement);
        meshes.forEach((m) => {
          scene.remove(m);
          if (m instanceof THREE.Mesh) { m.geometry?.dispose(); const mat = m.material; if (Array.isArray(mat)) mat.forEach((x) => x.dispose()); else (Array.isArray(mat) ? mat : [mat]).forEach((x) => x.dispose()); }
          else if (m instanceof THREE.Sprite) { const sm = m.material; sm.map?.dispose?.(); sm.dispose(); }
        });
        renderer.dispose();
        controls.dispose?.();
      };
    };

    const cleanup = init();
    return () => { cleanup.then((d) => d?.()); };
  }, [n, p, isWebGL, runId, showLabels]);

  if (!isWebGL) {
    return <WebGLFallback title="Mean & Variance" description="Distribution statistics — requires WebGL." />;
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex flex-wrap items-center gap-2">
          <span>Mean, Variance &amp; Standard Deviation</span>
          <span className="text-xs text-muted-foreground font-normal">Binomial distribution properties</span>
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <ScenePresets presets={presets} />
          <div className="flex flex-wrap items-center gap-2">
            <button onClick={() => setShowLabels((v) => !v)} className={`px-2.5 py-1 rounded-md text-xs font-medium border transition-colors ${showLabels ? "border-amber-500/50 bg-amber-500/10 text-amber-300" : "border-border bg-muted/40 text-muted-foreground"}`}>Labels</button>
            <button onClick={resetAll} className="px-2.5 py-1 rounded-md text-xs font-medium border border-border bg-muted/40 text-muted-foreground hover:bg-muted/70 transition-colors" title="Reset to defaults">Reset</button>
          </div>
        </div>

        <CollapsibleControls label="Parameters (Binomial B(n,p))">
          <div className="flex gap-3 mt-2">
            <div className="w-16"><Label className="text-xs text-muted-foreground">n:</Label><Input type="number" step="1" min={3} max={20} value={n} onChange={(e) => setN(Number(e.target.value))} className="mt-1" /></div>
            <div className="w-16"><Label className="text-xs text-muted-foreground">p:</Label><Input type="number" step="0.05" min={0} max={1} value={p} onChange={(e) => setP(Number(e.target.value))} className="mt-1" /></div>
          </div>
        </CollapsibleControls>

        <div ref={containerRef} className="relative h-[clamp(320px,60vh,640px)] w-full overflow-hidden rounded-lg border border-border bg-slate-900">
          <VizToolbar targetRef={vizTargetRef} />
        </div>

        <ReadoutGrid
          items={[
            { label: "E[X] = np", value: mean.toFixed(2), highlight: true },
            { label: "Var(X) = np(1−p)", value: variance.toFixed(2) },
            { label: "σ = √Var(X)", value: sd.toFixed(2) },
            { label: "E[X²] = Var + μ²", value: ex2.toFixed(2) },
            { label: "μ ± σ interval", value: `[${(mean - sd).toFixed(2)}, ${(mean + sd).toFixed(2)}]` },
            { label: "Property", value: "Var(aX+b) = a²·Var(X)" },
          ]}
        />

        <div className="rounded-lg border border-amber-500/30 bg-amber-500/5 p-4">
          <p className="text-xs font-semibold uppercase tracking-wide text-amber-400">Formulas</p>
          <div className="mt-2 space-y-1.5 text-xs text-muted-foreground">
            <p><strong className="text-foreground">Mean:</strong> E[X] = μ = np</p>
            <p><strong className="text-foreground">Variance:</strong> Var(X) = σ² = np(1 − p)</p>
            <p><strong className="text-foreground">Standard Deviation:</strong> σ = √(np(1−p))</p>
            <p><strong className="text-foreground">Property:</strong> σ² = E[X²] − (E[X])²</p>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { useRef, useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { CollapsibleControls } from "@/components/lab/collapsible-controls";
import { isWebGLAvailable } from "@/lib/webgl";
import { WebGLFallback } from "@/components/lab/webgl-fallback";
import { VizToolbar, type VizTarget } from "@/components/viz/viz-toolbar";
import {
  ScenePresets,
  PlaybackBar,
  ReadoutGrid,
  type ScenePreset,
} from "@/components/lab/scene-interactivity";
import * as THREE from "three";
import { LiveLeaderLine } from "@/components/lab/leader-lines-3d";

function mkSprite(text: string, color: string, pos: THREE.Vector3, scale = 1.0): THREE.Sprite {
  const canvas = document.createElement("canvas");
  canvas.width = 512;
  canvas.height = 96;
  const ctx = canvas.getContext("2d")!;
  ctx.fillStyle = "rgba(15, 23, 42, 0.9)";
  ctx.fillRect(4, 4, 504, 88);
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.strokeRect(4, 4, 504, 88);
  ctx.font = "bold 32px monospace";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillStyle = color;
  ctx.fillText(text, 256, 48);
  const tex = new THREE.CanvasTexture(canvas);
  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: false }));
  s.position.copy(pos);
  s.scale.set(3.0 * scale, 0.56 * scale, 1);
  return s;
}

const nuclei = {
  "h1": { protons: 1, neutrons: 0, label: "¹H (Protium)", color: 0xef4444, bindingMeV: 0, massDefectU: 0 },
  "he4": { protons: 2, neutrons: 2, label: "⁴He", color: 0x3b82f6, bindingMeV: 28.3, massDefectU: 0.0304 },
  "c12": { protons: 6, neutrons: 6, label: "¹²C", color: 0x22c55e, bindingMeV: 92.2, massDefectU: 0.0989 },
  "u238": { protons: 92, neutrons: 146, label: "²³⁸U", color: 0xf97316, bindingMeV: 1801.6, massDefectU: 1.9342 },
};

export function NuclearPhysicsVisual() {
  const containerRef = useRef<HTMLDivElement>(null);
  const vizTargetRef = useRef<VizTarget>({});
  const [isotope, setIsotope] = useState<"h1" | "he4" | "c12" | "u238">("u238");
  const [isWebGL] = useState(() => isWebGLAvailable());
  const [animating, setAnimating] = useState(true);
  const [speed, setSpeed] = useState(1);
  const [showLabels, setShowLabels] = useState(true);
  const [runId, setRunId] = useState(0);
  // Speed lives in a ref so changing it never tears down the WebGL scene.
  const speedRef = useRef(1);
  speedRef.current = speed;

  const nuc = nuclei[isotope];
  const massNumber = nuc.protons + nuc.neutrons;
  const bePerNucleon = massNumber > 0 ? nuc.bindingMeV / massNumber : 0;

  const DEFAULTS = { isotope: "u238" as const };
  const presets: ScenePreset[] = [
    {
      name: "¹H Protium",
      hint: "A lone proton — no nucleon pairs, so zero binding energy.",
      apply: () => { setIsotope("h1"); setRunId((r) => r + 1); },
    },
    {
      name: "⁴He alpha",
      hint: "Doubly magic and exceptionally tightly bound — 7.07 MeV per nucleon.",
      apply: () => { setIsotope("he4"); setRunId((r) => r + 1); },
    },
    {
      name: "¹²C carbon",
      hint: "Mid-light nucleus near the peak of the binding-energy curve.",
      apply: () => { setIsotope("c12"); setRunId((r) => r + 1); },
    },
    {
      name: "²³⁸U uranium",
      hint: "Heavy nucleus — lower BE/nucleon makes fission energetically favorable.",
      apply: () => { setIsotope("u238"); setRunId((r) => r + 1); },
    },
  ];

  const resetAll = () => {
    setIsotope(DEFAULTS.isotope);
    setSpeed(1);
    setShowLabels(true);
    setAnimating(true);
    setRunId((r) => r + 1);
  };

  useEffect(() => {
    const container = containerRef.current;
    if (!container || !isWebGL) return;

    let scene: THREE.Scene, camera: THREE.PerspectiveCamera, renderer: THREE.WebGLRenderer;
    let controls: any, frameId: number;
    const meshes: THREE.Object3D[] = [];
    const labelSprites: THREE.Sprite[] = [];
    let rotAngle = 0;

    const init = async () => {
      const { OrbitControls } = await import("three/addons/controls/OrbitControls.js");

      scene = new THREE.Scene();
      scene.background = new THREE.Color(0x0f172a);
      camera = new THREE.PerspectiveCamera(50, container.clientWidth / container.clientHeight, 0.1, 100);
      camera.position.set(0, 0, 10);

      renderer = new THREE.WebGLRenderer({ antialias: true });
      renderer.setSize(container.clientWidth, container.clientHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      container.appendChild(renderer.domElement);

      controls = new OrbitControls(camera, renderer.domElement);
      controls.enableDamping = true;
      controls.autoRotate = animating;
      controls.autoRotateSpeed = 1.0 * speed;
      controls.minDistance = 3;
      controls.maxDistance = 20;
      vizTargetRef.current = {
        controls,
        el: container,
        canvasEl: renderer.domElement,
        setLabels: (on: boolean) => labelSprites.forEach((s) => (s.visible = on)),
      };

      scene.add(new THREE.AmbientLight(0xffffff, 0.7));
      const dir = new THREE.DirectionalLight(0xffffff, 1.0);
      dir.position.set(5, 10, 5);
      scene.add(dir);

      const push = <T extends THREE.Object3D>(o: T): T => { scene.add(o); meshes.push(o); return o; };
      const addLabel = (s: THREE.Sprite): THREE.Sprite => { push(s); labelSprites.push(s); return s; };

      const nucleus = nuclei[isotope];
      const totalParticles = nucleus.protons + nucleus.neutrons;
      const nProtons = nucleus.protons;
      const nNeutrons = nucleus.neutrons;

      // Nucleus cluster
      const nucleons: THREE.Mesh[] = [];
      const positions: THREE.Vector3[] = [];
      const rand = (seed: number) => {
        const x = Math.sin(seed) * 10000;
        return x - Math.floor(x);
      };
      for (let i = 0; i < Math.min(totalParticles, 30); i++) {
        const angle = i * 2.399963225 + rand(i * 7) * 0.5;
        const r = 0.5 + rand(i * 13) * 1.5;
        const z = (rand(i * 17) - 0.5) * 2;
        positions.push(new THREE.Vector3(r * Math.cos(angle), r * Math.sin(angle), z));
      }

      positions.forEach((pos, i) => {
        const isProton = i < nProtons;
        const nucleon = push(new THREE.Mesh(
          new THREE.SphereGeometry(0.25, 12, 12),
          new THREE.MeshBasicMaterial({ color: isProton ? 0xef4444 : 0x3b82f6 }),
        )) as THREE.Mesh;
        nucleon.position.copy(pos);
        nucleons.push(nucleon);
      });

      // Proton count label with long arrow
      const pLabelPos = new THREE.Vector3(3, 2.5, 0);
      const pTarget = new THREE.Vector3(0, 0, 0);
      const pDir = pTarget.clone().sub(pLabelPos).normalize();
      push(new LiveLeaderLine(pDir, pLabelPos, pLabelPos.distanceTo(pTarget) * 0.9, 0xef4444, 0.2, 0.12));
      addLabel(mkSprite(`Protons (Z) = ${nProtons}`, "#ef4444", pLabelPos.clone().sub(pDir.multiplyScalar(0.5)), 0.8));

      // Neutron count label with long arrow
      const nLabelPos = new THREE.Vector3(-3, 2.5, 0);
      const nTarget = new THREE.Vector3(0, 0, 0);
      const nDir = nTarget.clone().sub(nLabelPos).normalize();
      push(new LiveLeaderLine(nDir, nLabelPos, nLabelPos.distanceTo(nTarget) * 0.9, 0x3b82f6, 0.2, 0.12));
      addLabel(mkSprite(`Neutrons (N) = ${nNeutrons}`, "#3b82f6", nLabelPos.clone().sub(nDir.multiplyScalar(0.5)), 0.8));

      // Isotope label
      const isoLabelPos = new THREE.Vector3(0, -3, 0);
      const isoTarget = new THREE.Vector3(0, 0, 0);
      const isoDir = isoTarget.clone().sub(isoLabelPos).normalize();
      push(new LiveLeaderLine(isoDir, isoLabelPos, isoLabelPos.distanceTo(isoTarget) * 0.9, 0xfbbf24, 0.15, 0.1));
      addLabel(mkSprite(nucleus.label, "#fbbf24", isoLabelPos.clone().sub(isoDir.multiplyScalar(0.5)), 0.85));

      // Mass number label
      const ALabelPos = new THREE.Vector3(-3, -2.5, 0);
      const ATarget = new THREE.Vector3(0, 0, 0);
      const ADir = ATarget.clone().sub(ALabelPos).normalize();
      push(new LiveLeaderLine(ADir, ALabelPos, ALabelPos.distanceTo(ATarget) * 0.9, 0xa78bfa, 0.15, 0.1));
      addLabel(mkSprite(`Mass # (A) = ${totalParticles}`, "#a78bfa", ALabelPos.clone().sub(ADir.multiplyScalar(0.5)), 0.75));

      // Nuclear force range indicator
      const rfLabelPos = new THREE.Vector3(0, 3.5, 0);
      const rfTarget = new THREE.Vector3(0.8, 0.5, 0);
      const rfDir = rfTarget.clone().sub(rfLabelPos).normalize();
      push(new LiveLeaderLine(rfDir, rfLabelPos, rfLabelPos.distanceTo(rfTarget) * 0.9, 0x34d399, 0.15, 0.1));
      addLabel(mkSprite("Nuclear force (short range)", "#34d399", rfLabelPos.clone().sub(rfDir.multiplyScalar(0.5)), 0.7));

      const update = () => {
        while (meshes.length > 50) {
          const m = meshes.pop()!;
          scene.remove(m);
          if (m instanceof THREE.Mesh) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Line) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Sprite) { (m.material as THREE.SpriteMaterial).map?.dispose?.(); m.material.dispose(); }
          else if (m instanceof THREE.ArrowHelper) m.dispose();
        }
      };
      update();
      labelSprites.forEach((s) => (s.visible = showLabels));

      const animate = () => {
        frameId = requestAnimationFrame(animate);
        controls.update();
        if (animating) {
          rotAngle += 0.005 * speedRef.current;
          nucleons.forEach((n, i) => {
            const base = positions[i];
            n.position.set(
              base.x * Math.cos(rotAngle) - base.z * Math.sin(rotAngle),
              base.y,
              base.x * Math.sin(rotAngle) + base.z * Math.cos(rotAngle)
            );
          });
        }
        renderer.render(scene, camera);
      };
      animate();

      const handleResize = () => {
        if (!container) return;
        camera.aspect = container.clientWidth / container.clientHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(container.clientWidth, container.clientHeight);
      };
      window.addEventListener("resize", handleResize);
      // Re-fit the canvas whenever the container itself resizes (screen fit)
      const resizeObserver = new ResizeObserver(() => handleResize());
      resizeObserver.observe(container);

      return () => {
        cancelAnimationFrame(frameId);
        window.removeEventListener("resize", handleResize);
        resizeObserver?.disconnect();
        if (renderer.domElement.parentNode) renderer.domElement.parentNode.removeChild(renderer.domElement);
        meshes.forEach((m) => {
          scene.remove(m);
          if (m instanceof THREE.Mesh) { m.geometry?.dispose(); const mat = m.material; if (Array.isArray(mat)) mat.forEach((x) => x.dispose()); else (Array.isArray(mat) ? mat : [mat]).forEach((x) => x.dispose()); }
          else if (m instanceof THREE.Line) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Sprite) { const sm = m.material; sm.map?.dispose?.(); sm.dispose(); }
          else if (m instanceof THREE.ArrowHelper) m.dispose();
        });
        renderer.dispose();
        controls.dispose?.();
      };
    };

    const cleanup = init();
    return () => { cleanup.then((d) => d?.()); };
  }, [isotope, isWebGL, runId, animating, showLabels]);

  if (!isWebGL) {
    return <WebGLFallback title="Nuclear Physics" description="Nucleus with proton/neutron labels." />;
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex flex-wrap items-center gap-2">
          <span>Nuclear Physics — Nucleus Structure</span>
          <span className="text-xs text-muted-foreground font-normal">Drag to rotate · Scroll to zoom</span>
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <CollapsibleControls label="Select Isotope">
          <div className="flex flex-wrap gap-2 mt-2">
            {(["h1", "he4", "c12", "u238"] as const).map((iso) => (
              <button
                key={iso}
                onClick={() => setIsotope(iso)}
                className={`px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${
                  isotope === iso ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground hover:bg-muted/80"
                }`}
              >
                {nuclei[iso].label}
              </button>
            ))}
          </div>
        </CollapsibleControls>

        <div className="flex flex-wrap items-center justify-between gap-3">
          <PlaybackBar
            playing={animating}
            onPlayToggle={() => setAnimating(!animating)}
            speed={speed}
            onSpeedChange={setSpeed}
            onReset={resetAll}
          />
          <div className="flex flex-wrap items-center gap-2">
            <button
              onClick={() => setShowLabels((v) => !v)}
              className={`px-2.5 py-1 rounded-md text-xs font-medium border transition-colors ${showLabels ? "border-primary/50 bg-primary/10 text-primary" : "border-border bg-muted/40 text-muted-foreground"}`}
            >
              Labels
            </button>
          </div>
        </div>

        <ScenePresets presets={presets} />

        <div ref={containerRef} className="relative h-[clamp(320px,60vh,640px)] w-full overflow-hidden rounded-lg border border-border bg-slate-900">
          <VizToolbar targetRef={vizTargetRef} />
        </div>

        <ReadoutGrid
          items={[
            { label: "Binding energy", value: nuc.bindingMeV.toFixed(1), unit: "MeV", highlight: isotope === "he4" },
            { label: "BE / nucleon", value: bePerNucleon.toFixed(2), unit: "MeV" },
            { label: "Mass defect Δm", value: nuc.massDefectU.toFixed(4), unit: "u" },
            { label: "Nucleons A (Z+N)", value: `${massNumber} (${nuc.protons}+${nuc.neutrons})` },
          ]}
        />

        <div className="rounded-lg border border-orange-500/30 bg-orange-500/5 p-4">
          <p className="text-xs font-semibold uppercase tracking-wide text-orange-400">Key Concepts</p>
          <div className="mt-2 space-y-1.5 text-xs text-muted-foreground">
            <p><strong className="text-foreground">Nucleons:</strong> Protons (Z) + Neutrons (N) = Mass number (A).</p>
            <p><strong className="text-foreground">Nuclear force:</strong> Strong attractive force holding nucleons together (short range ~10⁻¹⁵ m).</p>
            <p><strong className="text-foreground">Binding energy:</strong> Energy needed to separate nucleus — E = Δm·c².</p>
            <p><strong className="text-foreground">Fission:</strong> Heavy nucleus splits → releases energy.</p>
            <p><strong className="text-foreground">Fusion:</strong> Light nuclei combine → releases more energy.</p>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { useRef, useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { CollapsibleControls } from "@/components/lab/collapsible-controls";
import { isWebGLAvailable } from "@/lib/webgl";
import { WebGLFallback } from "@/components/lab/webgl-fallback";
import { VizToolbar, type VizTarget } from "@/components/viz/viz-toolbar";
import { ScenePresets, ReadoutGrid, type ScenePreset } from "@/components/lab/scene-interactivity";
import * as THREE from "three";

/* ============================================================
   Poisson Distribution — NEB Probability (Maths 12)
   PMF visualization of P(X=k) = e^(-λ) · λᵏ / k!
   with parameter λ (average rate).
   ============================================================ */

function mkSprite(text: string, color: string, pos: THREE.Vector3, scale = 1.0): THREE.Sprite {
  const canvas = document.createElement("canvas");
  canvas.width = 512;
  canvas.height = 96;
  const ctx = canvas.getContext("2d")!;
  ctx.fillStyle = "rgba(15, 23, 42, 0.9)";
  ctx.fillRect(4, 4, 504, 88);
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.strokeRect(4, 4, 504, 88);
  ctx.font = "bold 28px monospace";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillStyle = color;
  ctx.fillText(text, 256, 48);
  const tex = new THREE.CanvasTexture(canvas);
  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: false }));
  s.position.copy(pos);
  s.scale.set(3.0 * scale, 0.56 * scale, 1);
  return s;
}

export function PoissonDistVisual() {
  const containerRef = useRef<HTMLDivElement>(null);
  const vizTargetRef = useRef<VizTarget>({});
  const [lambda, setLambda] = useState(3);
  const [isWebGL] = useState(() => isWebGLAvailable());
  const [showLabels, setShowLabels] = useState(true);
  const [runId, setRunId] = useState(0);

  const presets: ScenePreset[] = [
    { name: "λ = 3 · defects/metre", hint: "Default rate — μ = σ² = 3", apply: () => { setLambda(3); setRunId((r) => r + 1); } },
    { name: "Rare events · λ = 0.5", hint: "P(X = 0) = e^−0.5 ≈ 0.607 dominates", apply: () => { setLambda(0.5); setRunId((r) => r + 1); } },
    { name: "Busy hour · λ = 8", hint: "Distribution becomes near-symmetric", apply: () => { setLambda(8); setRunId((r) => r + 1); } },
  ];

  const resetAll = () => {
    setLambda(3);
    setShowLabels(true);
    setRunId((r) => r + 1);
  };

  const factorial = (x: number): number => x <= 1 ? 1 : x * factorial(x - 1);
  const pmf = (k: number) => Math.exp(-lambda) * Math.pow(lambda, k) / factorial(k);

  const mode = Math.floor(lambda);
  const peakProb = pmf(mode);
  const pZero = Math.exp(-lambda);

  useEffect(() => {
    const container = containerRef.current;
    if (!container || !isWebGL) return;

    let scene: THREE.Scene, camera: THREE.PerspectiveCamera, renderer: THREE.WebGLRenderer;
    let controls: any, frameId: number;
    const meshes: THREE.Object3D[] = [];
    const labelSprites: THREE.Sprite[] = [];

    const init = async () => {
      const { OrbitControls } = await import("three/addons/controls/OrbitControls.js");

      scene = new THREE.Scene();
      scene.background = new THREE.Color(0x0f172a);
      camera = new THREE.PerspectiveCamera(50, container.clientWidth / container.clientHeight, 0.1, 100);
      camera.position.set(0, 6, 12);
      camera.lookAt(0, 1, 0);

      renderer = new THREE.WebGLRenderer({ antialias: true });
      renderer.setSize(container.clientWidth, container.clientHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      container.appendChild(renderer.domElement);

      controls = new OrbitControls(camera, renderer.domElement);
      controls.enableDamping = true;
      vizTargetRef.current = { controls, el: container, canvasEl: renderer.domElement, setLabels: (on: boolean) => labelSprites.forEach((s) => (s.visible = on)) };
      controls.autoRotate = false;
      controls.maxPolarAngle = Math.PI / 2.2;

      scene.add(new THREE.AmbientLight(0xffffff, 0.8));

      const push = <T extends THREE.Object3D>(o: T): T => { scene.add(o); meshes.push(o); if (o instanceof THREE.Sprite) labelSprites.push(o); return o; };

      push(new THREE.GridHelper(20, 20, 0x334155, 0x1e293b));

      const update = () => {
        while (meshes.length > 50) {
          const m = meshes.pop()!;
          scene.remove(m);
          if (m instanceof THREE.Mesh) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Sprite) { (m.material as THREE.SpriteMaterial).map?.dispose?.(); m.material.dispose(); }
        }

        const maxK = Math.max(Math.ceil(lambda * 3), 15);
        const probs = Array.from({ length: maxK + 1 }, (_, k) => pmf(k));
        const maxProb = Math.max(...probs, 0.001);

        for (let k = 0; k <= maxK; k++) {
          const prob = pmf(k);
          const barH = (prob / maxProb) * 3;
          if (barH < 0.05) continue;
          const bar = push(new THREE.Mesh(
            new THREE.BoxGeometry(0.5, barH, 0.5),
            new THREE.MeshBasicMaterial({ color: 0x60a5fa }),
          ));
          bar.position.set((k - lambda) * 0.8, barH / 2, 0);
          if (barH > 0.3) {
            push(mkSprite(`${k}: ${prob.toFixed(2)}`, "#fbbf24", new THREE.Vector3((k - lambda) * 0.8, barH + 0.3, 0), 0.55));
          }
        }

        // Mean = variance = lambda line
        const meanX = (lambda - lambda) * 0.8;
        push(new THREE.Line(
          new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(meanX, 0, 0.5), new THREE.Vector3(meanX, 4, 0.5)]),
          new THREE.LineBasicMaterial({ color: 0xef4444, linewidth: 3 }),
        ));
        push(mkSprite(`μ = σ² = λ = ${lambda.toFixed(1)}`, "#f87171", new THREE.Vector3(meanX, 4.3, 0), 0.7));
        push(mkSprite("Poisson: P(X=k) = e^(-λ)·λᵏ/k!", "#a78bfa", new THREE.Vector3(0, -3.5, 0), 0.8));
      };

      update();
      labelSprites.forEach((s) => (s.visible = showLabels));

      const animate = () => {
        frameId = requestAnimationFrame(animate);
        controls.update();
        renderer.render(scene, camera);
      };
      animate();

      const handleResize = () => {
        if (!container) return;
        camera.aspect = container.clientWidth / container.clientHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(container.clientWidth, container.clientHeight);
      };
      window.addEventListener("resize", handleResize);
      // Re-fit the canvas whenever the container itself resizes (screen fit)
      const resizeObserver = new ResizeObserver(() => handleResize());
      resizeObserver.observe(container);

      return () => {
        cancelAnimationFrame(frameId);
        window.removeEventListener("resize", handleResize);
        resizeObserver?.disconnect();
        if (renderer.domElement.parentNode) renderer.domElement.parentNode.removeChild(renderer.domElement);
        meshes.forEach((m) => {
          scene.remove(m);
          if (m instanceof THREE.Mesh) { m.geometry?.dispose(); const mat = m.material; if (Array.isArray(mat)) mat.forEach((x) => x.dispose()); else (Array.isArray(mat) ? mat : [mat]).forEach((x) => x.dispose()); }
          else if (m instanceof THREE.Sprite) { const sm = m.material; sm.map?.dispose?.(); sm.dispose(); }
        });
        renderer.dispose();
        controls.dispose?.();
      };
    };

    const cleanup = init();
    return () => { cleanup.then((d) => d?.()); };
  }, [lambda, isWebGL, runId, showLabels]);

  if (!isWebGL) {
    return <WebGLFallback title="Poisson Distribution" description="Rate-based PMF visualization — requires WebGL." />;
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex flex-wrap items-center gap-2">
          <span>Poisson Distribution</span>
          <span className="text-xs text-muted-foreground font-normal">P(X=k) = e^(-λ)·λᵏ/k!</span>
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <ScenePresets presets={presets} />
          <div className="flex flex-wrap items-center gap-2">
            <button onClick={() => setShowLabels((v) => !v)} className={`px-2.5 py-1 rounded-md text-xs font-medium border transition-colors ${showLabels ? "border-sky-500/50 bg-sky-500/10 text-sky-300" : "border-border bg-muted/40 text-muted-foreground"}`}>Labels</button>
            <button onClick={resetAll} className="px-2.5 py-1 rounded-md text-xs font-medium border border-border bg-muted/40 text-muted-foreground hover:bg-muted/70 transition-colors" title="Reset to defaults">Reset</button>
          </div>
        </div>

        <CollapsibleControls label="Parameter λ (average rate)">
          <input type="range" min={0.5} max={10} step={0.5} value={lambda} onChange={(e) => setLambda(Number(e.target.value))} className="w-full mt-1" />
          <p className="text-xs font-mono text-primary mt-1">λ = {lambda.toFixed(1)}</p>
        </CollapsibleControls>

        <div ref={containerRef} className="relative h-[clamp(320px,60vh,640px)] w-full overflow-hidden rounded-lg border border-border bg-slate-900">
          <VizToolbar targetRef={vizTargetRef} />
        </div>

        <ReadoutGrid
          items={[
            { label: "E[X] = Var(X) = λ", value: lambda.toFixed(1), highlight: true },
            { label: "σ = √λ", value: Math.sqrt(lambda).toFixed(2) },
            { label: "P(X = 0) = e^−λ", value: pZero.toFixed(3) },
            { label: "Mode = ⌊λ⌋", value: mode },
            { label: `P(X = ${mode})`, value: peakProb.toFixed(3) },
            { label: "PMF", value: "P(X=k) = e^−λ·λᵏ/k!" },
          ]}
        />

        <div className="rounded-lg border border-sky-500/30 bg-sky-500/5 p-4">
          <p className="text-xs font-semibold uppercase tracking-wide text-sky-400">Poisson Distribution</p>
          <div className="mt-2 space-y-1.5 text-xs text-muted-foreground">
            <p><strong className="text-foreground">PMF:</strong> P(X = k) = e<sup>-λ</sup> · λᵏ / k!,  k = 0, 1, 2, ...</p>
            <p><strong className="text-foreground">Mean:</strong> E[X] = λ</p>
            <p><strong className="text-foreground">Variance:</strong> Var(X) = λ  (mean = variance)</p>
            <p><strong className="text-foreground">Use case:</strong> Counts of rare events in fixed interval (calls/hr, defects/meter, accidents/day)</p>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { useRef, useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { CollapsibleControls } from "@/components/lab/collapsible-controls";
import { isWebGLAvailable } from "@/lib/webgl";
import { WebGLFallback } from "@/components/lab/webgl-fallback";
import { VizToolbar, type VizTarget } from "@/components/viz/viz-toolbar";
import { ScenePresets, ReadoutGrid, type ScenePreset } from "@/components/lab/scene-interactivity";
import * as THREE from "three";
import { LiveLeaderLine } from "@/components/lab/leader-lines-3d";

/* ============================================================
   Statics — NEB Mechanics (Maths 11)
   Parallelogram law of forces, resolution of forces,
   and resultant of coplanar forces acting on a point.
   ============================================================ */

function mkSprite(text: string, color: string, pos: THREE.Vector3, scale = 1.0): THREE.Sprite {
  const canvas = document.createElement("canvas");
  canvas.width = 512;
  canvas.height = 96;
  const ctx = canvas.getContext("2d")!;
  ctx.fillStyle = "rgba(15, 23, 42, 0.9)";
  ctx.fillRect(4, 4, 504, 88);
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.strokeRect(4, 4, 504, 88);
  ctx.font = "bold 30px monospace";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillStyle = color;
  ctx.fillText(text, 256, 48);
  const tex = new THREE.CanvasTexture(canvas);
  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: false }));
  s.position.copy(pos);
  s.scale.set(3.0 * scale, 0.56 * scale, 1);
  return s;
}

export function StaticsVisual() {
  const containerRef = useRef<HTMLDivElement>(null);
  const vizTargetRef = useRef<VizTarget>({});
  const [f1, setF1] = useState({ mag: 5, angle: 30 });
  const [f2, setF2] = useState({ mag: 4, angle: 120 });
  const [isWebGL] = useState(() => isWebGLAvailable());
  const [showLabels, setShowLabels] = useState(true);
  const [runId, setRunId] = useState(0);

  // Resultant of the two coplanar concurrent forces (component method —
  // equivalent to R = √(F₁² + F₂² + 2F₁F₂cosθ) with θ the included angle)
  const rad1 = (f1.angle * Math.PI) / 180;
  const rad2 = (f2.angle * Math.PI) / 180;
  const sumX = f1.mag * Math.cos(rad1) + f2.mag * Math.cos(rad2);
  const sumY = f1.mag * Math.sin(rad1) + f2.mag * Math.sin(rad2);
  const rMag = Math.hypot(sumX, sumY);
  const rDirDeg = ((Math.atan2(sumY, sumX) * 180) / Math.PI + 360) % 360;
  const betweenRaw = (((f2.angle - f1.angle) % 360) + 360) % 360;
  const betweenDeg = betweenRaw > 180 ? 360 - betweenRaw : betweenRaw;
  const equilibrantDeg = (rDirDeg + 180) % 360;

  const presets: ScenePreset[] = [
    { name: "Perpendicular pair (5 N, 4 N)", hint: "θ = 90° — R = √(F₁² + F₂²) = √41 ≈ 6.4 N.", apply: () => { setF1({ mag: 5, angle: 0 }); setF2({ mag: 4, angle: 90 }); setRunId((r) => r + 1); } },
    { name: "Equal forces at 120°", hint: "Two equal forces inclined 120° give a resultant equal to either force.", apply: () => { setF1({ mag: 5, angle: 30 }); setF2({ mag: 5, angle: 150 }); setRunId((r) => r + 1); } },
    { name: "Equilibrium pair", hint: "Equal and opposite forces — R = 0, body stays in equilibrium.", apply: () => { setF1({ mag: 6, angle: 30 }); setF2({ mag: 6, angle: 210 }); setRunId((r) => r + 1); } },
    { name: "Same direction (max R)", hint: "θ = 0° — resultants add algebraically: R = F₁ + F₂.", apply: () => { setF1({ mag: 5, angle: 45 }); setF2({ mag: 4, angle: 45 }); setRunId((r) => r + 1); } },
  ];

  const resetAll = () => {
    setF1({ mag: 5, angle: 30 });
    setF2({ mag: 4, angle: 120 });
    setShowLabels(true);
    setRunId((r) => r + 1);
  };


  useEffect(() => {
    const container = containerRef.current;
    if (!container || !isWebGL) return;

    let scene: THREE.Scene, camera: THREE.PerspectiveCamera, renderer: THREE.WebGLRenderer;
    let controls: any, frameId: number;
    const meshes: THREE.Object3D[] = [];
    const labelSprites: THREE.Sprite[] = [];

    const init = async () => {
      const { OrbitControls } = await import("three/addons/controls/OrbitControls.js");

      scene = new THREE.Scene();
      scene.background = new THREE.Color(0x0f172a);
      camera = new THREE.PerspectiveCamera(50, container.clientWidth / container.clientHeight, 0.1, 100);
      camera.position.set(0, 0, 14);

      renderer = new THREE.WebGLRenderer({ antialias: true });
      renderer.setSize(container.clientWidth, container.clientHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      container.appendChild(renderer.domElement);

      controls = new OrbitControls(camera, renderer.domElement);
      controls.enableDamping = true;
      vizTargetRef.current = { controls, el: container, canvasEl: renderer.domElement, setLabels: (on: boolean) => labelSprites.forEach((s) => (s.visible = on)) };
      controls.autoRotate = false;

      scene.add(new THREE.AmbientLight(0xffffff, 0.8));

      const push = <T extends THREE.Object3D>(o: T): T => { scene.add(o); meshes.push(o); return o; };
      const addLabel = (s: THREE.Sprite): THREE.Sprite => { push(s); labelSprites.push(s); return s; };

      const drawArrow = (from: THREE.Vector3, to: THREE.Vector3, color: number, label: string) => {
        const dir = to.clone().sub(from).normalize();
        const len = to.distanceTo(from);
        push(new LiveLeaderLine(dir, from, len, color, 0.2, 0.12));
        const mid = from.clone().add(to).multiplyScalar(0.5);
        addLabel(mkSprite(label, `#${color.toString(16).padStart(6, "0")}`, mid.clone().add(dir.clone().multiplyScalar(len * 0.5)).add(new THREE.Vector3(0, 0.5, 0)), 0.75));
      };

      const update = () => {
        while (meshes.length > 20) {
          const m = meshes.pop()!;
          scene.remove(m);
          if (m instanceof THREE.Mesh) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Sprite) { (m.material as THREE.SpriteMaterial).map?.dispose?.(); m.material.dispose(); }
          else if (m instanceof THREE.ArrowHelper) m.dispose();
        }

        const origin = new THREE.Vector3(0, 0, 0);

        // Force vectors from origin
        const f1End = new THREE.Vector3(f1.mag * Math.cos(rad1), f1.mag * Math.sin(rad1), 0);
        const f2End = new THREE.Vector3(f2.mag * Math.cos(rad2), f2.mag * Math.sin(rad2), 0);

        drawArrow(origin, f1End, 0xef4444, `F₁=${f1.mag}`);
        drawArrow(origin, f2End, 0x3b82f6, `F₂=${f2.mag}`);

        // Parallelogram: complete with parallel sides
        const paraEnd = f1End.clone().add(f2End);
        push(new THREE.Line(new THREE.BufferGeometry().setFromPoints([f1End, paraEnd]), new THREE.LineDashedMaterial({ color: 0x3b82f6, dashSize: 0.15, gapSize: 0.1 })));
        (meshes[meshes.length - 1] as any).computeLineDistances();
        push(new THREE.Line(new THREE.BufferGeometry().setFromPoints([f2End, paraEnd]), new THREE.LineDashedMaterial({ color: 0xef4444, dashSize: 0.15, gapSize: 0.1 })));
        (meshes[meshes.length - 1] as any).computeLineDistances();

        // Resultant
        const rMagLocal = paraEnd.length();
        const rAngle = Math.atan2(paraEnd.y, paraEnd.x) * 180 / Math.PI;
        drawArrow(origin, paraEnd, 0x22d3ee, `R=${rMagLocal.toFixed(1)}`);

        // Angle labels
        addLabel(mkSprite(`θ₁=${f1.angle}°  θ₂=${f2.angle}°`, "#a78bfa", new THREE.Vector3(-5.5, 5.5, 0), 0.8));
        addLabel(mkSprite(`R = √(F₁²+F₂²+2F₁F₂cosθ)  θ = ${rAngle.toFixed(1)}°`, "#fbbf24", new THREE.Vector3(0, -5.5, 0), 0.8));
      };

      update();
      labelSprites.forEach((s) => (s.visible = showLabels));

      const animate = () => {
        frameId = requestAnimationFrame(animate);
        controls.update();
        renderer.render(scene, camera);
      };
      animate();

      const handleResize = () => {
        if (!container) return;
        camera.aspect = container.clientWidth / container.clientHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(container.clientWidth, container.clientHeight);
      };
      window.addEventListener("resize", handleResize);
      // Re-fit the canvas whenever the container itself resizes (screen fit)
      const resizeObserver = new ResizeObserver(() => handleResize());
      resizeObserver.observe(container);

      return () => {
        cancelAnimationFrame(frameId);
        window.removeEventListener("resize", handleResize);
        resizeObserver?.disconnect();
        if (renderer.domElement.parentNode) renderer.domElement.parentNode.removeChild(renderer.domElement);
        meshes.forEach((m) => {
          scene.remove(m);
          if (m instanceof THREE.Mesh) { m.geometry?.dispose(); const mat = m.material; if (Array.isArray(mat)) mat.forEach((x) => x.dispose()); else (Array.isArray(mat) ? mat : [mat]).forEach((x) => x.dispose()); }
          else if (m instanceof THREE.Line) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Sprite) { const sm = m.material; sm.map?.dispose?.(); sm.dispose(); }
          else if (m instanceof THREE.ArrowHelper) m.dispose();
        });
        renderer.dispose();
        controls.dispose?.();
      };
    };

    const cleanup = init();
    return () => { cleanup.then((d) => d?.()); };
  }, [f1, f2, isWebGL, runId, showLabels]);

  if (!isWebGL) {
    return <WebGLFallback title="Statics" description="Force parallelogram visualization — requires WebGL." />;
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex flex-wrap items-center gap-2">
          <span>Statics — Parallelogram Law of Forces</span>
          <span className="text-xs text-muted-foreground font-normal">Resultant of coplanar forces</span>
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <ScenePresets presets={presets} />
          <div className="flex flex-wrap items-center gap-2">
            <button onClick={() => setShowLabels((v) => !v)} className={`px-2.5 py-1 rounded-md text-xs font-medium border transition-colors ${showLabels ? "border-cyan-500/50 bg-cyan-500/10 text-cyan-300" : "border-border bg-muted/40 text-muted-foreground"}`}>Labels</button>
            <button onClick={resetAll} className="px-2.5 py-1 rounded-md text-xs font-medium border border-border bg-muted/40 text-muted-foreground hover:bg-muted/70 transition-colors" title="Reset to defaults">Reset</button>
          </div>
        </div>

        <CollapsibleControls label="Force F₁">
          <div className="flex gap-3 mt-2">
            <div className="w-16"><Label className="text-xs text-muted-foreground">Magnitude:</Label><Input type="number" step="0.5" value={f1.mag} onChange={(e) => setF1({ ...f1, mag: Number(e.target.value) })} className="mt-1" /></div>
            <div className="w-16"><Label className="text-xs text-muted-foreground">Angle°:</Label><Input type="number" step="5" value={f1.angle} onChange={(e) => setF1({ ...f1, angle: Number(e.target.value) })} className="mt-1" /></div>
          </div>
        </CollapsibleControls>

        <CollapsibleControls label="Force F₂">
          <div className="flex gap-3 mt-2">
            <div className="w-16"><Label className="text-xs text-muted-foreground">Magnitude:</Label><Input type="number" step="0.5" value={f2.mag} onChange={(e) => setF2({ ...f2, mag: Number(e.target.value) })} className="mt-1" /></div>
            <div className="w-16"><Label className="text-xs text-muted-foreground">Angle°:</Label><Input type="number" step="5" value={f2.angle} onChange={(e) => setF2({ ...f2, angle: Number(e.target.value) })} className="mt-1" /></div>
          </div>
        </CollapsibleControls>

        <div ref={containerRef} className="relative h-[clamp(320px,60vh,640px)] w-full overflow-hidden rounded-lg border border-border bg-slate-900">
          <VizToolbar targetRef={vizTargetRef} />
        </div>

        <ReadoutGrid
          items={[
            { label: "Included angle θ", value: betweenDeg.toFixed(0), unit: "°" },
            { label: "ΣFx (horizontal)", value: sumX.toFixed(2), unit: "N" },
            { label: "ΣFy (vertical)", value: sumY.toFixed(2), unit: "N" },
            { label: "Resultant R", value: rMag.toFixed(2), unit: "N", highlight: true },
            { label: "Direction of R", value: rDirDeg.toFixed(1), unit: "° from +x" },
            { label: "Equilibrant", value: rMag < 1e-9 ? "R = 0 — system is in equilibrium" : `${rMag.toFixed(2)} N at ${equilibrantDeg.toFixed(1)}°` },
          ]}
        />

        <div className="rounded-lg border border-cyan-500/30 bg-cyan-500/5 p-4">
          <p className="text-xs font-semibold uppercase tracking-wide text-cyan-400">Key Concepts</p>
          <div className="mt-2 space-y-1.5 text-xs text-muted-foreground">
            <p><strong className="text-foreground">Parallelogram Law:</strong> If two forces act at a point, their resultant is represented by the diagonal of the parallelogram.</p>
            <p><strong className="text-foreground">Resultant magnitude:</strong> R = √(F₁² + F₂² + 2F₁F₂cosθ), where θ is the angle between forces.</p>
            <p><strong className="text-foreground">Direction:</strong> α = tan⁻¹(F₂sinθ / (F₁ + F₂cosθ))</p>
            <p><strong className="text-foreground">Resolution:</strong> Any force F at angle θ can be resolved into Fcosθ (horizontal) and Fsinθ (vertical).</p>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { useRef, useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { CollapsibleControls } from "@/components/lab/collapsible-controls";
import { isWebGLAvailable } from "@/lib/webgl";
import { WebGLFallback } from "@/components/lab/webgl-fallback";
import { VizToolbar, type VizTarget } from "@/components/viz/viz-toolbar";
import { ScenePresets, ReadoutGrid, type ScenePreset } from "@/components/lab/scene-interactivity";
import * as THREE from "three";

/* ============================================================
   Variable Separable DE — NEB Calculus (Maths 12)
   Visualizes solving dy/dx = g(x)h(y) by separation of variables
   and phase line / direction field representation.
   ============================================================ */

function mkSprite(text: string, color: string, pos: THREE.Vector3, scale = 1.0): THREE.Sprite {
  const canvas = document.createElement("canvas");
  canvas.width = 512;
  canvas.height = 96;
  const ctx = canvas.getContext("2d")!;
  ctx.fillStyle = "rgba(15, 23, 42, 0.9)";
  ctx.fillRect(4, 4, 504, 88);
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.strokeRect(4, 4, 504, 88);
  ctx.font = "bold 28px monospace";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillStyle = color;
  ctx.fillText(text, 256, 48);
  const tex = new THREE.CanvasTexture(canvas);
  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: false }));
  s.position.copy(pos);
  s.scale.set(3.0 * scale, 0.56 * scale, 1);
  return s;
}

type SepMode = "exp" | "bell" | "logistic";

const SEP_INFO: Record<SepMode, { de: string; separated: string; general: string; particular: (kk: number, yS: number) => string; eval: (x: number, kk: number, yS: number) => number; slope: (x: number, y: number, kk: number) => number }> = {
  exp: {
    de: "dy/dx = ky",
    separated: "dy/y = k dx",
    general: "∫dy/y = ∫k dx  →  ln|y| = kx + C  →  y = Aeᵏˣ",
    particular: (kk, yS) => `y = ${yS.toFixed(1)}·e^(${kk.toFixed(1)}x)`,
    eval: (x, kk, yS) => yS * Math.exp(kk * x),
    slope: (_x, y, kk) => kk * y,
  },
  bell: {
    de: "dy/dx = kxy",
    separated: "dy/y = kx dx",
    general: "ln|y| = kx²/2 + C  →  y = Ae^(kx²/2)",
    particular: (kk, yS) => `y = ${yS.toFixed(1)}·e^(${kk.toFixed(2)}x²/2)`,
    eval: (x, kk, yS) => yS * Math.exp((kk * x * x) / 2),
    slope: (x, y, kk) => kk * x * y,
  },
  logistic: {
    de: "dy/dx = ky(1 − y)",
    separated: "dy/[y(1 − y)] = k dx",
    general: "ln|y/(1−y)| = kx + C  →  y = 1/(1 + Ae⁻ᵏˣ)",
    particular: (kk, yS) =>
      yS === 1 ? "y = 1 (equilibrium)"
      : yS > 0 ? `y = 1/(1 + ${((1 - yS) / yS).toFixed(2)}·e^(−${kk.toFixed(1)}x))`
      : "y₀ must lie in (0, 1] for the logistic plot",
    eval: (x, kk, yS) => (yS > 0 ? 1 / (1 + ((1 - yS) / yS) * Math.exp(-kk * x)) : NaN),
    slope: (_x, y, kk) => kk * y * (1 - y),
  },
};

export function VariableSeparableDEVisual() {
  const containerRef = useRef<HTMLDivElement>(null);
  const vizTargetRef = useRef<VizTarget>({});
  const [mode, setMode] = useState<SepMode>("exp");
  const [k, setK] = useState(1);
  const [y0, setY0] = useState(1);
  const [isWebGL] = useState(() => isWebGLAvailable());
  const [showLabels, setShowLabels] = useState(true);
  const [runId, setRunId] = useState(0);

  const info = SEP_INFO[mode];
  const fmtV = (v: number) => (isFinite(v) ? v.toFixed(2) : "undefined");

  const presets: ScenePreset[] = [
    { name: "dy/dx = 0.5y", hint: "Classic exponential-growth separable DE", apply: () => { setMode("exp"); setK(0.5); setY0(1); setRunId((r) => r + 1); } },
    { name: "dy/dx = 0.5xy", hint: "Bell-shaped family y = y₀e^(x²/4)", apply: () => { setMode("bell"); setK(0.5); setY0(1); setRunId((r) => r + 1); } },
    { name: "dy/dx = y(1 − y)", hint: "Logistic — partial fractions on 1/[y(1−y)]", apply: () => { setMode("logistic"); setK(1); setY0(0.2); setRunId((r) => r + 1); } },
  ];

  const resetAll = () => {
    setMode("exp");
    setK(1);
    setY0(1);
    setShowLabels(true);
    setRunId((r) => r + 1);
  };


  useEffect(() => {
    const container = containerRef.current;
    if (!container || !isWebGL) return;

    let scene: THREE.Scene, camera: THREE.PerspectiveCamera, renderer: THREE.WebGLRenderer;
    let controls: any, frameId: number;
    const meshes: THREE.Object3D[] = [];
    const labelSprites: THREE.Sprite[] = [];

    const init = async () => {
      const { OrbitControls } = await import("three/addons/controls/OrbitControls.js");

      scene = new THREE.Scene();
      scene.background = new THREE.Color(0x0f172a);
      camera = new THREE.PerspectiveCamera(50, container.clientWidth / container.clientHeight, 0.1, 100);
      camera.position.set(0, 0, 14);

      renderer = new THREE.WebGLRenderer({ antialias: true });
      renderer.setSize(container.clientWidth, container.clientHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      container.appendChild(renderer.domElement);

      controls = new OrbitControls(camera, renderer.domElement);
      controls.enableDamping = true;
      vizTargetRef.current = { controls, el: container, canvasEl: renderer.domElement, setLabels: (on: boolean) => labelSprites.forEach((s) => (s.visible = on)) };
      controls.autoRotate = false;

      scene.add(new THREE.AmbientLight(0xffffff, 0.8));

      const push = <T extends THREE.Object3D>(o: T): T => { scene.add(o); meshes.push(o); return o; };

      // Axes
      push(new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(-10, 0, 0), new THREE.Vector3(10, 0, 0)]), new THREE.LineBasicMaterial({ color: 0xef4444 })));
      push(new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, -10, 0), new THREE.Vector3(0, 10, 0)]), new THREE.LineBasicMaterial({ color: 0x22c55e })));
      push(mkSprite("x", "#ef4444", new THREE.Vector3(10.2, 0, 0.05), 0.5));
      push(mkSprite("y", "#22c55e", new THREE.Vector3(0, 10.2, 0.05), 0.5));

      // Grid
      for (let i = -10; i <= 10; i++) {
        if (i === 0) continue;
        push(new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(i, -10, 0), new THREE.Vector3(i, 10, 0)]), new THREE.LineBasicMaterial({ color: 0x1e293b })));
        push(new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(-10, i, 0), new THREE.Vector3(10, i, 0)]), new THREE.LineBasicMaterial({ color: 0x1e293b })));
      }

      const update = () => {
        while (meshes.length > 50) {
          const m = meshes.pop()!;
          scene.remove(m);
          if (m instanceof THREE.Mesh) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Line) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Sprite) { (m.material as THREE.SpriteMaterial).map?.dispose?.(); m.material.dispose(); }
        }

        // Direction field (slope ticks): dy/dx evaluated at each lattice point (x, y)
        for (let i = -8; i <= 8; i += 2) {
          for (let j = -8; j <= 8; j += 2) {
            const slope = info.slope(i, j, k);
            const tickLen = 0.25;
            const angle = isFinite(slope) ? Math.atan(slope * 0.5) : Math.PI / 2;
            const pts = [
              new THREE.Vector3(i - tickLen * Math.cos(angle), j - tickLen * Math.sin(angle), 0),
              new THREE.Vector3(i + tickLen * Math.cos(angle), j + tickLen * Math.sin(angle), 0),
            ];
            push(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), new THREE.LineBasicMaterial({ color: 0x334155 })));
          }
        }

        // Solution curves for different y0 values
        const y0Values = [y0 * 0.25, y0 * 0.5, y0, y0 * 2, y0 * 3];
        const colors = [0x94a3b8, 0x64748b, 0x22d3ee, 0xef4444, 0xa78bfa];
        y0Values.forEach((yStart, idx) => {
          const pts: THREE.Vector3[] = [];
          for (let i = 0; i <= 200; i++) {
            const x = -8 + (i / 200) * 16;
            const y = info.eval(x, k, yStart);
            if (isFinite(y) && Math.abs(y) < 15) {
              pts.push(new THREE.Vector3(x, y, 0.02));
            }
          }
          push(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), new THREE.LineBasicMaterial({ color: colors[idx], linewidth: idx === 2 ? 3 : 1.5 })));
        });

        // Initial condition marker
        const initPt = push(new THREE.Mesh(new THREE.SphereGeometry(0.2, 12, 12), new THREE.MeshBasicMaterial({ color: 0xfbbf24 })));
        initPt.position.set(0, y0, 0.05);
        labelSprites.push(push(mkSprite(`(0, ${y0.toFixed(1)})`, "#fbbf24", new THREE.Vector3(0.5, y0 + 0.5, 0), 0.7)));

        // Separation steps annotation
        labelSprites.push(push(mkSprite(`${info.de}  →  ${info.separated}  →  ${info.general}`, "#f97316", new THREE.Vector3(0, 8, 0), 0.8)));
        labelSprites.push(push(mkSprite(`Solution: ${info.particular(k, y0)}`, "#22d3ee", new THREE.Vector3(0, 7, 0), 0.8)));
      };

      update();
      labelSprites.forEach((s) => (s.visible = showLabels));

      const animate = () => {
        frameId = requestAnimationFrame(animate);
        controls.update();
        renderer.render(scene, camera);
      };
      animate();

      const handleResize = () => {
        if (!container) return;
        camera.aspect = container.clientWidth / container.clientHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(container.clientWidth, container.clientHeight);
      };
      window.addEventListener("resize", handleResize);
      // Re-fit the canvas whenever the container itself resizes (screen fit)
      const resizeObserver = new ResizeObserver(() => handleResize());
      resizeObserver.observe(container);

      return () => {
        cancelAnimationFrame(frameId);
        window.removeEventListener("resize", handleResize);
        resizeObserver?.disconnect();
        if (renderer.domElement.parentNode) renderer.domElement.parentNode.removeChild(renderer.domElement);
        meshes.forEach((m) => {
          scene.remove(m);
          if (m instanceof THREE.Mesh) { m.geometry?.dispose(); const mat = m.material; if (Array.isArray(mat)) mat.forEach((x) => x.dispose()); else (Array.isArray(mat) ? mat : [mat]).forEach((x) => x.dispose()); }
          else if (m instanceof THREE.Line) { m.geometry?.dispose(); (m.material as THREE.Material).dispose(); }
          else if (m instanceof THREE.Sprite) { const sm = m.material; sm.map?.dispose?.(); sm.dispose(); }
        });
        renderer.dispose();
        controls.dispose?.();
      };
    };

    const cleanup = init();
    return () => { cleanup.then((d) => d?.()); };
  }, [mode, k, y0, isWebGL, runId, showLabels]);

  if (!isWebGL) {
    return <WebGLFallback title="Variable Separable DE" description="Separation of variables visualization — requires WebGL." />;
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex flex-wrap items-center gap-2">
          <span>Variable Separable DE</span>
          <span className="text-xs text-muted-foreground font-normal">dy/dx = g(x)·h(y) method</span>
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <ScenePresets presets={presets} />
          <div className="flex flex-wrap items-center gap-2">
            <button onClick={() => setShowLabels((v) => !v)} className={`px-2.5 py-1 rounded-md text-xs font-medium border transition-colors ${showLabels ? "border-teal-500/50 bg-teal-500/10 text-teal-300" : "border-border bg-muted/40 text-muted-foreground"}`}>Labels</button>
            <button onClick={resetAll} className="px-2.5 py-1 rounded-md text-xs font-medium border border-border bg-muted/40 text-muted-foreground hover:bg-muted/70 transition-colors" title="Reset to defaults">Reset</button>
          </div>
        </div>

        <CollapsibleControls label="Separable Equation">
          <div className="flex flex-wrap gap-2 mt-2">
            {(["exp", "bell", "logistic"] as SepMode[]).map((m) => (
              <button
                key={m}
                onClick={() => setMode(m)}
                className={`px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${
                  mode === m ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground hover:bg-muted/80"
                }`}
              >
                {SEP_INFO[m].de}
              </button>
            ))}
          </div>
        </CollapsibleControls>

        <CollapsibleControls label={`Parameters (${info.de})`}>
          <div className="flex gap-3 mt-2">
            <div className="w-16"><Label className="text-xs text-muted-foreground">k:</Label><Input type="number" step="0.5" value={k} onChange={(e) => setK(Number(e.target.value))} className="mt-1" /></div>
            <div className="w-16"><Label className="text-xs text-muted-foreground">y₀:</Label><Input type="number" step="0.5" value={y0} onChange={(e) => setY0(Number(e.target.value))} className="mt-1" /></div>
          </div>
        </CollapsibleControls>

        <div ref={containerRef} className="relative h-[clamp(320px,60vh,640px)] w-full overflow-hidden rounded-lg border border-border bg-slate-900">
          <VizToolbar targetRef={vizTargetRef} />
        </div>

        <ReadoutGrid
          items={[
            { label: "Equation", value: info.de, highlight: true },
            { label: "Step 1 — separate", value: info.separated },
            { label: "Step 2 — integrate", value: info.general },
            { label: `Particular solution, y(0) = ${y0}`, value: info.particular(k, y0) },
            { label: "y(1)", value: fmtV(info.eval(1, k, y0)) },
            { label: "Slope at (0, y₀)", value: fmtV(info.slope(0, y0, k)) },
          ]}
        />

        <div className="rounded-lg border border-teal-500/30 bg-teal-500/5 p-4">
          <p className="text-xs font-semibold uppercase tracking-wide text-teal-400">Solution Method · {info.de}</p>
          <div className="mt-2 space-y-1.5 text-xs text-muted-foreground">
            <p><strong className="text-foreground">Step 1:</strong> Separate variables: {info.separated}</p>
            <p><strong className="text-foreground">Step 2:</strong> Integrate both sides: {info.general}</p>
            <p><strong className="text-foreground">Step 3:</strong> Apply the initial condition y(0) = y₀ to fix the constant: {info.particular(k, y0)}</p>
            <p><strong className="text-foreground">Check:</strong> the ticks are the slope field of {info.de} — every solution curve must follow them.</p>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { useRef, useEffect, useMemo, useState, useCallback } from "react";
import { useThree, useFrame } from "@react-three/fiber";
import * as THREE from "three";
import { LiveLeaderLine } from "./leader-lines-3d";

/** viewport-relative configuration */
export interface ViewportRelativeArrowConfig {
  /** Which screen-space position (0-1) the arrow target aligns to */
  screenTarget?: [number, number];
  /** How deeply into the scene (world units) the arrow sits */
  depth?: number;
  /** Base direction before viewport adjustment */
  baseDirection?: [number, number, number];
  length?: number;
  color?: string;
  headLength?: number;
  headWidth?: number;
  pulse?: boolean;
  pulseSpeed?: number;
  flowParticles?: boolean;
  particleCount?: number;
  /** If true, arrow re-orients each frame toward camera view direction */
  followCamera?: boolean;
  /** If true, arrow dynamically recalculates based on viewport changes (default: true) */
  dynamic?: boolean;
  /** World position the arrow should point toward (overrides screenTarget when set) */
  worldTarget?: [number, number, number];
  /** Callback when arrow direction changes significantly */
  onDirectionChange?: (direction: [number, number, number]) => void;
}

/**
 * Hook: computes a viewport-relative direction vector each frame.
 * Converts screen-space target + depth into world-space direction
 * that responds to camera movement/zoom.
 * 
 * This is the KEY enhancement - arrows now dynamically track viewport
 * changes rather than using fixed positions.
 */
export function useViewportRelativeDirection(config: ViewportRelativeArrowConfig) {
  const { camera, size, gl } = useThree();
  const lastCameraPos = useRef<THREE.Vector3>(new THREE.Vector3());
  const lastViewport = useRef<{width: number, height: number}>({width: 0, height: 0});
  const worldTargetRef = useRef<THREE.Vector3 | null>(null);
  
  // Sync worldTarget prop to ref for use in frame loop
  useEffect(() => {
    if (config.worldTarget) {
      worldTargetRef.current = new THREE.Vector3(...config.worldTarget);
    } else {
      worldTargetRef.current = null;
    }
  }, [config.worldTarget]);
  
  const [direction, setDirection] = useState<THREE.Vector3>(
    new THREE.Vector3(...(config.baseDirection ?? [0, 1, 0]))
  );

  const computeDirection = useCallback(() => {
    const target = config.screenTarget ?? [0.5, 0.5];
    const depth = config.depth ?? 2;
    const aspect = size.width / (size.height || 1);
    
    // NDC coordinates
    const ndcX = target[0] * 2 - 1;
    const ndcY = -(target[1] * 2 - 1);
    
    // Camera basis vectors
    const forward = new THREE.Vector3(0, 0, -1).applyQuaternion(camera.quaternion);
    const right = new THREE.Vector3(1, 0, 0).applyQuaternion(camera.quaternion);
    const up = new THREE.Vector3(0, 1, 0).applyQuaternion(camera.quaternion);
    
    // View frustum dimensions at depth (fov only exists on PerspectiveCamera)
    const cam = camera as unknown as THREE.PerspectiveCamera;
    const fov = cam.fov ?? 50;
    const viewHeight = 2 * Math.tan((fov * Math.PI) / 360) * depth;
    const viewWidth = viewHeight * aspect;
    
    // World position at screen target
    const worldX = ndcX * viewWidth / 2;
    const worldY = ndcY * viewHeight / 2;
    
    const worldPos = new THREE.Vector3()
      .copy(camera.position)
      .add(forward.clone().multiplyScalar(-depth))
      .add(right.clone().multiplyScalar(worldX))
      .add(up.clone().multiplyScalar(worldY));

    // If worldTarget is set, point toward it instead
    if (worldTargetRef.current) {
      const dirToTarget = worldTargetRef.current.clone().sub(camera.position).normalize();
      if (dirToTarget.length() > 0.001) {
        setDirection(dirToTarget);
        return;
      }
    }

    // Default: direction from camera to world position at screen target
    const dirToTarget = worldPos.sub(camera.position).normalize();
    if (dirToTarget.length() > 0.001) {
      setDirection(dirToTarget);
    }
  }, [camera, size, config.screenTarget, config.depth, config.baseDirection]);

  useFrame(() => {
    const currentPos = camera.position.clone();
    const cameraMoved = currentPos.distanceTo(lastCameraPos.current) > 0.001;
    lastCameraPos.current.copy(currentPos);
    
    // Check for viewport size changes
    const viewportChanged = size.width !== lastViewport.current.width || 
                           size.height !== lastViewport.current.height;
    lastViewport.current = { width: size.width, height: size.height };
    
    // Dynamic mode: recalculate on camera or viewport change
    const shouldRecalc = config.dynamic !== false && (cameraMoved || viewportChanged);
    
    if (shouldRecalc) {
      computeDirection();
    } else if (config.followCamera) {
      // Follow camera look direction
      const lookDir = new THREE.Vector3(0, 0, -1).applyQuaternion(camera.quaternion).normalize();
      if (lookDir.length() > 0.001) {
        setDirection(lookDir);
      }
    }
  });

  return direction;
}

/**
 * React component: viewport-relative animated arrow.
 * Automatically re-orients when camera moves/zooms.
 */
interface ViewportRelativeArrowProps {
  screenTarget?: [number, number];
  depth?: number;
  length?: number;
  color?: string;
  headLength?: number;
  headWidth?: number;
  pulse?: boolean;
  pulseSpeed?: number;
  flowParticles?: boolean;
  particleCount?: number;
  followCamera?: boolean;
  /** Enable dynamic viewport tracking (default: true) */
  dynamic?: boolean;
  /** World position the arrow should point toward */
  worldTarget?: [number, number, number];
  /** Callback for direction changes */
  onDirectionChange?: (direction: [number, number, number]) => void;
}

export function ViewportRelativeArrow({
  screenTarget = [0.5, 0.5],
  depth = 2,
  length = 1.2,
  color = "#6366f1",
  headLength = 0.15,
  headWidth = 0.1,
  pulse = true,
  pulseSpeed = 2,
  flowParticles = true,
  particleCount = 5,
  followCamera = false,
}: ViewportRelativeArrowProps) {
  const groupRef = useRef<THREE.Group>(null);
  const { camera } = useThree();
  const direction = useViewportRelativeDirection({ screenTarget, depth, followCamera, baseDirection: [0, 1, 0] });

  const arrowData = useMemo(() => {
    const origin = new THREE.Vector3(0, 0, 0);
    const arrow = new LiveLeaderLine(
      direction.clone().normalize(),
      new THREE.Vector3(0, 0, 0),
      length,
      new THREE.Color(color).getHex(),
      headLength,
      headWidth
    );
    arrow.line.material = new THREE.LineBasicMaterial({
      color: new THREE.Color(color).getHex(),
      transparent: true,
      opacity: 0.9,
    });
    arrow.cone.material = new THREE.MeshBasicMaterial({
      color: new THREE.Color(color).getHex(),
      transparent: true,
      opacity: 0.9,
    });

    const group = new THREE.Group();
    group.add(arrow);

    // Flow particles
    const particles: THREE.Mesh[] = [];
    if (flowParticles) {
      const pGeom = new THREE.SphereGeometry(0.03, 8, 8);
      for (let i = 0; i < particleCount; i++) {
        const p = new THREE.Mesh(pGeom, new THREE.MeshBasicMaterial({
          color: new THREE.Color(color).getHex(),
          transparent: true,
          opacity: 0.8,
        }));
        p.userData.offset = i / particleCount;
        group.add(p);
        particles.push(p);
      }
    }

    const update = (time: number) => {
      // Pulse
      if (pulse) {
        const scale = 1 + Math.sin(time * pulseSpeed) * 0.1;
        arrow.scale.set(scale, scale, scale);
      }
      // Flow particles
      if (flowParticles) {
        const dir = direction.clone();
        particles.forEach((p) => {
          const t = ((p.userData.offset + time * 0.5) % 1);
          p.position.copy(dir.clone().multiplyScalar(t * length));
          (p.material as THREE.MeshBasicMaterial).opacity = 0.3 + 0.5 * Math.sin(t * Math.PI);
        });
      }
    };

    const dispose = () => {
      arrow.dispose();
      particles.forEach((p) => {
        p.geometry.dispose();
        (p.material as THREE.Material).dispose();
      });
    };

    return { group, arrow, update, dispose };
  }, [direction, length, color, headLength, headWidth, pulse, pulseSpeed, flowParticles, particleCount]);

  useEffect(() => {
    return () => arrowData.dispose();
  }, [arrowData]);

  // Update direction each frame based on camera
  useFrame((_, delta) => {
    if (groupRef.current && camera) {
      arrowData.update(performance.now() / 1000);
    }
  });

  return <primitive ref={groupRef} object={arrowData.group} />;
}

"use client";

import React, { useEffect, useState, useMemo, useRef } from "react";
import {
